window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch13"]={"id":"ch13","title":"第八章 癌细胞","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"癌基因 · 抑癌基因 · 转移","modules":[{"i":0,"name":"绪论 · 概览","slides":[{"i":0,"sec":"","title":"第8章 癌细胞Cancer","notes":"1 Basic properties of a cancer cell\n基本特征\n癌细胞转移\n2 the causes of cancer\nthe genetics of cancer：\n抑癌基因与原癌基因\n3 New strategies for cancer\n【结合课本/笔记】●癌症能治疗吗？一．癌细胞的基本特征癌症是一种严重威胁人类生命安全的疾病。动物体内细胞分裂调节失控而无限增殖的细胞称为肿瘤细胞(tumorcell)。具有转移能力的肿瘤称为恶性肿瘤（malignancy）。上皮组织的恶性肿瘤称癌。\n\n【本页英文讲解】\n本页为“第8章 癌细胞(Cancer)”章节导览，列出三大主题：癌细胞的基本特征与转移(basic properties、metastasis)、癌症成因即癌症遗传学(the genetics of cancer，涉及抑癌基因与原癌基因)、以及抗癌新策略。本章对应翟中和《细胞生物学》第4版第十四章细胞增殖调控与癌细胞，为高频考点。","page":1,"level":"掌握","img":"assets/img/ch13/p001.jpg","anim":null,"fig":null,"points":null,"check":{"q":"具有转移能力的肿瘤称为？","o":["A. 良性肿瘤","B. 原位癌","C. 恶性肿瘤","D. 息肉"],"a":"C","e":"具转移能力的肿瘤称恶性肿瘤(malignancy)，上皮组织的恶性肿瘤称癌。","oe":["A. 错误：良性肿瘤通常不转移，生长局限且有包膜","B. 错误：原位癌未突破基膜，尚不具备转移能力","C. 正确：具转移能力者即恶性肿瘤，是癌细胞的恶性标志","D. 错误：息肉多为良性增生性病变，与肿瘤转移无关"]},"cards":null,"mem":"癌细胞：特征、成因(原癌/抑癌)、治疗","big":"assets/img/ch13/big/p001.jpg"},{"i":1,"sec":"","title":"smear（软涂片中异常细胞的检测）","notes":"Detection of abnormal (premalignant) cell in a Pap\n正常子宫颈鳞状上皮细胞                  子宫颈侵润前的癌细胞\n形状一致，中央一个小细                  形状各异，具大的核。\n胞核。正常的分化细胞核                  核质比显著高于正常细胞，\n质比仅为1:4-6                    可达1:1","page":2,"level":"掌握","img":"assets/img/ch13/p002.jpg","anim":null,"fig":null,"points":null,"check":{"q":"与正常子宫颈鳞状上皮细胞相比，癌变（浸润前癌）细胞最显著的形态改变是？","o":["A. 核质比显著降低","B. 细胞核变小且形状一致","C. 细胞完全失去细胞核","D. 核质比显著升高，可达1:1"],"a":"D","e":"正常细胞核质比约1:4–6，癌变细胞形状各异、核大，核质比可达1:1。","oe":["A. 错误：癌变时核质比升高而非降低，是重要诊断依据","B. 错误：癌细胞核增大且形状各异，并非变小一致","C. 错误：癌细胞仍具细胞核，并非完全失去细胞核","D. 正确：癌细胞核增大，核质比由1:4~6升至约1:1"]},"cards":null,"mem":"癌细胞核质比1:1，正常1:4-6","big":"assets/img/ch13/big/p002.jpg"},{"i":2,"sec":"","title":"Cells collected by scraping the surface of","notes":"the uterine cervix\n【中文讲解·对照课本/考点】\n考点：绪论 · 概览 ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• ◆原癌基因存在于细胞基因组中(c-onc)，是控制细胞生长和分裂的基因。编码多种类型的蛋白质---细胞生长和分裂的调控因子。癌基因是控制细胞生长和分裂的原癌基因的一种突变形式。\n\n【本页英文讲解】\n本页讲“刮取子宫颈(cervix)表面采集的细胞”，即宫颈脱落细胞学检查(巴氏涂片，Pap smear)的取材方式。通过刮取宫颈表面细胞，可在显微镜下观察形态是否异常，用于宫颈癌(cervical cancer)早期筛查。原文简短，仅说明取材方法；联系考点：癌细胞形态改变、HPV感染与宫颈癌的关系。","page":3,"level":"掌握","img":"assets/img/ch13/p003.jpg","anim":null,"fig":null,"points":null,"check":{"q":"巴氏涂片(Pap smear)检测宫颈癌的细胞取材方式是？","o":["A. 抽取外周血细胞","B. 穿刺骨髓","C. 收集尿液沉淀细胞","D. 刮取子宫颈表面细胞"],"a":"D","e":"宫颈脱落细胞学检查通过刮取子宫颈表面细胞，镜下观察形态是否异常，用于宫颈癌早期筛查。","oe":["A. 错误：外周血细胞不能反映宫颈上皮的形态改变","B. 错误：骨髓穿刺用于血液系统疾病，与宫颈筛查无关","C. 错误：尿液沉淀细胞用于泌尿系统检查，非宫颈取材","D. 正确：刮取宫颈表面细胞行涂片，是巴氏涂片取材方法"]},"cards":null,"mem":"刮宫颈表面即巴氏涂片筛癌","big":"assets/img/ch13/big/p003.jpg"},{"i":3,"sec":"","title":"1 基本特征","notes":"1）细胞生长分裂失控，体外培养无生长的接触抑制。\n2）成为“永生”细胞：自分泌生长因子激活\n3）染色体异常，正常蛋白表达谱系改变：\n正常细胞不同类型分化的细胞有相同的基因组二倍体；\n癌细胞的细胞类型与特征相近，基因组却发生不同形式的突\n变。常出现非整倍数（aneuploidy）染色体，染色体缺失或增加，\n且不凋亡。\n癌细胞往往出现一些胚胎细胞中所表达的蛋白；且具有较高\n的端粒酶活性。\n4）细胞间相互作用改变，突破细胞间识别和连接的\n控制，异常表达某些水解酶类，细胞间黏着降低。\n5）具有侵润性和扩散性","page":4,"level":"掌握","img":"assets/img/ch13/p004.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列关于癌细胞基本特征的描述，错误的是？","o":["A. 具有较高端粒酶活性而“永生”","B. 体外培养仍保留正常接触抑制","C. 常出现非整倍体等染色体异常","D. 细胞间黏着降低并具浸润性"],"a":"B","e":"癌细胞生长分裂失控，体外培养失去接触抑制；并具高端粒酶活性、染色体异常、黏着降低及浸润性。","oe":["A. 正确：癌细胞端粒酶活性高，因而具有“永生”性","B. 应选：癌细胞已失去接触抑制，故“保留接触抑制”错误","C. 正确：癌细胞常有非整倍体、染色体缺失或增加","D. 正确：癌细胞黏着降低，具浸润性和扩散性"]},"cards":null,"mem":"失控永生、染色体乱、黏着降、侵润扩散","big":"assets/img/ch13/big/p004.jpg"},{"i":4,"sec":"","title":"1) 失去生长的接触抑制","notes":"【图中英文对照】\n• contact-inhibited monolayer of normal cells —— 正常细胞的接触抑制单层\n• transformed cells lose contact inhibition —— 转化细胞失去接触抑制\n• foci of uninhibited transformed cells —— 不受抑制的转化细胞灶\n• CELL TRANSFORMATION / CELL DIVISION —— 细胞转化 / 细胞分裂\n【读图讲解】\n示意+显微照片：正常细胞单层生长受接触抑制(contact inhibition)停止分裂；细胞转化(CELL TRANSFORMATION)后失去接触抑制继续分裂，形成转化细胞灶(foci)。考点：癌细胞失去接触抑制、可多层堆积。","page":5,"level":"掌握","img":"assets/img/ch13/p005.jpg","anim":null,"fig":null,"points":["1)失去生长的接触抑制","contact-inhibitedmonolayer","transformedcells","fociofuninhibited","ofnormalcellsin","losecontactinhibition","transformed cells","tissue-culturedish"],"check":{"q":"正常细胞在培养皿中长满单层后停止分裂的现象称为？","o":["A. 锚定依赖","B. 接触抑制","C. 血清依赖","D. 密度梯度离心"],"a":"B","e":"正常细胞长满单层后因接触抑制停止分裂；转化细胞失去该抑制，形成转化细胞灶。","oe":["A. 错误：锚定依赖指细胞需附着基质方能增殖，与接触无关","B. 正确：接触抑制指细胞相互接触后停止分裂，维持单层","C. 错误：血清依赖指生长需血清因子，与细胞接触无关","D. 错误：密度梯度离心是分离细胞的技术，并非生长现象"]},"cards":null,"mem":"正常单层接触抑制，转化失抑成灶","big":"assets/img/ch13/big/p005.jpg"},{"i":5,"sec":"","title":"接触抑制(contact inhibition)：","notes":"正常动物细胞体外培养时，细胞分裂增殖，\n铺满培养器皿的表面，形成单层 (monolayer)后\n则停止分裂⎯单层附壁生长，将细胞这种达到相\n互接触时停止分裂的现象称作。\n多层的聚集体，也说明恶性细胞的生长分裂失去\n控制，调节细胞正常生长和分裂的信号对恶性细\n胞已不起作用。","page":6,"level":"掌握","img":"assets/img/ch13/p006.jpg","anim":null,"fig":null,"points":["在相同条件下培养的恶性细胞则相互堆积形成"],"check":{"q":"接触抑制是指？","o":["A. 细胞相互接触诱导凋亡的现象","B. 细胞接触后加速分裂的现象","C. 细胞接触后发生融合的现象","D. 正常细胞增殖达到相互接触时停止分裂的现象"],"a":"D","e":"正常动物细胞体外培养形成单层、相互接触时即停止分裂，称为接触抑制。","oe":["该现象表现为停止分裂，不是凋亡。","接触抑制是停止分裂，不是加速分裂。","接触抑制与细胞融合过程没有关系。","正确，正常细胞铺满形成单层后接触即停止分裂。"],"basis":"将细胞这种达到相互接触时停止分裂的现象称作接触抑制。"},"cards":null,"mem":"铺满成单层即停，恶性堆叠","big":"assets/img/ch13/big/p006.jpg"},{"i":6,"sec":"","title":"失去生长的接触抑制","notes":"肿瘤的形成与\n扩散\n肿瘤的形成与扩散\n\n【读图讲解】\n该图分三步说明肿瘤的形成与扩散，主题为“失去生长的接触抑制”。①正常上皮中一个细胞发生突变；②突变细胞摆脱接触抑制、不断增殖堆积，形成肿瘤；③肿瘤继续生长，癌细胞突破基膜进入血液，随血流转移。图中紫色细胞代表癌变细胞，下方棕色结构为基膜与血管。要点：正常细胞因接触抑制而单层生长，癌变后失去该抑制而堆叠成瘤，并可侵入血液发生转移，这是恶性肿瘤的基本行为。","page":7,"level":"掌握","img":"assets/img/ch13/p007.jpg","anim":null,"fig":null,"points":null,"check":{"q":"该图所示肿瘤形成的关键环节是？","o":["A. 细胞停止增殖形成规则单层","B. 细胞分化能力显著增强","C. 突变细胞摆脱接触抑制、不断增殖堆积成瘤","D. 细胞凋亡增强使组织萎缩"],"a":"C","e":"正常细胞因接触抑制单层生长，突变细胞摆脱该抑制后堆叠成瘤并可侵入血液转移。","oe":["肿瘤表现为过度增殖，而非停止增殖单层生长。","癌变是分化异常，不是分化增强。","正确，突变细胞失去接触抑制而堆叠成瘤。","肿瘤形成与细胞凋亡增强正好相反。"],"basis":"突变细胞摆脱接触抑制、不断增殖堆积，形成肿瘤。"},"cards":null,"mem":"突变堆积成瘤，破基膜随血转移","big":"assets/img/ch13/big/p007.jpg"},{"i":7,"sec":"","title":"2）某些癌细胞能够分泌刺激自身增殖的生","notes":"长因子，促进自身分裂。\n充一定浓度后才能正常生长。\n等。\n常条件下生长因子的依赖。即体外培养不依赖血\n清。\n细胞无血清生长基本停止。","page":8,"level":"掌握","img":"assets/img/ch13/p008.jpg","anim":null,"fig":null,"points":["体外培养的正常细胞通常对血清有依赖性，补","血清提供生长因子，如表皮生长因子、胰岛素","癌细胞则能够不正常合成生长因子，失去对正","培养基有无血清对癌细胞生长影响不大，正常"],"check":{"q":"关于癌细胞与生长因子的关系，叙述正确的是？","o":["A. 正常细胞可自发合成所需生长因子","B. 癌细胞可自发合成生长因子，对血清依赖降低","C. 血清对两类细胞的生长均无影响","D. 癌细胞比正常细胞更依赖血清"],"a":"B","e":"正常细胞依赖血清中的生长因子，癌细胞能自发合成生长因子而降低对血清的依赖。","oe":["正常细胞需外源生长因子，不能自发合成。","正确，癌细胞能自己合成生长因子，失去对血清的依赖。","正常细胞对血清有依赖性，无血清则基本停止生长。","癌细胞对血清依赖降低，而非增强。"],"basis":"癌细胞能够不正常合成生长因子，失去对正常条件下生长因子的依赖。"},"cards":null,"mem":"癌自分泌生长因子，不依赖血清","big":"assets/img/ch13/big/p008.jpg"},{"i":8,"sec":"","title":"●癌细胞的自分泌生长刺激","notes":"【图中英文对照】\n• Growth factor production —— 癌细胞产生生长因子\n• Receptor stimulation —— 刺激自身受体(自分泌环)\n• autocrine growth stimulation —— 自分泌生长刺激\n【读图讲解】\n示意图：癌细胞的自分泌生长刺激——癌细胞自身分泌生长因子(growth factor)，结合自身膜受体(receptor)，形成自分泌正反馈环，持续刺激增殖。考点：自分泌刺激是癌细胞自主生长机制之一。","page":9,"level":"掌握","img":"assets/img/ch13/p009.jpg","anim":null,"fig":null,"points":["癌细胞的自分泌生长刺激","Receptor","stimulation","Growth","factor","production"],"check":{"q":"癌细胞自身分泌生长因子并刺激自身受体，持续刺激增殖的机制称为？","o":["A. 自分泌生长刺激","B. 旁分泌刺激","C. 内分泌刺激","D. 接触抑制"],"a":"A","e":"癌细胞产生生长因子结合自身膜受体，形成自分泌正反馈环，是自主生长机制之一。","oe":["A. 正确：自分泌指细胞分泌的因子作用于自身受体，形成正反馈","B. 错误：旁分泌是作用于邻近细胞，非自身受体","C. 错误：内分泌通过血液循环作用于远距离靶细胞","D. 错误：接触抑制是正常细胞停止分裂的现象，与题意相反"]},"cards":null,"mem":"癌细胞产因子，自分泌刺激自身","big":"assets/img/ch13/big/p009.jpg"},{"i":9,"sec":"","title":"自分泌激活","notes":"血清饥饿对正常细胞与癌基因转化细胞的影响\n\n【读图讲解】\n该图为“自分泌激活”曲线，比较血清饥饿对正常细胞与癌基因转化细胞的影响。横轴为培养时间(天)，纵轴为细胞数。红色曲线代表癌细胞：即使不添加血清生长因子(虚线)仍持续增长，添加血清(实线)增长更快；蓝色曲线代表正常细胞：加血清生长因子时增长并趋于平缓，去除血清(虚线)后几乎不增殖。要点：癌细胞可自分泌生长因子，对外源血清的依赖性降低，即对生长因子、锚定等的依赖减弱。","page":10,"level":"掌握","img":"assets/img/ch13/p010.jpg","anim":null,"fig":null,"points":null,"check":{"q":"与正常细胞相比，癌基因转化细胞在血清饥饿条件下的生长特点是？","o":["A. 完全停止增殖并迅速死亡","B. 增殖速度不变且完全不需要生长因子","C. 转为单层接触抑制生长","D. 对外源血清依赖性降低，仍能持续增殖"],"a":"D","e":"癌细胞可自分泌生长因子，对外源血清（生长因子）的依赖性降低，去除血清后仍持续增长。","oe":["A. 错误：正常细胞去除血清后几乎不增殖，癌细胞则继续生长","B. 错误：癌细胞是依赖性降低而非绝对不需要生长因子","C. 错误：癌细胞失去接触抑制，不会转为单层接触抑制生长","D. 正确：癌细胞自分泌生长因子，血清饥饿时仍可持续增殖"]},"cards":null,"mem":"血清饥饿正常停，癌细胞照长","big":"assets/img/ch13/big/p010.jpg"},{"i":10,"sec":"","title":"3)染色体异常","notes":"癌细胞常出现染色体非整数倍，有染色体\n的缺失或增加。\nautosomes(常染色体) and 2 sex chromosomes. The\ntwo members of a pair would be identical, and each\nchromosome would be a single continuous color.\nderanged as evidenced by the presence of extra and\nmissing chromosomes and chromosomes of more\nthan one color.\n【中文讲解·对照课本/考点】\n考点：绪论 · 概览 ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• 染色体（chromosome）：当细胞进入有丝分裂时，伸展、弥散的丝状染色质高度折叠、盘曲而凝缩成条状或棒状的特殊形态，称为染色体。\n\n【本页英文讲解】\n本页主题为癌细胞的染色体异常(3)。关键术语：二倍体细胞(diploid cell)、常染色体(autosome)、性染色体(sex chromosome)。正常二倍体细胞有22对常染色体与2条性染色体，同源染色体形态一致；而癌细胞出现染色体非整倍体(aneuploidy)，有染色体的缺失或增加，颜色多样提示存在易位。考点：癌细胞染色体数目与结构畸变。","page":11,"level":"掌握","img":"assets/img/ch13/p011.jpg","anim":null,"fig":null,"points":["A normal diploid cell would have 22 pairs of","The chromosomes of this cancer cell are highly"],"check":{"q":"关于癌细胞的染色体异常，叙述正确的是（　）","o":["A. 癌细胞染色体数目与正常二倍体细胞完全一致","B. 癌细胞常呈染色体非整倍体，出现染色体的缺失或增加","C. 正常人体细胞含23对常染色体和2条性染色体","D. 癌细胞染色体仅数目异常，结构不发生改变"],"a":"B","e":"癌细胞常出现染色体非整数倍，有染色体的缺失或增加，即非整倍体；正常二倍体细胞有22对常染色体与2条性染色体，同源染色体形态一致，而癌细胞染色体高度紊乱，还可见易位等结构畸变。","oe":["错误：癌细胞染色体高度紊乱，与正常二倍体明显不同。","正确：癌细胞常出现染色体非整数倍，有染色体的缺失或增加。","错误：正常人体细胞有22对常染色体和2条性染色体。","错误：癌细胞还存在易位等结构畸变，并非仅数目异常。"]},"cards":null,"mem":"癌细胞染色体非整倍，多缺失","big":"assets/img/ch13/big/p011.jpg"},{"i":11,"sec":"","title":"乳","notes":"腺\n癌\n细\n胞\n核\n型\n变\n化\nThe chromosomes are highly deranged by the presence of extra\nand missing chromosomes and chromosomes of more than one\ncolor. These multicolored chromosomes reflect the large\nnumbers of translocations that have occurred in previous cell\ngenerations.\n【中文讲解·对照课本/考点】\n考点：绪论 · 概览 ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• ◆原癌基因存在于细胞基因组中(c-onc)，是控制细胞生长和分裂的基因。编码多种类型的蛋白质---细胞生长和分裂的调控因子。癌基因是控制细胞生长和分裂的原癌基因的一种突变形式。\n\n【本页英文讲解】\n本页展示乳腺癌(breast cancer)细胞核型(karyotype)的变化。关键术语：易位(translocation)。癌细胞核内有多余和缺失的染色体，同一条染色体带多种颜色，说明曾发生大量染色体易位，且是经多个细胞世代累积而成，体现基因组不稳定性。对应翟中和教材：核型紊乱是癌细胞的恶性特征之一。","page":12,"level":"掌握","img":"assets/img/ch13/p012.jpg","anim":null,"fig":null,"points":null,"check":{"q":"乳腺癌细胞核型中同一条染色体呈现多种颜色，说明曾发生大量？","o":["A. DNA点突变","B. 染色体易位","C. 基因扩增","D. 染色体倒位"],"a":"B","e":"多色染色体反映多个细胞世代中发生的大量染色体易位，体现癌细胞基因组不稳定性。","oe":["A. 错误：点突变属碱基水平改变，不产生多色染色体带","B. 正确：多色染色体反映曾发生大量易位，是核型紊乱表现","C. 错误：基因扩增表现为拷贝数增加，不产生多色染色体","D. 错误：倒位是染色体片段方向改变，不是多色的主要原因"]},"cards":null,"mem":"乳腺癌核型乱，多彩示易位","big":"assets/img/ch13/big/p012.jpg"},{"i":12,"sec":"","title":"leukemia(慢性骨髓性","notes":"Normal structure\nThe translocation\nbetween chromosomes9\nand 22 responsible for\nchronic myelogenous\n白血病).\n→费城染色体\n【中文讲解·对照课本/考点】\n考点：绪论 · 概览 ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• ◆原癌基因存在于细胞基因组中(c-onc)，是控制细胞生长和分裂的基因。编码多种类型的蛋白质---细胞生长和分裂的调控因子。癌基因是控制细胞生长和分裂的原癌基因的一种突变形式。\n\n【本页英文讲解】\n本页主题为慢性骨髓性白血病(CML)相关的染色体易位。关键术语：易位(translocation)、费城染色体(Philadelphia chromosome)。第9号与第22号染色体间发生易位，形成特征性费城染色体，导致BCR-ABL融合基因及异常酪氨酸激酶活性。考点：染色体易位激活原癌基因，CML可用伊马替尼靶向治疗。","page":13,"level":"掌握","img":"assets/img/ch13/p013.jpg","anim":null,"fig":null,"points":null,"check":{"q":"慢性骨髓性白血病(CML)特征性的费城染色体由哪两条染色体易位形成？","o":["A. 第8号与第14号染色体","B. 第11号与第19号染色体","C. 第9号与第22号染色体","D. 第1号与第7号染色体"],"a":"C","e":"第9号与第22号染色体易位形成费城染色体，产生BCR-ABL融合基因及异常酪氨酸激酶活性。","oe":["A. 错误：8与14号易位多见于伯基特淋巴瘤，与CML无关","B. 错误：11与19号易位见于急性白血病，与费城染色体无关","C. 正确：9号与22号易位形成费城染色体，即CML的标志","D. 错误：此组合并非CML特征性易位，属干扰项"]},"cards":null,"mem":"9与22易位→费城染色体(CML)","big":"assets/img/ch13/big/p013.jpg"},{"i":13,"sec":"","title":"4) 细胞表面蛋白减少，细胞黏着降低","notes":"恶性肿瘤常合成和分泌一些蛋白酶，降解细胞表面的某些结\n构，降低了细胞之间的黏着和连接，使癌细胞具有在体内\n转移的能力。\nTwo main ways in which animal cells are bound together.","page":14,"level":"掌握","img":"assets/img/ch13/p014.jpg","anim":null,"fig":null,"points":null,"check":{"q":"恶性肿瘤细胞易于转移的原因之一是合成分泌蛋白酶，其作用是？","o":["A. 增加细胞间黏着连接","B. 促进细胞凋亡","C. 抑制血管生成","D. 降解细胞表面结构，降低细胞间黏着"],"a":"D","e":"恶性肿瘤分泌蛋白酶降解细胞表面结构，降低细胞间黏着和连接，使癌细胞具有体内转移能力。","oe":["A. 错误：蛋白酶降低而非增加细胞间黏着与连接","B. 错误：该作用与促进凋亡无关，肿瘤反而抑制凋亡","C. 错误：蛋白酶与抑制血管生成无直接关系","D. 正确：蛋白酶降解表面结构与连接，降低黏着而利于转移"]},"cards":null,"mem":"分泌蛋白酶降黏着，利转移","big":"assets/img/ch13/big/p014.jpg"},{"i":14,"sec":"","title":"5) 癌细胞转移－具有侵润性和扩散性","notes":"良性肿瘤与恶性肿瘤的主要区别：\n侵润周围健康组织；通过血液循环或淋巴途径转移病增殖。\n移灶 metastasis”\n黑色素肉瘤对正常肝组织细胞\n的侵润\n(红色为转移病灶)\n【结合课本/笔记】基本生物学特征◆细胞生长与分裂失去控制，具有无限增殖能力，成为“永生”细胞。◆具有扩散性·癌细胞的细胞间粘着性下降，具有侵润性和扩散性，这是癌细胞的基本特征。·在分化程度上癌细胞低于良性肿瘤细胞，且失去了许多原组织细胞的结构和功能◆细胞间相互作用改变（识别改变；表达水解酶类；产生新的表面抗原）◆蛋白表达谱系或蛋白活性改变（胚胎细胞蛋白、端粒酶活性升高）◆ mRNA转录谱系的改变（少数基因表达不同；突变位点不同，表型多变）◆染色体非整倍性体外培养的恶性转化细胞的特征◆恶性转化细胞同癌细胞一样具有无限增殖的潜能","page":15,"level":"掌握","img":"assets/img/ch13/p015.jpg","anim":null,"fig":null,"points":["恶性肿瘤细胞间粘性下降，具有侵润性和扩散性，易于","转移并在身体其它部位增殖产生的的次级肿瘤称为 “转"],"check":{"q":"关于癌细胞的浸润与转移，叙述正确的是（　）","o":["A. 转移是指癌细胞在原发部位形成次级肿瘤","B. 癌细胞间黏着性下降，具有浸润性和扩散性，可经血行或淋巴转移","C. 良性肿瘤细胞同样具有浸润性但不会转移","D. 癌细胞的分化程度高于良性肿瘤细胞"],"a":"B","e":"恶性肿瘤与良性肿瘤的主要区别在于浸润周围健康组织并通过血液循环或淋巴途径转移；癌细胞间黏着性下降，具有浸润性和扩散性，转移后形成的次级肿瘤称转移灶（metastasis）。","oe":["错误：转移灶是癌细胞在身体其他部位增殖形成的次级肿瘤。","正确：癌细胞间黏着性下降，具浸润扩散性，可经血液或淋巴转移。","错误：良性肿瘤一般不浸润周围组织，也不发生转移。","错误：癌细胞分化程度低于良性肿瘤细胞。"]},"cards":null,"mem":"恶性侵润扩散，转移灶=metastasis","big":"assets/img/ch13/big/p015.jpg"},{"i":15,"sec":"","title":"化学致癌物","notes":"2 The causes of cancer\n物理辐射: X-射线、紫外线\n生物因子：DNA病毒和RNA病毒\n癌基因、原癌基因\n\n【读图讲解】\n该页为文字与图示结合，题为“The causes of cancer”。右侧“What Causes Cancer?”图列出四类因素：Viruses(病毒)、Other infectious agents(其他感染因子)、Mutations in specific genes(特定基因突变)、Breakdown in immunity(免疫崩溃)。左侧中文归纳致癌因素：化学致癌物；物理辐射，如X-射线、紫外线；生物因子，即DNA病毒和RNA病毒；以及癌基因、原癌基因。要点：癌症是多种因素引起、多基因多步骤累积突变的结果。","page":16,"level":"掌握","img":"assets/img/ch13/p016.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于癌症的发生，该页表达的核心观点是？","o":["A. 癌症由单一基因一次突变即可引起","B. 癌症仅由病毒感染引起","C. 癌症完全由遗传因素决定","D. 癌症是多种因素引起、多基因多步骤累积突变的结果"],"a":"D","e":"致癌因素包括化学致癌物、物理辐射、病毒及癌基因等，癌症是多因素多步骤累积突变的结果。","oe":["癌症需多步骤累积突变，非一次突变。","病毒只是致癌因素之一，非唯一。","癌症主要是体细胞突变，环境因素也重要。","正确，癌症为多因素、多基因多步骤累积突变的结果。"],"basis":"癌症是多种因素引起、多基因多步骤累积突变的结果。"},"cards":null,"mem":"致癌四因：化学、辐射、病毒、突变","big":"assets/img/ch13/big/p016.jpg"}],"mcq":[{"id":"ch13_mcq_2","mod":"绪论 · 概览","modI":0,"q":"周期蛋白依赖性蛋白激酶中，充当调节亚基的是（              ）。","o":["A．周期蛋白","B．CDK 蛋白","C．MPF 蛋白","D．都不是"],"a":"A","e":"在 CDK-Cyclin 复合物中，CDK 为催化亚基，Cyclin 为调节亚基。","kp":"ch13_s0_7","oe":["CDK-Cyclin复合物中周期蛋白为调节亚基，正确。","CDK为催化亚基，具蛋白激酶活性。","MPF是CDK1与cyclinB的复合物，非单一调节亚基。","周期蛋白即为调节亚基，故“都不是”错误。"]},{"id":"ch13_mcq_3","mod":"绪论 · 概览","modI":0,"q":"MPF 的功能有（     ）。","o":["A．催化组蛋白 H1 的磷酸化","B．催化核限层蛋白磷酸化","C．作用于微管蛋白，控制着细胞周期中微管的动力学变化","D．以上都正确"],"a":"D","e":"MPF 调控细胞由 G2 期向 M 期转换，其功能是催化靶蛋白磷酸化，为细胞由间期 进入分裂期做好准备。","kp":"ch13_s0_0","oe":["MPF可催化组蛋白H1磷酸化，属其功能之一，正确。","MPF使核纤层蛋白磷酸化致核膜解体，属其功能，正确。","MPF作用于微管蛋白调控微管动态变化，属其功能，正确。","MPF兼具上述三方面功能，故以上都正确。"]},{"id":"ch13_mcq_6","mod":"绪论 · 概览","modI":0,"q":"将有丝分裂中期细胞与 G1 细胞融合，可诱导 G1 细胞出现早熟染色体凝集其形态为（       ）。","o":["A．单线状","B．双线状","C．粉末状","D．都不是"],"a":"A","e":"G0 期的 PCC 呈单细丝状，S 期的呈粉末状，G2 期的呈双线状。","kp":"ch13_s0_9","oe":["G1期细胞DNA尚未复制，早熟染色体凝集呈单线状，正确。","双线状对应DNA已复制的G2期细胞。","粉末状对应S期细胞，非G1期形态。","G1期呈单线状，故“都不是”错误。"]},{"id":"ch13_mcq_10","mod":"绪论 · 概览","modI":0,"q":"癌细胞的主要特点之一是（           ）。","o":["A．细胞间黏附性增强","B．缺少接触抑制作用","C．对生长因子的需求量上升","D．增殖力下降"],"a":"B","e":"A 项，癌细胞几乎丧失细胞间的黏着，相互之间不产生抑制作用，更有利于快速繁 殖。C 项，由于癌细胞的增殖能力增强，其对生长因子的需求量下降。D 项，癌细胞的一个 典型特征就是增殖力增强。","kp":"ch13_s0_8","oe":["癌细胞细胞间黏附性下降而非增强。","癌细胞丧失接触抑制，可堆积重叠、无限增殖，正确。","癌细胞自分泌生长因子，对生长因子需求下降。","癌细胞的增殖能力增强而非下降。"]}],"judge":[{"id":"ch13_judge_1","modI":0,"q":"在有蛋白质合成抑制剂存在的情况下，孕酮和成熟卵细胞的细胞质都能诱导卵母细胞成 熟。（      ）","a":"错","e":"在有蛋白质合成抑制剂存在的情况下．成熟卵细胞的细胞质都能诱导卵母细胞成熟， 而孕酮不能，因为不能合成 MPF。","kp":"ch13_s0_8","oe":["有人以为成熟卵细胞质含 MPF、孕酮也经细胞质起作用，故误判为都能诱导。","成熟卵细胞质含现成 MPF 可诱导成熟，孕酮需合成 MPF，被抑制剂阻断故不能。"]},{"id":"ch13_judge_3","modI":0,"q":"在泛素化途径降解蛋白质过程中，泛素随靶蛋白一同被蛋白酶体降解。（                     ）","a":"错","e":"泛素并不被降解，它可以循环利用。","kp":"ch13_s0_13","oe":["泛素标记靶蛋白并引导其进入蛋白酶体，易让人以为泛素也一并被降解。","泛素起标签作用，靶蛋白降解后泛素被释放并可循环利用，自身不被降解。"]},{"id":"ch13_judge_9","modI":0,"q":"正常细胞发生癌变时游离的核糖体增多，而附着的核糖体和内质网的数目相应减少。 （     ）","a":"错","e":"正常细胞发生癌变后，与癌细胞恶性增殖、扩散等过程相关的蛋白成分会过表达， 从而使得粗面内质网的数目增多，附着核糖体的数目增多。","kp":"ch13_s0_9","oe":["癌细胞增殖旺盛需大量蛋白，易误以为游离核糖体增多而粗面内质网减少。","癌变时与恶性增殖相关的蛋白过表达，粗面内质网及附着核糖体反而增多。"]},{"id":"ch13_judge_13","modI":0,"q":"Bc12 是一种原癌基因，它和一般的癌基因不同，它能够延长细胞的生存，而不是促进细 胞的增殖。（          ）","a":"对","e":"","kp":"ch13_s0_9","oe":["Bcl-2 属原癌基因，通过抑制凋亡延长细胞存活，符合其抗凋亡功能。","若认为 Bcl-2 是通过促进细胞增殖致癌，则混淆了其抗凋亡机制。"]},{"id":"ch13_judge_14","modI":0,"q":"永生细胞和癌细胞的主要共同点就是既没有细胞分裂次数的限制，也没有细胞间的接触 抑制。（         ）","a":"错","e":"永生细胞间有接触抑制。","kp":"ch13_s0_4","oe":["永生细胞与癌细胞都能无限传代，易被误认为两者都失去接触抑制。","永生细胞仍保留接触抑制，只有癌细胞才同时丧失接触抑制。"]},{"id":"ch13_judge_15","modI":0,"q":"在不利于细胞分裂的情形下，高等动物细胞通常会选择在 G2 检验点暂停，等待继续进行 细胞分裂的信号。（            ）","a":"对","e":"","kp":"ch13_s0_5","oe":["细胞在 G2 期检查 DNA 复制是否完成、损伤是否修复，不利时暂停等信号。","若认为细胞只在 G1 检验点受阻、不存在 G2 检验点，则不符合事实。"]}],"fill":[{"id":"ch13_fill_15","modI":0,"q":"周期蛋白 B 的降解依赖______途径。","a":"泛素-蛋白酶体降解","kp":"ch13_s0_0","oe":["周期蛋白B经泛素化后被蛋白酶体识别并降解。"]},{"id":"ch13_fill_17","modI":0,"q":"______是细胞增殖的负性调节因子，能够抑制癌细胞的恶性增殖，突变后有可能使细胞 发生癌变。","a":"抑癌基因","kp":"ch13_s0_8","oe":["抑癌基因抑制细胞增殖，突变失活后可能导致细胞癌变。"]},{"id":"ch13_fill_21","modI":0,"q":"YEIID 是专一结合在基因上游调控序列的______盒上，它决定转录正确的其始位置。","a":"TATA","kp":"ch13_s0_0","oe":["TFIID专一结合基因上游TATA盒，决定转录起始位置。"]},{"id":"ch13_fill_23","modI":0,"q":"英国科学家______在多肽链序列测定和 DNA 序列测定方面做出重大的贡献。","a":"Sanger","kp":"ch13_s0_15","oe":["英国科学家Sanger在蛋白质和DNA序列测定方面贡献卓著。"]},{"id":"ch13_fill_24","modI":0,"q":"CpG 岛常常位于______，其中的______位常常被甲基化，DNA 甲基化与基因表达的 ______有关。","a":"转录调控区；5-C；阻抑","kp":"ch13_s0_15","oe":["CpG岛常位于基因的转录调控区（启动子区）。","其中胞嘧啶第5位碳常被甲基化成5-甲基胞嘧啶。","DNA甲基化通常与基因表达的阻抑（沉默）有关。"]},{"id":"ch13_fill_26","modI":0,"q":"动物体内细胞分裂调节失控而无限增殖的细胞称为______，其中具有转移能力的称为 ______。","a":"肿瘤细胞；恶性肿瘤（癌症）","kp":"ch13_s0_0","oe":["细胞分裂调节失控而无限增殖的细胞称为肿瘤细胞。","其中具有转移能力的称为恶性肿瘤，即癌症。"]},{"id":"ch13_fill_27","modI":0,"q":"让 M 期的细胞与间期的细胞融合，诱导间期细胞产生 PCC。G1 期的 PCC 呈单线状，S 期呈______状，G2 期的呈______状。","a":"粉末；双线","kp":"ch13_s0_9","oe":["S期DNA正在复制，PCC呈粉末状。","G2期DNA已复制完成，PCC呈双线状。"]},{"id":"ch13_fill_29","modI":0,"q":"不同时期的间期细胞与 M 期细胞融合产生______。","a":"超前凝聚染色体","kp":"ch13_s0_9","oe":["间期细胞与M期细胞融合，间期染色质被诱导提前凝集。"]}],"short":[{"id":"ch13_short_1","modI":0,"q":"简述 CDK1（MPF）激酶的活化过程。","a":"CDK1 激酶活化的过程如下： （1）首先调节亚基周期蛋白 B 或 A 必须与 CDK1 结合。 （2）weel／mikl 激酶使的 CDK1 的 Thr14 和 Tyr15 磷酸化，CAK（CDK1-activating kinase） 催化 Thr161 的磷酸化。 （3）磷酸酶 Cdc25c 催化 Thr14 和 Tyr15 去磷酸化。 （4）CDK1 表现出蛋白激酶活性，调控细胞周期的进程。","kp":"ch13_s0_0"},{"id":"ch13_short_5","modI":0,"q":"将 G1 期细胞与 S 期细胞融合，观察融合后细胞核的变化。试描述现象并对此进行解释。","a":"G-期细胞融合后其核内染色质变得较伸展，DNA 开始复制。这是因为 S 期细胞内的蛋 白质因子启动了 G1 期细胞内的 DNA 复制。","kp":"ch13_s0_9"},{"id":"ch13_short_7","modI":0,"q":"试述真核生物 G2／M 转换的机制。","a":"真核生物 G2／M 的转换实际上就是 MPF 的完全激活。P34cdc2 与周期蛋白 B 结合，形成 的是无活性的 MPF。然后在激酶 weel 和 mikl 的作用下，将 P34cdc2 的 Tyr15 和 Thr167 磷酸 化，形成的是无活性的前 MPF，然后在 Cdc25 磷酸酶的作用下，将 Tyr15 位的磷酸脱去， 形成活性 MPF，使一系列的底物发生磷酸化，进入 M 期。由此看来，Tyr15 位的磷酸化起 抑制作用，Thr167 磷酸化起激活作用。","kp":"ch13_s0_0"},{"id":"ch13_short_9","modI":0,"q":"何为癌细胞？癌细胞的基本生物学特征包括哪些？","a":"癌细胞是指由于基因突变，正常细胞的生长分化失控，脱离了衰老和死亡的正常途径， 而具有无限增殖特性的细胞。其基本特征有： （1）细胞生长与分裂失去控制，具有无限增殖能力，成为“永生”细胞； （2）具有侵润性和扩散性； （3）细胞间相互作用改变； （4）mRNA 表达谱系及蛋白表达谱系或蛋白活性改变； （5）染色体非整倍性。","kp":"ch13_s0_8"},{"id":"ch13_short_11","modI":0,"q":"良性和恶性肿瘤的主要异同是什么？","a":"都由于细胞生长失控而造成，但良性肿瘤缺乏在体内转移的能力，所以可通过手术根除； 而转移性的恶性肿瘤的细胞可脱离原来的位置，侵入邻近的组织或更远的位置，并在新的位 点迅速生长。恶性肿瘤常由良性肿瘤转化而来。","kp":"ch13_s0_14"},{"id":"ch13_short_14","modI":0,"q":"请简要叙述肿瘤细胞相对于正常细胞而言，在细胞水平上所特有的基本特征。 相关试题：癌细胞具有哪些不同于正常细胞的特性？","a":"肿瘤细胞相对于正常细胞而言的特征有： （1）细胞生长和分裂失去控制 正常细胞执行其特定的生理功能(如肝细胞和神经细胞)，会有新生细胞的增殖、衰老细胞的 死亡，在动态平衡中维持组织与器官的稳定，这是一种严格受控的过程。癌细胞生长失去控 制，成为永生细胞，核质比例增大，分裂速度加快，破坏了正常组织的结构与功能。 （2）具有浸润性和扩散性 恶性肿瘤细胞（癌细胞）的细胞间黏着性下降，具有浸润性和扩散性，易于浸润周围健康组 织，或通过血液循环或淋巴途径转移并在其他部位黏着和增殖。此外，癌细胞在分化程度上 低于正常细胞和良性肿瘤细胞，失去了原组织细胞的某些结构和功能。 （3）细胞间相互作用改变 癌细胞冲破了细胞识别作用的束缚，在转移过程中，除了会产生水解酶类（如用于水解基底 膜成分的酶类），而且要异常表达某些膜蛋白，以便与别处细胞黏着和继续增殖，并借此逃 避免疫系统的监视，防止天然杀伤细胞等的识别和攻击。 （4）表达谱改变或蛋白活性改变 对癌细胞与正常细胞中基因表达谱进行检测比较，不同的转录片段仅占整个基因表达谱中很 少一部分；蛋白质表达谱系中，常出现一些在胚胎细胞中所表达的蛋白质，还异常表达与其 恶性增殖、扩散等过程相关的蛋白质组分。由于癌细胞基因突变位点不同，表型不稳定，决 定了癌细胞异质性的特征。 （5）体外培养的恶性转化细胞的特征 应用人工诱导技术培养出恶性转化细胞，同癌细胞一样具有无限增殖的潜能，在体外培养时 贴壁性下降，可不依附在培养器皿壁上生长，有些还可进行悬浮式培养；失去运动和分裂的 接触抑制，在软琼脂培养基中可形成细胞克隆。当将恶性转化细胞注入易感染动物体内时， 往往会形成肿瘤。","kp":"ch13_s0_8"},{"id":"ch13_short_17","modI":0,"q":"简述发现海胆周期蛋白 B 的实验过程。","a":"发现海胆周期蛋白 B 的实验过程如下： （1）以 Tim Hunt 为代表的科学家以海胆卵为实验材料，对细胞周期进行深入研究。1983 年，他们报道在海胆卵细胞中存在两种特殊蛋白质。这两种蛋白质的含量随细胞周期进程变 化而变化，一般在细胞间期内积累，在细胞分裂期内消失，在下一个细胞周期中又重复这一 消长过程。因此他们将这两种蛋白质命名为周期蛋白（cyclin）。 （2）这些周期蛋白很快被分离和克隆出来，并被证明广泛存在于从酵母到人类等各种真核 生物中。 （3）用柱层析从蛙卵中纯化 MPF 之后，James Maller 和 Tim Hunt 实验室合作，证明周期蛋 白 B 是 MPF 的一种成分。","kp":"ch13_s0_0"},{"id":"ch13_short_20","modI":0,"q":"Ras 蛋白在信号转导中的作用，谈谈突变 Ras 致癌的可能机制。 相关试题：Ras 蛋白是细胞信号转导途径中的一个重要分子开关。ras 基因突变会导致蛋白 GTP 酶活性丧失，并且会导致正常细胞发生癌变。请解释这一现象。","a":"（1）Ras 蛋白在信号转导中的作用 Ras 蛋白是一种小的 GTP 结合蛋白，具有 GTP 酶活性，位于胞质侧，结合 GTP 时为活化态， 结合 GDP 时失活。Ras 蛋白具有分子开关作用，激活磷酸化级联反应。GAP 增强 Ras 蛋白 的 GTP 酶活性。 （2）突变 Ras 致癌的可能机制 发生突变的 Ras 蛋白能够与 GTP 结合，但不能将其水解成 GDP，从而使自身锁定于活化状 态，导致变性、细胞转化和肿瘤发生。","kp":"ch13_s0_9"},{"id":"ch13_short_27","modI":0,"q":"什么是肿瘤干细胞？","a":"肿瘤干细胞是一群存在于某些肿瘤组织中的干细胞样细胞，具有自我更新、无限增殖、 转移和抗化学毒物损伤的能力。目前认为肿瘤干细胞的存在是导致肿瘤化疗失败的主要原因。 与一般的肿瘤细胞相比，肿瘤干细胞具有以下特性： （1）高致瘤性 很少量的肿瘤干细胞在体外培养，就能生成集落；将很少量的肿瘤干细胞注入实验动物体内， 即可形成肿瘤。 （2）强耐药性 多数肿瘤干细胞的细胞膜上表达 ATP 结合盒（ABC）家族膜转运蛋白，可运输并外排代谢 产物、药物、毒性物质、内源性脂质、多肽、核苷酸及固醇类等多种物质，使之对许多化疗 药物产生耐药性。","kp":"ch13_s0_0"}],"calc":[],"term":[{"id":"ch13_term_3","modI":0,"term":"成熟促进因子（MPF）。","def":"成熟促进因子（MPF）是指由 CDK1 和周期蛋白 B 结合而成，调控细胞由 G2 期向 M 期转化的一种酶。","kps":"","kp":"ch13_s0_0"},{"id":"ch13_term_7","modI":0,"term":"后期促进因子复合体（anaphase-promoting complex，APC）。","def":"后期促进因子复合体 APC 主要介导两类蛋白降解：后期抑制因子和有丝分裂周期蛋白。 前者维持姐妹染色单体粘连，抑制后期启动；后者的降解意味着有丝分裂即将结束，即染色 体开始去凝集，核膜重建。APC 可被 Cdc20 激活。但是，在有丝分裂前期，Cdc20 和 Mad2 蛋白位于染色体的动粒上，在染色体结合有丝分裂纺锤体的微管前将不能从动粒上释放，由 于 Mad2 与 Cdc20 结合而抑制 Cdc20 的活性。所以只有所有染色体都与纺锤体微管结合后， Cde20 释放出来作用于 APC，APC 才有活性，才启动细胞向后期转换。","kps":"","kp":"ch13_s0_10"},{"id":"ch13_term_15","modI":0,"term":"早熟染色体凝集","def":"早熟染色体凝集（PCC）是指 M 期细胞与其他间期细胞在一定介质（如仙台病毒）介 导下发生融合，继续培养一段时间后，与 M 期细胞融合的间期细胞发生了形态各异的染色 体凝集现象。G1 期 PCC 为细单线状，S 期 PCC 为粉末状，G2 期 PCC 为双线染色体状。","kps":"","kp":"ch13_s0_9"}]},{"i":1,"name":"2.1 化学致癌物与辐射对癌的影响","slides":[{"i":16,"sec":"2.1 化学致癌物与辐射对癌的影响","title":"2.1 化学致癌物与辐射对癌的影响","notes":"化学致癌物：\n烟、焦油\n是肝癌的主要诱发者，引起p53基因249位碱基置\n换，G→T (肝癌检测指标)\n辐射：\n癌力远远高于紫外线。\nX射线治疗(副作用)时注意权衡。","page":17,"level":"掌握","img":"assets/img/ch13/p017.jpg","anim":null,"fig":null,"points":["苯胺衍生物，砷、石棉，苯，铅，芥子气，煤","坚果、谷物发霉产生的黄曲霉素B (aflatoxin B)","X射线具有较强的穿透力，到达内部器官，致","放射性元素：居里夫人（白血病）"],"check":{"q":"关于化学致癌物与辐射对癌的影响，叙述正确的是（　）","o":["A. 紫外线的致癌能力远高于X射线","B. 化学致癌物只作用于肝脏，不引起其他器官肿瘤","C. 黄曲霉素B是肝癌的主要诱发者，可致p53基因249位碱基G→T置换","D. 黄曲霉素B引起p53基因249位碱基A→T置换"],"a":"C","e":"黄曲霉素B是肝癌的主要诱发者，可引起p53基因249位碱基G→T置换（肝癌检测指标）；X射线穿透力强，致癌能力远高于紫外线；苯胺衍生物、砷、石棉、苯、铅、芥子气、煤等也是化学致癌物。","oe":["错误：X射线穿透力强，致癌能力远高于紫外线。","错误：砷、石棉、苯等化学致癌物可诱发多种器官肿瘤。","正确：黄曲霉素B是肝癌主要诱发者，引起p53基因249位G→T置换。","错误：是G→T置换，而非A→T置换。"]},"cards":null,"mem":"黄曲霉致肝癌G→T，X射线强于UV","big":"assets/img/ch13/big/p017.jpg"},{"i":17,"sec":"2.1 化学致癌物与辐射对癌的影响","title":"p53 gene 中随机7个密码子，在癌症病人中有50%发","notes":"生突变或缺失。C →T，每一种致癌物都引起一种不\n同的碱基置换\n黄曲霉毒素\n内源肝的代谢引起的脱氨作用","page":18,"level":"掌握","img":"assets/img/ch13/p018.jpg","anim":null,"fig":null,"points":null,"check":{"q":"该页说明致癌物引起基因改变的方式是？","o":["A. 致癌物只改变染色体数目","B. 所有致癌物都只引起基因缺失","C. 每种致癌物都引起一种不同的碱基置换","D. 致癌物不改变DNA的序列"],"a":"C","e":"p53基因在约50%癌症病人中突变或缺失，且每种致癌物引起一种不同的碱基置换。","oe":["该页强调的是碱基置换，非染色体数目变化。","碱基置换是主要方式之一，并非只有缺失。","正确，不同致癌物引起不同的碱基置换。","致癌物可引起碱基置换等DNA改变。"],"basis":"每一种致癌物都引起一种不同的碱基置换。"},"cards":null,"mem":"p53七密码子50%突变，C→T","big":"assets/img/ch13/big/p018.jpg"},{"i":18,"sec":"2.1 化学致癌物与辐射对癌的影响","title":"阳光中的紫外线辐射导致DNA损伤：","notes":"相邻两个胸腺嘧啶碱基之间形成二聚体，\n暴露在阳光下的皮肤细胞对这种DNA损伤十分敏感。\n这种损伤经常使DNA复制过程在损伤位点停止运转，\n长期积累则易于突变为癌细胞。","page":19,"level":"掌握","img":"assets/img/ch13/p019.jpg","anim":null,"fig":null,"points":null,"check":{"q":"阳光紫外线导致DNA损伤的主要形式是？","o":["A. 相邻胸腺嘧啶形成二聚体","B. 嘌呤环开环","C. 磷酸二酯键断裂","D. 碱基甲基化"],"a":"A","e":"紫外线使相邻两个胸腺嘧啶形成二聚体，使复制在损伤位点停止运转，长期积累易突变为癌细胞。","oe":["A. 正确：UV使相邻胸腺嘧啶形成二聚体，是典型光损伤","B. 错误：嘌呤开环多与化学致癌物的烷化作用有关","C. 错误：磷酸二酯键断裂多为辐射或核酸酶所致，非UV主因","D. 错误：碱基甲基化是表观修饰，非UV直接损伤形式"]},"cards":null,"mem":"UV致胸腺嘧啶二聚体，阻复制","big":"assets/img/ch13/big/p019.jpg"},{"i":19,"sec":"2.1 化学致癌物与辐射对癌的影响","title":"基因的稳定性取决于            DNA","notes":"DNA修复                修复\n→               机制\n整个精确度提高到大约每复\n制109个核苷酸出现一次差错。\n该精确度远远高于我\n们日常生活所遇到的其它事\n件。\n即使没有外在诱变剂\n刺激下，每次细胞分裂中每\n个基因都有约10-6/10-7的概率\n发生自发突变。","page":20,"level":"掌握","img":"assets/img/ch13/p020.jpg","anim":null,"fig":null,"points":null,"check":{"q":"基因的稳定性主要取决于下列哪一过程？","o":["A. DNA复制速度","B. 转录效率","C. DNA修复","D. 翻译保真度"],"a":"C","e":"基因的稳定性取决于DNA修复，修复机制使复制精确度提高到约每10^9个核苷酸出现一次差错。","oe":["A. 错误：复制速度与基因稳定性无直接因果关系","B. 错误：转录效率影响表达量，不决定基因组稳定性","C. 正确：DNA修复维持基因组稳定性，显著提高复制精确度","D. 错误：翻译保真度影响蛋白质量，与基因稳定性无关"]},"cards":null,"mem":"DNA修复保基因，每10^9错一次","big":"assets/img/ch13/big/p020.jpg"}],"mcq":[{"id":"ch13_amcq_1","mod":"2.1 化学致癌物与辐射对癌的影响","modI":1,"q":"关于「化学致癌物与辐射对癌的影响」，下列说法正确的是（　）","o":["A. 在相同条件下培养的恶性细胞则相互堆积形成","B. 苯胺衍生物，砷、石棉，苯，铅，芥子气，煤","C. 体外培养的正常细胞通常对血清有依赖性，补","D. 血清提供生长因子，如表皮生长因子、胰岛素"],"a":"B","e":"本页要点：苯胺衍生物，砷、石棉，苯，铅，芥子气，煤","kp":"ch13_s1_16","oe":["描述恶性细胞失去接触抑制而堆积，与化学致癌物无关","苯胺衍生物、砷、石棉、苯等属化学致癌物，正确","描述正常细胞对血清的依赖性，非化学致癌物，故不选","描述血清提供生长因子，与化学致癌物列举无关，故不选"]}],"judge":[],"fill":[],"short":[],"calc":[],"term":[]},{"i":2,"name":"2.2 病毒","slides":[{"i":20,"sec":"2.2 病毒","title":"2.2 病毒","notes":"【图中英文对照】\n• DNA / RNA tumor viruses —— DNA / RNA 肿瘤病毒\n• SV-40 —— SV-40(猿猴病毒40)\n【读图讲解】\n表格（致瘤病毒）：DNA 病毒如 HPV→宫颈癌、EBV→伯基特淋巴瘤/鼻咽癌、SV40、多瘤病毒、腺病毒；RNA 病毒如劳氏肉瘤病毒(RSV)→肉瘤、HTLV→白血病。考点：致瘤病毒与所诱导肿瘤的对应关系。","page":21,"level":"掌握","img":"assets/img/ch13/p021.jpg","anim":null,"fig":null,"points":["表14-5部分DNA和RNA肿瘤病毒","病毒","诱导的肿瘤","生物","2.2病毒","DNA病毒","吕克氏病毒","肾腺癌"],"check":{"q":"下列致瘤病毒与所诱导肿瘤的对应关系，正确的是？","o":["A. EBV——宫颈癌","B. RSV——白血病","C. HTLV——肉瘤","D. HPV——宫颈癌"],"a":"D","e":"DNA病毒HPV致宫颈癌、EBV致伯基特淋巴瘤/鼻咽癌；RNA病毒RSV致肉瘤、HTLV致白血病。","oe":["EBV与伯基特淋巴瘤、鼻咽癌相关。","RSV(劳氏肉瘤病毒)与肉瘤相关。","HTLV与白血病的发生密切相关。","正确，HPV(人乳头瘤病毒)与宫颈癌密切相关。"],"basis":"DNA病毒如HPV→宫颈癌、EBV→伯基特淋巴瘤/鼻咽癌。"},"cards":null,"mem":"DNA病毒HPV/EBV，RNA病毒RSV/HTLV","big":"assets/img/ch13/big/p021.jpg"},{"i":21,"sec":"2.2 病毒","title":"DNA病毒","notes":"HBV病毒的碱基序列。体外培养的人肝癌细胞中，\n见到HBV病毒DNA整合到细胞DNA中。HBV整合到\n细胞 DNA中，能使细胞 DNA发生缺失、插入、转位、\n突变或易位等改变。\npapilloma virus，HPV）有 50余种亚型，与生殖道\n肿瘤的发生有密切关系，并与口腔、咽、喉、气管\n等处的乳头状瘤和皮肤疣等良性病变有关。\n【结合课本/笔记】病毒的基本知识●病毒（virus）——核酸分子（DNA或RNA）与蛋白质构    成的核酸-蛋白质复合体；根据病毒的核酸类型可以将其分为两大类：● DNA病毒与RNA病毒● 病毒的多样性）●类病毒（viroid）——仅由感染性的RNA构成；●朊病毒（prion） ——仅由感染性的蛋白质亚基构成；","page":22,"level":"掌握","img":"assets/img/ch13/p022.jpg","anim":null,"fig":null,"points":["乙型肝炎病毒(HBV)：人肝癌细胞DNA中发现有","乳头状瘤病毒：人乳头瘤状病毒（human"],"check":{"q":"关于DNA病毒与肿瘤，叙述正确的是（　）","o":["A. HBV是RNA病毒，不整合到宿主基因组中","B. HBV DNA可整合到人肝癌细胞DNA中，引起缺失、插入、易位等改变","C. HBV感染只会导致肝炎，不会引起细胞DNA改变","D. HPV有50余种亚型，仅与皮肤疣有关而与生殖道肿瘤无关"],"a":"B","e":"乙型肝炎病毒（HBV）是DNA病毒，其DNA可整合到人肝癌细胞DNA中，使细胞DNA发生缺失、插入、转位、突变或易位等改变；人乳头瘤病毒（HPV）有50余种亚型，与生殖道肿瘤密切相关，也与皮肤疣等病变有关。","oe":["错误：HBV属DNA病毒，其DNA可整合到细胞DNA中。","正确：HBV DNA可整合入肝癌细胞DNA，引起缺失、插入、易位等改变。","错误：HBV整合可使细胞DNA发生缺失、插入、易位等改变。","错误：HPV与生殖道肿瘤密切相关，也引起皮肤疣等病变。"]},"cards":null,"mem":"HBV整合致肝癌，HPV多亚型","big":"assets/img/ch13/big/p022.jpg"},{"i":22,"sec":"2.2 病毒","title":"乳头状瘤病毒   子宫颈癌","notes":"【图中英文对照】\n• The Nobel Prize in Physiology or Medicine 2008 —— 2008年诺贝尔生理学或医学奖\n• one half to Harald zur Hausen —— 半额授予 Harald zur Hausen\n• for discovery of human papilloma viruses causing cervical cancer —— 因发现导致宫颈癌的人乳头瘤病毒(HPV)\n【读图讲解】\n诺奖页：2008 年诺贝尔生理学或医学奖授予 Harald zur Hausen，表彰其发现人乳头瘤病毒(HPV)导致子宫颈癌。考点：HPV 与宫颈癌的因果关系及 HPV 疫苗。","page":23,"level":"掌握","img":"assets/img/ch13/p023.jpg","anim":null,"fig":null,"points":["THE","NOBEL","PRIZE","E IN","PHYSIOLOGY OR MEDICINE","2008","is awarded with one half to","HARALD ZUR"],"check":{"q":"关于HPV与宫颈癌关系的叙述，正确的是？","o":["A. 宫颈癌导致HPV感染","B. HPV是导致宫颈癌的病原体","C. HPV只感染动物不感染人","D. HPV与宫颈癌无因果关系"],"a":"B","e":"2008年诺奖授予zur Hausen，表彰其发现导致宫颈癌的人乳头瘤病毒(HPV)。","oe":["因果关系是HPV感染在先，导致宫颈癌。","正确，发现HPV导致宫颈癌而获2008年诺奖。","HPV是能感染人的一种致瘤病毒。","HPV与宫颈癌存在明确因果关系。"],"basis":"因发现导致宫颈癌的人乳头瘤病毒(HPV)"},"cards":null,"mem":"08诺奖zur Hausen：HPV致宫颈癌","big":"assets/img/ch13/big/p023.jpg"},{"i":23,"sec":"2.2 病毒","title":"人乳头瘤病毒（Human","notes":"papillomavirus，HPV）是一种嗜\n上皮性病毒，在人和动物中分布\n广泛，有高度的特异性。它是一\n种小的DNA病毒，直径45～55nm，\n衣壳呈二十面体立体对称。\n子宫颈\n肛门","page":24,"level":"掌握","img":"assets/img/ch13/p024.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于人乳头瘤病毒(HPV)的描述，正确的是？","o":["A. 是一种RNA病毒，无衣壳","B. 是直径约200nm的巨型病毒","C. 是一种细菌，可独立生活","D. 是一种小的DNA病毒，衣壳呈二十面体对称"],"a":"D","e":"HPV是嗜上皮性的小DNA病毒，直径45–55nm，衣壳呈二十面体立体对称，分布广泛且有高度特异性。","oe":["A. 错误：HPV是DNA病毒且有衣壳，不是无衣壳RNA病毒","B. 错误：HPV直径仅45~55nm，并非约200nm的巨型病毒","C. 错误：HPV是病毒而非细菌，必须依赖宿主细胞复制","D. 正确：HPV为小DNA病毒，衣壳二十面体对称，直径45~55nm"]},"cards":null,"mem":"HPV嗜上皮，小DNA，二十面体衣壳","big":"assets/img/ch13/big/p024.jpg"},{"i":24,"sec":"2.2 病毒","title":"(子宫颈)   (子宫)","notes":"【图中英文对照】\n• HPV infects cells deep within the cervical membrane —— HPV感染宫颈黏膜深层细胞\n• viral DNA incorporated into cell DNA → tumor —— 病毒DNA整合入细胞DNA→肿瘤\n• 90% resolve within 2 years; 0.8% develop cancer —— 90%两年内消退；0.8%发展为癌\n• Weeks / 2–4 months / 10–30 years —— 数周 / 2–4 月 / 10–30 年\n• Uterus / Cervix / Invasive cancer —— 子宫 / 宫颈 / 浸润性癌\n【读图讲解】\n示意图：HPV 感染发展为宫颈癌。病毒经宫颈黏膜裂口感染基底层细胞，病毒 DNA 整合入宿主 DNA，历经数周、2–4 月、10–30 年演进为浸润癌。考点：多数感染可消退，DNA 整合是恶变关键。","page":25,"level":"掌握","img":"assets/img/ch13/p025.jpg","anim":null,"fig":null,"points":["HPV infection","Uterus(子宫)","membrane.Ifacertainpartoftheviral DNA","Cervix","atumorwillform.","Frominfectiontomalignanttumor","Virus","Productionof"],"check":{"q":"关于HPV感染与宫颈癌，下列描述正确的是？","o":["A. 所有HPV感染均在2年内发展为癌","B. 病毒DNA整合入宿主细胞DNA是恶变的关键","C. HPV只感染宫颈表层已分化细胞","D. 病毒感染后即刻形成浸润癌"],"a":"B","e":"HPV感染宫颈黏膜深层细胞，病毒DNA整合入宿主DNA致肿瘤；约90%两年内消退，仅0.8%发展为癌。","oe":["A. 错误：约90%感染两年内消退，仅少数发展为癌","B. 正确：病毒DNA整合入宿主基因组是HPV致癌的关键步骤","C. 错误：HPV主要感染宫颈黏膜深层（基底层）细胞","D. 错误：从感染到浸润癌需10~30年，并非即刻形成"]},"cards":null,"mem":"HPV侵宫颈深层，DNA整合成癌","big":"assets/img/ch13/big/p025.jpg"},{"i":25,"sec":"2.2 病毒","title":"→we have vaccines specifically against","notes":"these viruses. The vaccines have proven\nto give more than 90% protection\nagainst the early stages of cancer that\nthese two HPV variants cause.\n【中文讲解·对照课本/考点】\n考点：2.2 病毒 ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• 核孔复合体（nuclear pore complex）：核孔并非单纯的孔道，而是一个复杂的盘状结构体系，每个复合体由一串大的排列成八角形的蛋白质颗粒组成，中央是含水的通道。\n\n【本页英文讲解】\n本页讲针对病毒的疫苗。关键术语：疫苗(vaccine)、人乳头瘤病毒(HPV, human papillomavirus)。已研制出专门针对这些病毒的疫苗，对这两种HPV变种(variant)引起的癌症早期阶段，能提供90%以上的保护。原文句子略有残缺但语义完整。考点：病毒(HPV)感染与宫颈癌的病因关系，以及疫苗用于肿瘤预防。","page":26,"level":"掌握","img":"assets/img/ch13/p026.jpg","anim":null,"fig":null,"points":null,"check":{"q":"针对HPV的疫苗预防肿瘤的基本原理是？","o":["A. 修复突变的p53基因","B. 预防HPV感染，从而阻断相关癌症的发生","C. 直接杀死已形成的癌细胞","D. 激活癌基因的表达"],"a":"B","e":"已研制出针对HPV的疫苗，对两种HPV变种引起的癌症早期阶段提供90%以上保护。","oe":["该疫苗不能修复突变的p53基因。","正确，疫苗针对病毒，提供90%以上保护，阻断癌症早期阶段。","疫苗作用于病毒预防，不直接杀癌细胞。","该疫苗不会引起癌基因的激活表达。"],"basis":"已研制出专门针对这些病毒的疫苗...提供90%以上的保护。"},"cards":null,"mem":"HPV疫苗>90%保护，防早期癌","big":"assets/img/ch13/big/p026.jpg"},{"i":26,"sec":"2.2 病毒","title":"逆转录病毒(RNA病毒)：","notes":"（HIV）等病毒都属于逆转录病毒。\n到宿主细胞的染色体中，成为细胞的组成部分，一般\n情况下受到正常细胞的调节控制，病毒处于静止状态，\n但受到化学致癌物、射线辐射等因素的作用后，可能\n被激活病毒表达而在体内诱发肿瘤。","page":27,"level":"掌握","img":"assets/img/ch13/p027.jpg","anim":null,"fig":null,"points":["人 T细胞白血病病毒(ATLV)和爱滋病病毒","逆转录病毒感染机体后，病毒的遗传信息整合"],"check":{"q":"关于逆转录病毒的致癌机制，叙述正确的是？","o":["A. 病毒遗传信息整合入宿主染色体，可被激活而诱发肿瘤","B. 病毒在细胞质中独立复制并立即杀死细胞","C. 病毒只感染细菌不感染动物细胞","D. 病毒DNA直接取代宿主全部基因组"],"a":"A","e":"逆转录病毒感染后遗传信息整合到宿主染色体中，一般静止，受化学致癌物或辐射作用后可被激活而诱发肿瘤。","oe":["正确，逆转录病毒整合入宿主染色体，受致癌因素作用后被激活诱发肿瘤。","病毒整合后常处于静止状态，非立即复制。","逆转录病毒感染动物细胞，如HIV。","整合的是病毒基因片段，并非取代全部基因组。"],"basis":"病毒的遗传信息整合到宿主细胞的染色体中...可能被激活病毒表达而在体内诱发肿瘤。"},"cards":null,"mem":"逆转录病毒整合宿主，可激活致癌","big":"assets/img/ch13/big/p027.jpg"},{"i":27,"sec":"2.2 病毒","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Genomic ssRNA / reverse transcriptase —— 基因组单链RNA / 逆转录酶\n• 1 Fusion → 2 reverse transcription → 3 transport to nucleus & integration → 4 transcription → 5 budding —— 1融合→2逆转录→3入核并整合为原病毒→4转录→5出芽\n• provirus / host-cell chromosomal DNA / nucleocapsid —— 原病毒 / 宿主染色体DNA / 核衣壳\n• Figure 4-49 —— 图4-49 逆转录病毒复制周期\n【读图讲解】\n逆转录病毒复制周期图：①融合进入→②逆转录→③入核并整合为原病毒→④转录→⑤出芽释放。考点：逆转录酶将 RNA 转为 DNA 并整合进宿主基因组。","page":28,"level":"掌握","img":"assets/img/ch13/p028.jpg","anim":null,"fig":null,"points":["Genomic","Reverse","ssRNA","transcriptase","Retrovirus","Host-cell","proteins","Budding"],"check":{"q":"逆转录病毒复制周期中，其单链RNA基因组首先被转化为？","o":["A. 双链DNA，再入核整合","B. 蛋白质","C. 直接翻译的mRNA","D. 新的RNA链"],"a":"A","e":"逆转录病毒以逆转录酶将单链RNA基因组转变为DNA，入核并整合为原病毒。","oe":["正确，逆转录酶将RNA逆转录为DNA后入核整合。","遗传信息先转为DNA，不是直接变蛋白质。","先逆转录为DNA，再整合并转录。","逆转录方向是RNA→DNA，不是RNA→RNA。"],"basis":"逆转录酶将RNA转为DNA并整合进宿主基因组。"},"cards":null,"mem":"融合→逆转录→整合→转录→出芽","big":"assets/img/ch13/big/p028.jpg"},{"i":28,"sec":"2.2 病毒","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Françoise Barré-Sinoussi (b.1947, Institut Pasteur) —— 弗朗索瓦丝·巴尔-西诺西(1947生，巴斯德研究所)\n• Luc Montagnier (b.1932, Université de Paris) —— 吕克·蒙塔尼耶(1932生，巴黎大学)\n• for discovery of human immunodeficiency virus (HIV) —— 因发现人类免疫缺陷病毒(HIV)，获2008年诺奖\n【读图讲解】\n人物照片：法国病毒学家 Françoise Barré-Sinoussi 与 Luc Montagnier，因发现人类免疫缺陷病毒(HIV)获 2008 年诺贝尔生理学或医学奖。考点：HIV 属逆转录病毒，可整合入宿主基因组。","page":29,"level":"掌握","img":"assets/img/ch13/p029.jpg","anim":null,"fig":null,"points":["for their discovery of","\"human immunodeficiency virus","Luc Montagnier was born in 1932 and is a","fessor andPresident atFondationMondiale","Recherche de Prevention SIDA in Paris.","Institut Pasteur in Paris."],"check":{"q":"人类免疫缺陷病毒(HIV)属于下列哪类病毒？","o":["A. 朊病毒","B. 逆转录病毒","C. 噬菌体","D. DNA肿瘤病毒"],"a":"B","e":"HIV属逆转录病毒，其RNA经逆转录为DNA后整合入宿主基因组。","oe":["朊病毒是蛋白质感染因子，与HIV无关。","正确，HIV属逆转录病毒，可整合入宿主基因组。","噬菌体感染细菌，HIV感染人。","HIV是RNA逆转录病毒，非DNA病毒。"],"basis":"HIV属逆转录病毒，可整合入宿主基因组。"},"cards":null,"mem":"发现HIV获08诺奖，属逆转录病毒","big":"assets/img/ch13/big/p029.jpg"},{"i":29,"sec":"2.2 病毒","title":"人免疫缺陷病毒， HIV","notes":"毒属，病人以全身免疫系\n统损伤为特征。\n能力下降，发生机会感染、\n恶性肿瘤及神经障碍等一\n系列临床综合症。","page":30,"level":"掌握","img":"assets/img/ch13/p030.jpg","anim":null,"fig":null,"points":["属于逆转录病毒科慢病","由于免疫缺陷，抗感染"],"check":{"q":"关于人免疫缺陷病毒（HIV），叙述正确的是（　）","o":["A. HIV属腺病毒科，感染后免疫系统功能增强","B. HIV属DNA病毒，直接整合后立即引起免疫损伤","C. HIV属逆转录病毒科慢病毒属，以全身免疫系统损伤为特征","D. HIV感染只引起机会感染，不伴发恶性肿瘤"],"a":"C","e":"HIV属逆转录病毒科慢病毒属，病人以全身免疫系统损伤为特征；由于免疫缺陷，抗感染能力下降，发生机会感染、恶性肿瘤及神经障碍等一系列临床综合症。","oe":["错误：HIV不属于腺病毒科，且导致免疫缺陷而非增强。","错误：HIV是RNA逆转录病毒，并非DNA病毒。","正确：HIV属逆转录病毒科慢病毒属，特征是全身免疫系统损伤。","错误：HIV感染还可发生机会感染、恶性肿瘤及神经障碍等。"]},"cards":null,"mem":"HIV慢病毒，免疫损伤致机会感染","big":"assets/img/ch13/big/p030.jpg"},{"i":30,"sec":"2.2 病毒","title":"The two","notes":"main\nclasses of\nimmune\nresponses.\n【中文讲解·对照课本/考点】\n考点：2.2 病毒 ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• ◆原癌基因存在于细胞基因组中(c-onc)，是控制细胞生长和分裂的基因。编码多种类型的蛋白质---细胞生长和分裂的调控因子。癌基因是控制细胞生长和分裂的原癌基因的一种突变形式。\n\n【本页英文讲解】\n本页主题为免疫应答(immune response)的两大主要类别。结合教材，免疫应答分为固有免疫(innate immunity)与适应性免疫(adaptive immunity)，后者包括体液免疫(humoral immunity，B细胞介导)和细胞免疫(cell-mediated immunity，T细胞介导)。考点：抗肿瘤免疫。","page":31,"level":"掌握","img":"assets/img/ch13/p031.jpg","anim":null,"fig":null,"points":null,"check":{"q":"适应性免疫应答中，由T细胞介导的是？","o":["A. 体液免疫","B. 固有免疫","C. 细胞免疫","D. 补体激活"],"a":"C","e":"免疫应答分固有免疫与适应性免疫，后者包括B细胞介导的体液免疫和T细胞介导的细胞免疫。","oe":["A. 错误：体液免疫由B细胞介导产生抗体，非T细胞","B. 错误：固有免疫是非特异性免疫，不属适应性免疫","C. 正确：细胞免疫由T细胞介导，是适应性免疫的重要分支","D. 错误：补体激活属固有免疫效应，与T细胞无直接对应"]},"cards":null,"mem":"固有+适应性(体液B/细胞T)免疫","big":"assets/img/ch13/big/p031.jpg"},{"i":31,"sec":"2.2 病毒","title":"T cell","notes":"foreign tumor cell\n【中文讲解·对照课本/考点】\n考点：2.2 病毒 ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• ◆原癌基因存在于细胞基因组中(c-onc)，是控制细胞生长和分裂的基因。编码多种类型的蛋白质---细胞生长和分裂的调控因子。癌基因是控制细胞生长和分裂的原癌基因的一种突变形式。\n\n【本页英文讲解】\n本页主题为T细胞(T cell)与外来肿瘤细胞(foreign tumor cell)的相互作用。T细胞是细胞免疫的主要执行者，其T细胞受体(TCR)识别肿瘤细胞提呈的抗原肽-MHC复合物，进而特异性杀伤肿瘤细胞，其中细胞毒性T细胞(CTL)作用关键。考点：机体抗肿瘤的细胞免疫机制与肿瘤免疫逃逸。原文为图示标签，信息简短。","page":32,"level":"掌握","img":"assets/img/ch13/p032.jpg","anim":null,"fig":null,"points":null,"check":{"q":"细胞毒性T细胞(CTL)特异性杀伤肿瘤细胞时，其TCR识别的是？","o":["A. 肿瘤细胞提呈的抗原肽-MHC复合物","B. 游离的肿瘤抗原蛋白","C. 肿瘤细胞的核DNA","D. 血清中的补体成分"],"a":"A","e":"T细胞受体(TCR)识别肿瘤细胞提呈的抗原肽-MHC复合物，进而特异性杀伤肿瘤细胞。","oe":["A. 正确：TCR识别抗原肽-MHC复合物，是特异性杀伤的前提","B. 错误：TCR不能识别游离抗原，须经MHC提呈","C. 错误：TCR识别的是肽-MHC而非核酸，肿瘤DNA不参与","D. 错误：补体成分非TCR配体，与细胞免疫识别无关"]},"cards":null,"mem":"T细胞识别杀伤外来肿瘤细胞","big":"assets/img/ch13/big/p032.jpg"},{"i":32,"sec":"2.2 病毒","title":"HIV通过外壳上的包","notes":"膜糖蛋白与T淋巴细\n胞表面的CD4分子结合，\n以膜融合方式进入细胞。\n(RdRp)和反转录酶均缺乏校正\n功能，\n※病毒基因组复制过程有很高\n的碱基错配率，变异非常频繁，\n给诊断和控制带来困难。","page":33,"level":"掌握","img":"assets/img/ch13/p033.jpg","anim":null,"fig":null,"points":["病毒复制依赖的RNA聚合酶"],"check":{"q":"关于HIV侵入细胞及其变异，叙述正确的是（　）","o":["A. HIV包膜糖蛋白与T细胞表面CD4结合，以膜融合方式进入细胞","B. HIV通过包膜糖蛋白与T细胞表面的CD8分子结合","C. HIV以胞吞方式进入细胞，无需膜融合","D. HIV复制所依赖的反转录酶具有校正功能，变异率低"],"a":"A","e":"HIV通过外壳上的包膜糖蛋白与T淋巴细胞表面的CD4分子结合，以膜融合方式进入细胞；其复制依赖的RNA聚合酶（RdRp）和反转录酶均缺乏校正功能，基因组复制碱基错配率很高，变异非常频繁。","oe":["正确：HIV包膜糖蛋白结合T细胞CD4分子，以膜融合方式进入细胞。","错误：结合的是CD4分子，而非CD8分子。","错误：HIV以膜融合方式进入细胞，而非单纯胞吞。","错误：反转录酶缺乏校正功能，病毒基因组错配率高、变异频繁。"]},"cards":null,"mem":"HIV包膜结合CD4入胞，酶无校正","big":"assets/img/ch13/big/p033.jpg"}],"mcq":[{"id":"ch13_mcq_4","mod":"2.2 病毒","modI":2,"q":"在细胞由 G2 进入 M 期过程中，MPF 中的 CDK 的 Thr14 和 Tyr15 的去磷酸化需要下列 哪种磷酸酶的催化（        ）。","o":["A．Weel","B．CAK","C．cdc25","D．cdc20"],"a":"C","e":"Weel 激酶使 Thr14 和 Tyr15 的磷酸化，CAK 催化 Thr161 的磷酸化。","kp":"ch13_s2_32","oe":["Weel是激酶，催化Thr14/Tyr15磷酸化而抑制MPF。","CAK催化Thr161磷酸化，而非去磷酸化。","cdc25磷酸酶催化Thr14和Tyr15去磷酸化，激活MPF，正确。","cdc20参与APC介导的泛素化，非该去磷酸化酶。"]},{"id":"ch13_mcq_5","mod":"2.2 病毒","modI":2,"q":"MPF 中的拍 p32 蛋白能被下列哪种蛋白的特异性抗体识别（             ）。","o":["A．p34","B．p56","C．cyclin B","D．p45"],"a":"A","e":"p32 同 p34 为同源物。","kp":"ch13_s2_23","oe":["p32与p34(cdc2)为同源物，可被抗p34抗体识别，正确。","p56与p32无同源性，不能识别p32。","cyclinB为调节亚基，与p32非同源物。","p45与p32无同源性，不能识别。"]},{"id":"ch13_mcq_9","mod":"2.2 病毒","modI":2,"q":"有活性的 CDK1 激酶符合下列何种描述？（             ）","o":["A．与周期蛋白以复合物形式存在","B．Thr161 去磷酸化","C．Thr14 和 Tyr15 磷酸化","D．与之结合的周期蛋白泛素化"],"a":"A","e":"CDK 激酶激活的途径：①CDK 蛋白本身不具有蛋白激酶活性；②当周期蛋白 B/A 含量积累到一定值时，二者相互结合形成复合体，但不表现出激酶活性；周期蛋白与 CDK 的结合是 CDK 激酶活性表现的先决条件；③在 wee1∕mik1 和 CAK 激酶的催化下 CDK 的 Thr14、Tyr15、Thr161 磷酸化，形成高度磷酸化的周期蛋白 CDK 复合体，但仍不具备激酶 活性；④在磷酸酶 Cdc25C 的催化下，Thr14 和 Tyr15 去磷酸化，CDK 激酶活性才能表现出 来。Thr161 位点保持磷酸化状态是 CDK1 激酶活性表现所必需的前提。","kp":"ch13_s2_32","oe":["CDK1须与周期蛋白B结合成复合物才具激酶活性，正确。","Thr161须保持磷酸化才有活性，去磷酸化则失活。","Thr14、Tyr15须去磷酸化才激活，磷酸化则抑制。","结合的周期蛋白泛素化导致其降解、CDK失活。"]}],"judge":[],"fill":[{"id":"ch13_fill_8","modI":2,"q":"Cdk 是一种蛋白激酶，必须与______结合后才具有活性。","a":"细胞周期蛋白","kp":"ch13_s2_23","oe":["CDK单独无活性，必须与细胞周期蛋白结合才被激活。"]},{"id":"ch13_fill_10","modI":2,"q":"在早熟染色体凝集实验中 G1 期的染色体呈现______，G2 期是______，而 S 期是______。","a":"细线状；双线状；粉末状","kp":"ch13_s2_26","oe":["G1期染色质尚未复制，PCC呈细线状。","G2期DNA已复制完成，PCC呈双线状。","S期DNA复制未完成，PCC呈粉末状。"]},{"id":"ch13_fill_16","modI":2,"q":"______是指在病毒基因组中存在的能促使细胞无限增殖进而癌变的 DNA 序列。","a":"病毒癌基因","kp":"ch13_s2_32","oe":["病毒癌基因是病毒基因组中能使细胞无限增殖癌变的序列。"]}],"short":[{"id":"ch13_short_15","modI":2,"q":"为什么说肿瘤既是一种基因性疾病，又是一种细胞性疾病？","a":"（1）肿瘤是一种基因性疾病的原因 肿瘤的发生是基因突变逐渐累积的结果。在分子层面上，肿瘤细胞的基因已经不同于正常细 胞的基因，肿瘤是发生一系列基因突变的累积结果，因此认为它是一种基因性疾病。 （2）肿瘤是一种细胞性疾病的原因 在细胞层面上，肿瘤细胞发生了很多异常变化。 ①细胞之间的黏着性降低，具有浸润性和转移性； ②细胞生长与分裂失去控制； ③体外培养的恶性转化细胞：具有无限增殖的潜能，贴壁性下降，有些可进行悬浮式培养； 失去运动和分裂的接触抑制，在软琼脂培养基中可形成细胞克隆。 因此从这个层面上讲，肿瘤又是一种细胞性疾病。","kp":"ch13_s2_23"},{"id":"ch13_short_18","modI":2,"q":"简述 MPF 的组成和在 G2∕M 期进程中的作用。","a":"（1）MPF 的组成 MPF 即成熟促进因子，是一种促进细胞成熟和分裂的调控性蛋白激酶。成熟促进因子的生 化成分是两个亚单位，一个是 Cdc2 蛋白，一个是周期蛋白 B。Cdc2 蛋白（p34cdc2）为催化 亚基，周期蛋白为调节亚基，二者结合后，表现出蛋白激酶活性。 （2）MPF 在 G2∕M 期进程中的作用 当 Cdc2 蛋白和周期蛋白结合后，MPF（CDK1）表现出蛋白激酶活性，磷酸化下游的蛋白 质分子，促进细胞周期由 G2 向 M 期转化，从而促进细胞成熟或分裂，Cdc2 蛋白是其催化 亚单位，周期蛋白是其调节亚单位。","kp":"ch13_s2_26"}],"calc":[],"term":[{"id":"ch13_term_2","modI":2,"term":"检验点（checkpoint）。","def":"检验点（checkpoint），又称限制点，指细胞对一些环境因素有一敏感点，可以限制细 胞通过周期，是控制 cell 增殖的关键。","kps":"","kp":"ch13_s2_31"},{"id":"ch13_term_4","modI":2,"term":"染色体超前凝集（PCC）。","def":"染色体超前凝集（PCC）是指与 M 期细胞融合的间期细胞发生的形态各异的染色体凝 集。","kps":"","kp":"ch13_s2_26"},{"id":"ch13_term_11","modI":2,"term":"肿瘤坏死因子","def":"肿瘤坏死因子是主要的死亡配体，最初发现存在于注射细菌脂多糖后的小鼠血清中，能 够使肿瘤组织出血坏死。肿瘤坏死因子主要由激活的单核-巨噬细胞分泌，诱导细胞凋亡和 诱发炎症反应是其主要的生理效应。肿瘤坏死因子的生物学功能是通过与细胞表面的受体结 合来实现的。","kps":"","kp":"ch13_s2_32"}]},{"i":3,"name":"2.3 癌的发生涉及2类基因：","slides":[{"i":33,"sec":"2.3.1原癌基因","title":"2.3 癌的发生涉及2类基因：","notes":"2.3.1原癌基因\n→Its presence contributes to cancer\n2.3.2 肿瘤抑制基因\n→Its absence (inactivation) contributes to cancer\n【中文讲解·对照课本/考点】\n考点：2.3 癌的发生涉及2类基因： ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• ◆原癌基因存在于细胞基因组中(c-onc)，是控制细胞生长和分裂的基因。编码多种类型的蛋白质---细胞生长和分裂的调控因子。癌基因是控制细胞生长和分裂的原癌基因的一种突变形式。\n\n【本页英文讲解】\n本页主题：癌的发生涉及2类基因。原癌基因(proto-oncogene)指其存在(激活)促进癌症发生；肿瘤抑制基因(tumor suppressor gene)指其缺失或失活促进癌症。关键考点：原癌基因多为显性、功能获得(gain of function)突变；抑癌基因通常隐性、功能丧失(loss of function)突变，需两个拷贝均失活(二次打击)。","page":34,"level":"掌握","img":"assets/img/ch13/p034.jpg","anim":null,"fig":null,"points":null,"check":{"q":"肿瘤抑制基因促进癌症发生的方式是？","o":["A. 其存在或激活","B. 其缺失或失活","C. 其点突变激活","D. 其过量表达"],"a":"B","e":"原癌基因的存在(激活)促癌，肿瘤抑制基因的缺失(失活)促癌。","oe":["其存在或激活促进癌症的是原癌基因。","正确，肿瘤抑制基因缺失/失活促癌。","激活型的点突变多见于原癌基因。","抑癌基因通常因失活而非过量表达促癌。"],"basis":"肿瘤抑制基因缺失(失活)促进癌症发生。"},"cards":null,"mem":"原癌存则促癌(显)，抑癌失则癌(隐)","big":"assets/img/ch13/big/p034.jpg"}],"mcq":[],"judge":[{"id":"ch13_judge_6","modI":3,"q":"癌的发生涉及两类基因：原癌基因和肿瘤抑制基因，这两类基因中的任何一个拷贝突变 都会导致癌变。（       ）","a":"错","e":"只有当肿瘤抑制基因两个拷贝都丢失了或两个拷 rA 都失活了才会使细胞失去增殖 的控制，只要肿瘤抑制基因有一个拷贝是正常的，就能够正常调节细胞的周期。","kp":"ch13_s3_33","oe":["原癌基因一个拷贝突变即可致癌，易把此规律错误地推到抑癌基因上。","抑癌基因需两个拷贝都失活才致癌，仅一个拷贝突变仍能正常调控细胞周期。"]}],"fill":[{"id":"ch13_fill_22","modI":3,"q":"癌的发生涉及两类基因：肿瘤抑制基因与癌基因。肿瘤抑制基因是细胞生长的______, 它们编码的蛋白质抑制细胞生长，并阻止细胞癌变。癌基因则是细胞生长的______,它们编 码的蛋白质使细胞生长不受控制，并促进细胞癌变。","a":"制动器；加速器","kp":"ch13_s3_33","oe":["抑癌基因是细胞生长的制动器，抑制细胞过度增殖。","癌基因是细胞生长的加速器，使生长不受控制。"]}],"short":[],"calc":[],"term":[{"id":"ch13_term_9","modI":3,"term":"复制起始点识别复合体（origin recognition complex，Ore）。","def":"复制起始点识别复合体含有 6 个亚单位，识别 DNA 复制起始位点并与之结合，是 DNA 复制起始所必需的。","kps":"","kp":"ch13_s3_33"}]},{"i":4,"name":"2.3.1 肿瘤抑制基因(Tumor suppressor gene)","slides":[{"i":34,"sec":"2.3.1     肿瘤抑制基因(Tum","title":"2.3.1     肿瘤抑制基因(Tumor suppressor gene)","notes":"中的负调控因子，细胞周期中起阻止周期进程的作用，\n并阻止细胞癌变。\n有当2个copy都失活或都丢失才使细胞增殖失控\n(即突变是隐性突变)。\ngene identified.\n【结合课本/笔记】● DNA肿瘤病毒与RNA肿瘤病毒致癌三、癌症产生是基因突变积累和自然选择的结果癌症主要是体细胞突变产生的遗传病，涉及到两大类与细胞增殖相关的基因的突变。●促进细胞增殖相关基因突变：原癌基因(proto-oncogene)突变形成癌基因(oncogene)●抑制细胞增殖相关基因突变：肿瘤抑制基因(tumor-suppressor gene)●细胞癌变是基因突变累积和自然选择的结果，所以患者多为年长者。●原癌基因与肿瘤抑制基因产物协调作用，避免细胞癌变","page":35,"level":"掌握","img":"assets/img/ch13/p035.jpg","anim":null,"fig":null,"points":["编码的蛋白抑制细胞生长，是正常细胞增殖过程","正常细胞中每一种抑癌基因都有2个copy，只","目前发现10多种，如 Rb、p53、p16","Rb gene-retinoblastoma, the first tumor suppressor","p53, mutated in 50% of all cancer cells"],"check":{"q":"关于肿瘤抑制基因，叙述正确的是（　）","o":["A. 抑癌基因突变后成为癌基因，促进细胞增殖","B. 一个拷贝突变即可导致细胞增殖失控，属显性突变","C. 目前仅发现Rb一种肿瘤抑制基因","D. 是细胞增殖的负调控因子，两个拷贝均失活才使细胞增殖失控"],"a":"D","e":"肿瘤抑制基因编码的蛋白抑制细胞生长，是正常细胞增殖过程中的负调控因子，阻止细胞周期进程并阻止细胞癌变；每种抑癌基因都有2个拷贝，只有当2个拷贝都失活或丢失才使细胞增殖失控（隐性突变），目前发现10多种如Rb、p53、p16。","oe":["错误：抑癌基因产物抑制生长，不会突变为促增殖的癌基因。","错误：抑癌基因突变通常为隐性，需两个拷贝都失活或丢失。","错误：已发现10多种，如Rb、p53、p16等，不止Rb一种。","正确：抑癌基因为负调控因子，需两个拷贝均失活才致增殖失控。"]},"cards":null,"mem":"抑癌两copy全失才癌，Rb/p53/p16","big":"assets/img/ch13/big/p035.jpg"},{"i":35,"sec":"2.3.1     肿瘤抑制基因(Tum","title":"Rb gene: 视网膜细胞瘤易感基因","notes":"The Rb protein first\nidentified through\nstudies of a rare\nchildhood eye tumor\ncalled retinoblastoma, in\nwhich the Rb protein is\nmissing or defective.\nproliferation in the developing retina视网膜, suggesting that the\nRb protein is particularly important for restraining cell division\nin this tissue.\n【中文讲解·对照课本/考点】\n考点：2.3.1 肿瘤抑制基因(Tumor suppressor gene) ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• 原癌基因（proto-oncogene）：正常细胞基因组中存在与病毒癌基因相似的一类基因，\f产物是正常细胞增殖所必不可少的，突变为癌基因则导致细胞生长失控。\n\n【本页英文讲解】\n本页主题为Rb基因。关键术语：视网膜细胞瘤(retinoblastoma)、Rb蛋白、细胞增殖。Rb蛋白最初通过研究罕见儿童眼肿瘤——视网膜母细胞瘤发现，患者Rb蛋白缺失或缺陷；Rb基因两个拷贝均丢失会导致发育中视网膜过度增殖，说明Rb蛋白在该组织抑制细胞分裂尤为重要。考点：Rb是首个被发现的抑癌基因。","page":36,"level":"掌握","img":"assets/img/ch13/p036.jpg","anim":null,"fig":null,"points":["The loss of both copies of the Rb gene leads to excessive cell"],"check":{"q":"关于Rb基因与视网膜母细胞瘤，叙述正确的是（　）","o":["A. Rb基因只需一个拷贝突变即可引发肿瘤","B. Rb是原癌基因，其过度表达导致视网膜母细胞瘤","C. 视网膜母细胞瘤由Rb蛋白过量表达引起","D. Rb是首个被发现的抑癌基因，两个拷贝均丢失致视网膜细胞过度增殖"],"a":"D","e":"Rb蛋白最初通过研究罕见儿童眼肿瘤——视网膜母细胞瘤发现，患者Rb蛋白缺失或缺陷；Rb基因两个拷贝均丢失会导致发育中视网膜过度增殖，说明Rb蛋白在该组织抑制细胞分裂尤为重要；Rb是首个被发现的抑癌基因。","oe":["错误：Rb为隐性突变，需两个拷贝均丢失或失活才致病。","错误：Rb为抑癌基因，并非原癌基因，其缺失或缺陷致病。","错误：患者Rb蛋白缺失或缺陷，而非过量表达。","正确：Rb是首个发现的抑癌基因，两个拷贝丢失使视网膜细胞过度增殖。"]},"cards":null,"mem":"Rb两拷贝失→视网膜母细胞瘤","big":"assets/img/ch13/big/p036.jpg"},{"i":36,"sec":"2.3.1     肿瘤抑制基因(Tum","title":"proteins required for S-phase activities. 视网膜细胞瘤蛋白(Rb)","notes":"prevents them from transcription several genes encoding\n结合转录因子E2F，组织该转录因子的激活。\n释放出E2F(once phosphorylated, Rb releases E2F)\nAllowing the E2F transcription factor to activate gene\nexpression, which marks the cell’s commitment to\nenter S phase. 启动S期相关蛋白基因的转录表达(e.g.\ncyclin E, cyclin A, DNA polymerase α)\ninactivate E2F, thereby removing certain restraints\nover the entry to S phase.\n【中文讲解·对照课本/考点】\n考点：2.3.1 肿瘤抑制基因(Tumor suppressor gene) ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• 基因表达（gene expression）：DNA 分子中由4种碱基不同组合而构成的遗传信息通过转绿“传抄”给 mRNA，进而 mRNA 通过遗传密码将其翻译成特定蛋白质氨基酸序列的过程，称为基因表达。\n• 转录（transcription）：在细胞核中以 DNA 为模板合成 mRNA 的过程，成为转录。\n\n【本页英文讲解】\n本页讲视网膜细胞瘤蛋白(Rb)调控G1/S转换的机制。关键术语：Rb、转录因子E2F、G1-Cdk与G1/S-Cdk。G1期Rb与E2F结合，阻止其转录S期所需基因；G1-Cdk和G1/S-Cdk使Rb磷酸化失活并释放E2F，启动S期相关蛋白基因(如cyclin E、cyclin A)表达，细胞进入S期。Rb失活则E2F失控。此即G1/S限制点核心机制。","page":37,"level":"掌握","img":"assets/img/ch13/p037.jpg","anim":null,"fig":null,"points":["During G1, Rb is normally bound to E2F proteins, which","G1-Cdk and G1/S-Cdk作用下，RB磷酸化后失活，","A cell that loses Rb activity would lose its ability to"],"check":{"q":"关于Rb蛋白调控G1/S转换的机制，叙述正确的是（　）","o":["A. Rb直接结合DNA，启动S期相关基因的转录","B. G1期Rb结合E2F阻止转录，Rb被Cdk磷酸化后释放E2F启动S期基因表达","C. E2F被Rb磷酸化后激活，促进S期基因表达","D. Rb蛋白始终抑制E2F，细胞因而不能进入S期"],"a":"B","e":"G1期Rb与转录因子E2F结合，阻止E2F激活；G1-Cdk和G1/S-Cdk使Rb磷酸化失活并释放E2F，E2F随即激活S期相关蛋白基因（如cyclin E、cyclin A）表达，细胞进入S期；Rb失活则失去对进入S期的约束。","oe":["错误：Rb通过结合并抑制转录因子E2F起作用，不直接结合DNA启动转录。","正确：G1期Rb结合E2F，Cdk磷酸化Rb后释放E2F，启动S期基因表达。","错误：被磷酸化的是Rb，E2F是Rb结合并调控的转录因子。","错误：Rb磷酸化失活后释放E2F，细胞可进入S期。"]},"cards":null,"mem":"Rb绑E2F，磷酸化释放启S期","big":"assets/img/ch13/big/p037.jpg"},{"i":37,"sec":"2.3.1     肿瘤抑制基因(Tum","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Control of G1–S phase transition / Restriction point —— G1–S期转换(限制点)调控\n• Growth factors → Cyclin D–CDK4/6 → phosphorylate RB → release E2F —— 生长因子→CyclinD-CDK4/6→磷酸化RB→释放E2F\n• E2F activates S-phase genes; p16 inhibits CDK4/6 —— E2F启动S期基因；p16抑制CDK4/6\n• Cyclin E/A–CDK2 → S phase; Centrosome duplication —— CyclinE/A-CDK2→S期；中心体复制\n• Figure 24-25 —— 图24-25 限制点：cyclinD过表达或p16、RB缺失常见于人类癌症\n【读图讲解】\n示意图：G1–S 转换（限制点）调控。生长因子激活 Cyclin D–CDK4/6，磷酸化 RB 释放 E2F，启动 DNA 合成基因转录并复制中心体；p16 抑制 CDK4/6。考点：cyclin D 过表达或 p16/RB 缺失使限制点失控，常见于人类癌症。","page":38,"level":"掌握","img":"assets/img/ch13/p038.jpg","anim":null,"fig":null,"points":["(b)Metazoans","Control of the G-S phase transition.","Rb","E2F","WCyclinEorcyclinAgene","Cyclin D","Growthfactors","CDK4/6"],"check":{"q":"G1–S期转换（限制点）调控中，E2F转录因子被释放是由于？","o":["A. Cyclin D–CDK4/6磷酸化RB","B. p16抑制CDK4/6","C. CDK1-cyclinB磷酸化RB","D. p53被降解"],"a":"A","e":"生长因子激活Cyclin D–CDK4/6，磷酸化RB使其释放E2F，E2F启动S期基因；p16抑制CDK4/6。","oe":["A. 正确：Cyclin D-CDK4/6磷酸化RB后释放E2F，启动S期","B. 错误：p16抑制CDK4/6，使RB不能释放E2F，抑制增殖","C. 错误：CDK1-cyclinB调控M期，不参与限制点的E2F释放","D. 错误：p53是基因组守卫，其降解并非E2F释放的机制"]},"cards":null,"mem":"CyclinD-CDK4/6磷Rb放E2F，p16抑","big":"assets/img/ch13/big/p038.jpg"},{"i":38,"sec":"2.3.1     肿瘤抑制基因(Tum","title":"p53基因是迄今发现与人类肿瘤相关性最高","notes":"的基因，编码一种53kDa的蛋白质。\n（本身为转录因子）\nDNA受到损伤后P53浓度快速上升。\n\n【读图讲解】\n该页为纯文字课件，归纳p53基因的要点：p53基因是迄今发现与人类肿瘤相关性最高的基因，编码一种53kDa的蛋白质；其活性也受磷酸化调控；该蛋白失活对肿瘤形成起重要作用；p53蛋白主要集中在核仁区，与DNA特异结合，本身为转录因子；正常G1细胞中p53蛋白浓度很低，当DNA受到损伤后其浓度快速上升。要点：p53是重要的抑癌基因与转录因子，参与DNA损伤应答，其失活与肿瘤发生密切相关。","page":39,"level":"掌握","img":"assets/img/ch13/p039.jpg","anim":null,"fig":null,"points":["其活性也受磷酸化调控","该蛋白失活对肿瘤形成起重要作用","p53蛋白主要集中在核仁区，与DNA特异结合","正常的G1细胞中， p53蛋白浓度很低，当"],"check":{"q":"关于p53基因及其蛋白，叙述正确的是（　）","o":["A. p53蛋白主要分布于细胞质膜，浓度恒定不受DNA损伤影响","B. p53蛋白与DNA非特异结合，不具转录因子活性","C. p53是原癌基因，其失活会抑制肿瘤发生","D. 编码53kDa蛋白，本身为转录因子，DNA损伤后浓度快速升高"],"a":"D","e":"p53基因是迄今发现与人类肿瘤相关性最高的基因，编码53kDa的蛋白质；p53蛋白主要集中在核仁区，与DNA特异结合，本身为转录因子，其活性受磷酸化调控；正常G1细胞中浓度很低，DNA损伤后浓度快速上升。","oe":["错误：p53主要集中在核仁区，DNA损伤后其浓度快速上升。","错误：p53与DNA特异结合，本身具转录因子活性。","错误：p53是重要的抑癌基因，失活促进而非抑制肿瘤形成。","正确：p53编码53kDa蛋白，为转录因子，DNA损伤后浓度快速上升。"]},"cards":null,"mem":"p53最高相关，53kDa转录因子","big":"assets/img/ch13/big/p039.jpg"},{"i":39,"sec":"2.3.1     肿瘤抑制基因(Tum","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• p53 → p21 → inhibits CDK1-cyclinB/A (cell cycle arrest) —— DNA损伤→p53→p21→抑制CDK1-cyclinB/A(周期阻滞)\n• p53 also activates DNA repair —— p53同时启动DNA修复\n• p53 / p21 / CDK1 / cyclinB/A / DNA —— p53 / p21 / CDK1 / cyclinB/A / DNA\n【读图讲解】\n信号通路图：DNA 损伤激活 p53，分两路——①p53 启动 p21 转录，p21 抑制 CDK1-cyclinB/A，阻止进入分裂（周期阻滞）；②启动 DNA 修复酶转录完成修复。考点：p53 为“基因组守卫”，损伤过重则促凋亡。","page":40,"level":"掌握","img":"assets/img/ch13/p040.jpg","anim":null,"fig":null,"points":["DNA损伤","WMINMINMIN","DNINNINNIN","p53","2.活化DNA","1.细胞周期阻滞","修复系统","XNXNINNXNMXNNNIN"],"check":{"q":"DNA损伤时p53介导细胞周期阻滞的途径是？","o":["A. 激活CDK1-cyclinB/A","B. 直接水解cyclinB","C. 抑制p21转录","D. 激活p21，抑制CDK1-cyclinB/A"],"a":"D","e":"DNA损伤激活p53，p53启动p21转录，p21抑制CDK1-cyclinB/A使周期阻滞，同时p53启动DNA修复。","oe":["A. 错误：p53是抑制而非激活CDK1-cyclinB/A复合物","B. 错误：p53不直接水解cyclinB，而是通过p21间接抑制","C. 错误：p53促进而非抑制p21转录，以此实现阻滞","D. 正确：p53激活p21，p21抑制CDK1-cyclinB/A导致周期阻滞"]},"cards":null,"mem":"p53→p21阻周期，兼启动修复","big":"assets/img/ch13/big/p040.jpg"}],"mcq":[{"id":"ch13_mcq_1","mod":"2.3.1     肿瘤抑制基因(Tumor suppressor gene)","modI":4,"q":"MPF（CDK1）调控细胞周期中（         ）。","o":["A．G1 期向 M 期转换","B．G2 期向 M 期转换","C．G1 期向 S 期转换","D．S 期向 G2 期转换"],"a":"B","e":"MPF＝cdc2（CDK1）＋clyclin B，调控细胞由 G2 期向 M 期转换。","kp":"ch13_s4_34","oe":["MPF不调控G1→M，该转换不由MPF负责。","MPF(CDK1-cyclinB)调控细胞由G2期进入M期，正确。","G1→S由CDK2-cyclinE等调控，非MPF。","S期向G2期的转换并非由MPF调控。"]},{"id":"ch13_mcq_11","mod":"2.3.1     肿瘤抑制基因(Tumor suppressor gene)","modI":4,"q":"调节细胞进出 S 期所必需的蛋白质激酶是（              ）。","o":["A．MPF","B．SPF","C．CDC","D．AC","E．PKC"],"a":"B","e":"A 项，MPF 是 M 期促进因子，能够调控细胞周期从 G2 到 M 期。B 项，SPF 是 S 期促进因子，能够调控细胞周期从 G1 到 S 期。C 项，CDC 是蛋白激酶催化亚基。D 项，AC 即腺苷酸环化酶，是膜整合蛋白，能够将 ATP 转变成 cAMP 引起细胞的信号应答，是 G 蛋 白偶联系统中的效应物。E 项，PKC 是信号调节系统中的蛋白激酶，主要起到激活下游级 联反应的作用。","kp":"ch13_s4_38","oe":["MPF调控G2→M，不调控G1→S。","SPF(S期促进因子)调控细胞由G1进入S期，正确。","CDC为蛋白激酶催化亚基，非使细胞进入S期的专一因子。","腺苷酸环化酶催化ATP生成cAMP，与S期进入无关。","PKC是信号通路蛋白激酶，非S期促进因子。"]}],"judge":[{"id":"ch13_judge_2","modI":4,"q":"磷酸化的 CDK2／cyclinE 不一定表现出激酶活力。（      ）","a":"对","e":"正如 CDK1 在 Thr14 和 Tyr15 磷酸化时无活性，只有 Thr14 和 Tyr15 去磷酸化。才 能被激活。","kp":"ch13_s4_36","oe":["CDK 需在特定 Thr 去磷酸化才被激活，磷酸化状态不当时可无激酶活性。","误以为只要 CDK2 与 cyclinE 结合并磷酸化，就必然具有激酶活力。"]},{"id":"ch13_judge_11","modI":4,"q":"在正常的二倍体细胞中，每一种抑癌基因都有两个拷贝，任何一个拷贝发生突变都会失 去抑癌作用。（           ）","a":"错","e":"在正常的二倍体细胞中，每一种肿瘤抑制基因有两个拷贝，只有当两个拷贝都丢失 或两个拷贝都失活才会使细胞失去增殖的控制，只要有一个拷贝是正常的，就能够正常调节 细胞的周期。相反，只要有一个拷贝的原癌基因突变，就会致癌。","kp":"ch13_s4_34","oe":["受原癌基因一个拷贝突变即致癌的影响，易类推到抑癌基因而误判。","二倍体细胞中抑癌基因需两个拷贝都丢失或失活才失去抑癌作用。"]}],"fill":[{"id":"ch13_fill_2","modI":4,"q":"CyclinB 的合成在 G1 晚期开始合成，在细胞中逐渐积累，到______末时达到最大值。","a":"G2","kp":"ch13_s4_36","oe":["CyclinB从G1晚期开始合成积累，到G2期末达到最大值。"]},{"id":"ch13_fill_3","modI":4,"q":"CDK1 分子中第 161 位苏氨酸的磷酸化是______的作用。","a":"激酶 CAK","kp":"ch13_s4_38","oe":["CDK1第161位苏氨酸的磷酸化由CDK活化激酶CAK催化。"]},{"id":"ch13_fill_4","modI":4,"q":"在泛素化途径降解蛋白质过程中，涉及______、______、______三种酶。","a":"泛素激活酶（E1）；泛素结合酶（E2）；泛素连接酶（E3）","kp":"ch13_s4_38","oe":["泛素激活酶E1消耗ATP将泛素激活。","泛素结合酶E2接受并转运活化的泛素。","泛素连接酶E3识别底物并介导其泛素化。"]},{"id":"ch13_fill_5","modI":4,"q":"APC 即______，其主要作用是______，______是它的有效正调控因子。","a":"后期促进因子；调节 M 期周期蛋白泛素化途径降解；cdc20 蛋白","kp":"ch13_s4_34","oe":["APC即后期促进复合物，又称后期促进因子。","APC通过泛素化途径促使M期周期蛋白降解。","cdc20是APC的有效正调控因子，激活其活性。"]},{"id":"ch13_fill_6","modI":4,"q":"细胞成熟促进因子包括两类蛋白质：①______；②______。","a":"P34cdc2 蛋白激酶；细胞周期蛋白","kp":"ch13_s4_38","oe":["成熟促进因子MPF含P34cdc2蛋白激酶。","MPF另一成分为细胞周期蛋白，起调节作用。"]},{"id":"ch13_fill_9","modI":4,"q":"Cdk 是一种周期蛋白依赖性的蛋白激酶，可使靶蛋白的______残基磷酸化。","a":"丝氨酸或苏氨酸","kp":"ch13_s4_38","oe":["CDK属丝氨酸/苏氨酸蛋白激酶，使靶蛋白相应残基磷酸化。"]},{"id":"ch13_fill_12","modI":4,"q":"MPF 包括______和______两种蛋白质。","a":"周期蛋白 B；CDKl 蛋白","kp":"ch13_s4_38","oe":["MPF含周期蛋白B这一调节亚基。","MPF另一成分是CDK1（p34cdc2）蛋白激酶。"]},{"id":"ch13_fill_19","modI":4,"q":"转录因子从功能上分为______和______。","a":"通用转录因子；特异转录因子","kp":"ch13_s4_38","oe":["通用转录因子参与所有基因转录起始，如TFIID。","特异转录因子识别特定基因的调控序列并调控其表达。"]},{"id":"ch13_fill_20","modI":4,"q":"转录因子包括两个结构域，一个是______，结合特异的 DNA 序列；另一个是______， 通过与其他蛋白作用而激活转录。","a":"DNA 结合结构域；转录激活结构域","kp":"ch13_s4_38","oe":["DNA结合结构域识别并结合靶基因特异的DNA序列。","转录激活结构域通过与其他蛋白作用而激活转录。"]}],"short":[{"id":"ch13_short_12","modI":4,"q":"P53 蛋白含有哪些功能结构域?哪些在肿瘤细胞中发生了突变？","a":"P53 包括一个转录激活结构域，一个识别特异的由 10 个碱基对组成的回文序列的 DNA 结合结构域，一个寡聚体化结构域，和一个结合非特异性损伤 DNA（单链）的 C 端结构域。 大部分的致癌突变位于位点特异性 DNA 结合结构域中。 ②基因扩增。某些造血系统恶性肿瘤（如前髓细胞性白血病）中，c-myc 扩增 8～32 倍。 ③DNA 重排。染色体的易位使原癌基因处于活跃转录基因强启动子的下游，将产生过度表 达。如 Burkitt 淋巴瘤细胞的染色体易位，使 c-myc 与 IG 重链基因的调控区为邻。 ④插入激活。某些不含 v-onc 的弱转化逆转录病毒具有冗长末端重复序列（LTR），含有启 动子、增强子，插入基因组后引起下游基因过表达。","kp":"ch13_s4_38"},{"id":"ch13_short_21","modI":4,"q":"概述细胞周期蛋白 B 在分裂后期的降解途径、机理和调控因素。","a":"（1）细胞周期蛋白 B 降解途径 细胞周期蛋白 B（cyclin B）在分裂后期的降解是通过泛素化-蛋白酶体降解途径。蛋白质的 泛素化需要泛素活化酶（E1）、泛素结合酶（E2，又称泛素载体蛋白）和泛素连接酶（E3） 的先后催化来完成，具体过程如下： ①E1 活化泛素分子； ②泛素分子转移至 E2； ③E3 催化形成异肽键； ④靶蛋白（cyclin B）被泛素化； ⑤蛋白酶体识别泛素化靶蛋白、ATP 水解驱动泛素移除、靶蛋白解折叠转入蛋白酶体核心 内被降解。 （2）周期蛋白 B 在分裂后期降解的机理 染色体与纺锤体结合后，Mad2 从动粒上消失，对 Cdc2 的抑制解除，Cdc2 是后期促进复合 物 APC 的正调控因子，因而能激活 APC，APC 是一种泛素化途径中的 E3 连接酶，促进 cyclin B 的降解。泛素化途径通过 E1、E2、E3 三个酶对需要降解的蛋白质打上多泛素链标签，具 有这个标签的蛋白质最终被蛋白酶体水解。 （3）周期蛋白 B 在分裂后期降解的调控因素 cyclin B 的调控因素包括其自身的破坏框和 APC，其自身破坏框氨基酸残基的突变或者 APC 的突变都能使 cyclin B 的降解被阻断。","kp":"ch13_s4_34"},{"id":"ch13_short_23","modI":4,"q":"细胞周期运转到分裂中期时，周期蛋白 A 和周期蛋白 B 通过泛素化途径降解。 （1）简述蛋白质的泛素化降解途径； （2）在上述泛素化降解途径中，蛋白降解的特异性（亦即确保只有该降解的蛋白被降解） 是如何实现的？ （3）周期蛋白 A 和 B 的分子结构中含有一段由 9 个氨基酸序列组成的破坏框。请设计一个 实验，证明该破坏框在周期蛋白 A 和 B 的泛素化降解途径中起了重要作用。 （4）如何证明周期蛋白 A 和 B 的存在对于驱动细胞周期从 M 期中期向后期的转化是必须 的？请提出两种不同的实验方案。","a":"（1）蛋白质的泛素化降解途径 泛素依赖性降解途径对于控制蛋白质寿命具有重要作用。蛋白质的泛素化需要泛素活化酶 （E1）、泛素结合酶（E2，又称泛素载体蛋白）和泛素连接酶（E3）的先后催化来完成， 具体过程如下： ①E1 活化泛素分子； ②泛素分子转移至 E2； ③E3 催化形成异肽键； ④靶蛋白被泛素化； ⑤蛋白酶体识别泛素化靶蛋白、ATP 水解驱动泛素移除、靶蛋白解折叠转入蛋白酶体核心 内被降解。 （2）确保只有该降解的蛋白被降解的机制 蛋白降解的特异性是因为降解的蛋白有其特异的 E3。E3 是泛素与底物蛋白特异性结合的决 定者，参与泛素对底物蛋白的识别，是决定泛素依赖的蛋白降解特异性的关键因子。 （3）证明该破坏框在周期蛋白 A 和 B 的泛素化降解途径中起重要作用的实验设计 将周期蛋白 A 和 B 的破坏框突变，引入到细胞中表达，结果显示周期蛋白 A 和 B 不能通过 泛素化途径降解。结论：此破坏框在周期蛋白 A 和 B 的泛素化降解途径中起了重要作用。 （4）证明周期蛋白 A 和 B 的存在对于驱动细胞周期从 M 期中期向后期的转化是必须的实 验方案 ①方案一：采用 siRNA 分别将编码周期蛋白 A、编码周期蛋白 B 的基因突变，使之不能表 达，通过收集培养细胞，观察其细胞周期变化情况。 具体设计三组： a．突变编码周期蛋白 A 基因； b．突变编码周期蛋白 B 基因； c．同时突变编码周期蛋白 A 基因和编码周期蛋白 B 基因。 结果：三组实验的细胞周期均停留在 M 期中期。 结论：周期蛋白 A 和 B 的存在对于驱动细胞周期从 M 期中期向后期的转化是必须的。 ②方案二：采用基因敲除分别将编码周期蛋白 A、编码周期蛋白 B 的基因突变，使之不能 表达，通过收集培养细胞，观察其细胞周期变化情况。实验分组同方案一。 结果：三组实验的细胞周期均停留在 M 期中期。 结论：周期蛋白 A 和 B 的存在对于驱动细胞周期从 M 期中期向后期的转化是必须的。","kp":"ch13_s4_38"}],"calc":[{"id":"ch13_calc_1","modI":4,"q":"为什么说蛋白质磷酸化-去磷酸化和泛素介导的蛋白质水解（UPP）的互相协调推动细胞 周期的运转？","a":"之所以说蛋白质磷酸化-去磷酸化和泛素介导的蛋白质水解（UPP）的互相协调推动细 胞周期的运转，是因为： （1）对细胞起核心作用的是 CDK 激酶，通过不同的周期蛋白与不同种类的 CDK 结合，在 细胞周期的不同周期表现出活性，因而对细胞周期的不同时期进行调节。 （2）CDK 激酶主要通过磷酸化与细胞周期进程相关的蛋白质，使它们在适当的时期表现出 相应的功能，促进细胞周期的运转，比如在 G2 向 M 期过渡的时候，MPF 被激活后，它可 以使组蛋白 H1 磷酸化，促进染色体凝集，使核纤层蛋白磷酸化，促使核纤层解聚，还可以 作用于微管蛋白，控制细胞周期中微管的动力学变化等，这些促使细胞由间期进入分裂期。 （3）去磷酸化在细胞周期中也起到很重要的作用，比如，CDK1 在非活性状态下其 Thr14 和 Tyr15 是磷酸化的，只有在 Cdc25 的作用下，使 Thr14 和 Tyr15 去磷酸化后才能表现出激 酶活性，从而调控细胞周期。再如，细胞运转到分裂中期后，被 MPF 磷酸化的蛋白去磷酸 化，细胞周期便从 M 期中期向后期转化。 （4）CDK 激酶被激活，其首先要与周期蛋白结合，而周期蛋白的浓度是随着细胞周期进程 的变化而变化的，从而使 CDK 激酶在特定时期表现活性，使得细胞周期正常运转，而周期 蛋白的周期性降解是通过泛素介导的蛋白质水解系统（UPPS）介导的。 综上所述，正是通过对蛋白质的磷酸化-去磷酸化和泛素介导的蛋白质水解系统对蛋白质的 降解，调控细胞周期中诸多蛋白的功能，并使其在正确的时间上执行功能，保证细胞周期的 正常运转。","kp":"ch13_s4_38"},{"id":"ch13_calc_2","modI":4,"q":"试述有丝分裂促进因子 MPF 在细胞周期中所起的作用，常用的研究细胞周期的方法有哪 些？","a":"（1）细胞周期中，M 期占用的时间最短，但细胞的形态变化最大。此阶段细胞的主要 生化特点是：RNA 合成停止，蛋白质合成减少，染色体高度螺旋化。由 G 期进入 M 期是细 胞周期中的另一个关键时期，M 期细胞质中存在一种染色质浓缩物质，即 M 期促进因子 MPF。如果将 M 期细胞与 G1、G2 或 S 期细胞融合，不论这些细胞中原来染色体状态如何， 都能使其浓缩。 （2）细胞周期常用研究方法：①细胞同步化法。可使处于不同细胞周期的细胞共同进入某 一特定阶段，即细胞同步化，有利于对细胞周期调控的研究。可分为物理法和化学法。物理 法有温度法、辐射法以及有丝分裂抖落法。化学法有 DNA 合成阻断法和细胞中期阻断法。 ②细胞周期调控研究法：免疫组化法、显微注射法、细胞融合法等。③3H-TdR 掺入法。利 用 3H-TdR 掺入法将同位素标记的 DNA 合成前体 TdR 掺入到 DNA 分子中．    可以对 S 期 DNA 合成动态过程加以研究，同时可以用于细胞周期的时间测定。","kp":"ch13_s4_34"},{"id":"ch13_calc_5","modI":4,"q":"简述 p34 ／cyclin B 蛋白激酶的发现过程。 cdc2","a":"p34cdc2／cyclin B 蛋白激酶的发现过程如下： （1）1970 年，R．T．Johnson 和 P．N．Rao 发现将 M 期细胞与其他间期细胞融合，可诱 导间期细胞染色质提前凝集成染色体，提示在 M 期细胞内可能存在一种诱导染色体凝缩的 因子，即细胞有丝分裂促进因子（MPF）； （2）1971 年，Y．Masui 和 C．L．Markert 用非洲爪蟾卵做实验，明确提出了 MPF 这一概 念； （3）1988 年，Lohka 等人从非洲爪蟾卵中分离出了微克级纯化的 MPF，证明其含 p32 和 p45 两种蛋白质，表现出蛋白激酶活性； （4）L．Hartwell 等获得了数十个芽殖酵母温度敏感型突变株，发现在限定温度下失去正常 分裂繁殖能力的现象是由于基因发生突变而引起的； （5）Paul Nurse 以裂殖酵母为材料发现，cdc2 基因突变导致细胞停留在 G2／M 期的交界处。 cdc2 基因的表达产物分子量为 34kDa，与其他蛋白质结合后具有激酶活性，能为 MPF 的 p32 抗体识别，能增强 MPF 活性，表明其为 p32 的同源物； （6）1983 年，Tim Hunt 首次发现海胆卵受精后，在其卵裂过程中两种蛋白质的含量随细胞 周期剧烈变化，分别命名为 cyclin A 和 cyclin B。后来证明酵母的 p56cdc13 为 cyclin B 的同源 物。 至此，MPF 蛋白的生化成分被确定了下来，它含有两个亚单位，Cdc2 蛋白为其催化亚单位， 周期蛋白为其调节亚单位。但二者结合后，表现出蛋白激酶活性。","kp":"ch13_s4_36"},{"id":"ch13_calc_6","modI":4,"q":"细胞周期中有哪些主要检验点，各起何作用？","a":"细胞周期中的主要检验点及其作用如下： （1）G1 期检验点：在 G1 期的晚期阶段，分裂的细胞可以通过一个特定时期进入 S 期，开 始细胞核 DNA 合成，并继续运行直到完成细胞分裂，这个特定时期称为检验点。在酵母中 称为起始点（start），在哺乳动物中称为限制点（R 点）。G1 期检验点的主要事件包括： DNA 是否损伤，细胞外环境是否适宜，细胞体积是否足够大等。防止 DNA 损伤或是突变 的细胞进入 S 期。 （2）S 期检验点：在 S 期内发生 DNA 损伤如 DNA 双链发生断裂时，S 期内部检验点被激 活，从而抑制复制起始点的启动，使 DNA 复制速度减慢，S 期延长，同时激活 DNA 修复 和复制叉的恢复等机制。S 期检验点的主要事件是 DNA 复制是否完成。出行损伤或未完成 则使 DNA 修复或减缓合成速度。 （3）G2 期检验点：细胞能否顺利进入 M 期要受到 G2 期检验点的控制，G2 期检验点的主要 事件包括：DNA 是否损伤，细胞是否已生长到合适大小，环境因素是否利于细胞分裂等。 阻止带有 DNA 损伤的细胞进入 M 期，使得细胞有充足的时间将损伤的 DNA 得以修复。 （4）中-后期检验点（纺锤体组装检验点）：可以阻止染色体分离，直到姐妹染色单体正确 地连接于有丝分裂纺锤体上。纺锤体组装检验点的主要事件包括：监控纺锤体微管与染色单 体动粒的连接，染色体在赤道面的队列和向纺锤体两极的分离等。若这些事件未正确完成， 检验点将阻止细胞从分裂中期进入后期。","kp":"ch13_s4_34"}],"term":[{"id":"ch13_term_10","modI":4,"term":"抑癌基因（turmor．suppressor gene）。","def":"编码的蛋白质直接或间接抑制细胞周期进程的基因，该基因发生的功能丢失突变是致癌 的。许多肿瘤抑制基因（如 RB，APC，BRCAl）的单个突变体等位的遗传能大大提高形成 某种类型肿瘤的危险性。抑癌基因又称肿瘤抑制基因，是细胞的制动器（brake），它们编 码的蛋白质抑制细胞生长，并阻止细胞癌变。在正常的二倍体细胞中，每一种抑癌基因都有 两个拷贝，只有当两个拷贝都丢失了或两个拷贝都失活了才会使细胞失去增殖的控制，只要 有一个拷贝是正常的，就能够正常调节细胞的周期。从此意义上说，抑癌基因的突变是功能 丧失性突变。","kps":"","kp":"ch13_s4_34"},{"id":"ch13_term_12","modI":4,"term":"癌基因 VS 肿瘤抑制因子 相关试题：oncogene","def":"（1）癌基因 癌基因是控制细胞生长和分裂的正常基因，其突变能引起正常细胞癌变。癌基因可分为病毒 癌基因和细胞癌基因两大类。病毒癌基因是指反转录病毒的基因组里带有可使受病毒感染的 宿主细胞发生癌变的基因。细胞癌基因即原癌基因，是指在正常细胞基因组中对细胞正常生 命活动起主要调控作用的基因，在发生突变或被异常激活后变成具有致癌能力的癌基因。 （2）肿瘤抑制因子 肿瘤抑制因子又称抑癌基因，是正常细胞增殖过程中的负调控因子，它编码的蛋白在细胞周 期的检验点上起阻遏周期进程的作用。抑癌基因有两个拷贝，其中一个拷贝正常，可保证正 常的调控作用，两个拷贝都丢失或失活，才能引起细胞增殖的失控。 抑癌基因与癌基因之间的区别：癌基因的突变性质为显性，抑癌基因的突变性质为隐性。","kps":"","kp":"ch13_s4_34"}]},{"i":5,"name":"2.3.2 原癌基因(proto-oncogene)","slides":[{"i":40,"sec":"2.3.2 原癌基因(proto-onc","title":"2.3.2 原癌基因(proto-oncogene)","notes":"细胞的正常基因，编码的蛋白在细胞中对细胞\n周期、细胞生长增殖起正调节作用，突变后成\n为癌基因。eg. 生长因子、生长因子受体、细胞信号\n分子、核转录因子等。\n癌基因(oncogene)：\n多数癌基因都是由与细胞生长和分裂有关的正常\n基因（原癌基因）突变而来。突变能导致该基因所编\n码的蛋白过量或过度活化，从而导致细胞过度增殖，\n这类突变的基因称为癌基因。\n而将其未突变的细胞中同源物称为原癌基因。\n【结合课本/笔记】● DNA肿瘤病毒与RNA肿瘤病毒致癌三、癌症产生是基因突变积累和自然选择的结果癌症主要是体细胞突变产生的遗传病，涉及到两大类与细胞增殖相关的基因的突变。●促进细胞增殖相关基因突变：原癌基因(proto-oncogene)突变形成癌基因(oncogene)●抑制细胞增殖相关基因突变：肿瘤抑制基因(tumor-suppressor gene)●细胞癌变是基因突变累积和自然选择的结果，所以患者多为年长者。●原癌基因与肿瘤抑制基因产物协调作用，避免细胞癌变","page":41,"level":"掌握","img":"assets/img/ch13/p041.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于癌基因与原癌基因的关系，正确的是？","o":["A. 癌基因是正常细胞基因组固有的基因","B. 原癌基因由癌基因突变而来","C. 两者是同一基因的不同名称","D. 癌基因多由原癌基因突变而来"],"a":"D","e":"原癌基因是正常基因，突变后成为癌基因，导致编码蛋白过量或过度活化。","oe":["原癌基因才是正常细胞基因组中固有的基因。","顺序颠倒，是原癌基因突变形成癌基因。","癌基因是原癌基因的突变形式，二者不同。","正确，癌基因由原癌基因突变形成，产物过量或过度活化。"],"basis":"多数癌基因都是由与细胞生长和分裂有关的正常基因（原癌基因）突变而来。"},"cards":null,"mem":"原癌正调控，突变过量成癌基因","big":"assets/img/ch13/big/p041.jpg"},{"i":41,"sec":"2.3.2 原癌基因(proto-onc","title":"differentiation and that have the potential to subvert (颠","notes":"Proto-oncogenes:\na variety of normal cellular genes that encodes proteins\nusually involved in regulation of cell growth or\n覆，暗中破坏) the cell’s own activities and push the\ncell toward the malignant state.\nA proto-oncogene can be mutated into a cancer-\nprotmoting oncogene, enther by changing the protein-\ncoding segment or by altering its expression.\n目前已发现的原癌基因有100多个。\n【中文讲解·对照课本/考点】\n考点：2.3.2 原癌基因(proto-oncogene) ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• 原癌基因（proto-oncogene）：正常细胞基因组中存在与病毒癌基因相似的一类基因，\f产物是正常细胞增殖所必不可少的，突变为癌基因则导致细胞生长失控。\n• 癌基因（oncogenes）：是控制细胞生长和分裂的正常基因的一种突变形式，能引起正常细胞癌变。\n\n【本页英文讲解】\n本页定义原癌基因(proto-oncogene)。它是一类正常细胞基因，编码通常参与细胞生长或分化调节的蛋白，具有颠覆细胞自身活动、推动细胞走向恶性状态(malignant state)的潜能。原癌基因可通过改变蛋白编码区或其表达，突变成为促癌的癌基因(oncogene)。原文指出目前已发现的原癌基因有100多个。考点：原癌基因的激活机制。","page":42,"level":"掌握","img":"assets/img/ch13/p042.jpg","anim":null,"fig":null,"points":null,"check":{"q":"原癌基因转变为癌基因的途径可包括？","o":["A. 只能通过染色体数目加倍","B. 必须丢失两个等位基因","C. 只能通过病毒感染","D. 改变蛋白编码区或改变其表达"],"a":"D","e":"原癌基因可通过改变蛋白编码区或改变表达水平，突变为促癌的癌基因，目前发现的原癌基因有100多个。","oe":["A. 错误：激活机制多样，并非只能通过染色体数目加倍","B. 错误：丢失两个等位基因是抑癌基因失活方式，非原癌基因","C. 错误：除病毒外，点突变、易位等也可激活原癌基因","D. 正确：编码区突变或表达改变均可使原癌基因激活为癌基因"]},"cards":null,"mem":"原癌可编码变或表达变，已百余个","big":"assets/img/ch13/big/p042.jpg"},{"i":42,"sec":"2.3.2 原癌基因(proto-onc","title":"原癌基因主要有","notes":"① 生长因子\n②生长因子受体 growth factor receptor,\n③ 细胞信号转导过程中的蛋白－The signal-\ntransduction proteins (e.g. Ras and Src),\n④转录因子 transcription factors in the nucleus (e.g.\nmyc),\n⑤ 细胞周期调节蛋白\n⑥抑制凋亡－The genes that resist apoptosis and\npromote survival, e.g.Bcl-2\n【中文讲解·对照课本/考点】\n考点：2.3.2 原癌基因(proto-oncogene) ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• 原癌基因（proto-oncogene）：正常细胞基因组中存在与病毒癌基因相似的一类基因，\f产物是正常细胞增殖所必不可少的，突变为癌基因则导致细胞生长失控。\n• 转录（transcription）：在细胞核中以 DNA 为模板合成 mRNA 的过程，成为转录。\n\n【本页英文讲解】\n列举原癌基因主要类别：①生长因子(growth factor)；②生长因子受体；③细胞信号转导蛋白(signal-transduction proteins)；④核内转录因子(transcription factors，如myc)；⑤细胞周期调节蛋白；⑥抑制凋亡、促进存活的基因(如Bcl-2)。考点：按编码蛋白在信号通路中的位置，任一环节过度激活均可促癌。","page":43,"level":"掌握","img":"assets/img/ch13/p043.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列均属原癌基因编码产物类别，其中myc属于？","o":["A. 核内转录因子","B. 生长因子","C. 受体酪氨酸激酶","D. G蛋白"],"a":"A","e":"原癌基因产物包括生长因子、受体、信号转导蛋白(Ras、Src)、核内转录因子(如myc)、周期调节蛋白及抗凋亡蛋白(Bcl-2)。","oe":["A. 正确：myc编码核内转录因子，是最典型的原癌基因之一","B. 错误：生长因子如sis编码的PDGF，myc并非生长因子","C. 错误：受体酪氨酸激酶如erb-B、fms，myc不属此类","D. 错误：G蛋白如Ras，myc是转录因子而非G蛋白"]},"cards":null,"mem":"生长因子、受体、Ras、myc、周期、Bcl-2","big":"assets/img/ch13/big/p043.jpg"},{"i":43,"sec":"2.3.2 原癌基因(proto-onc","title":"原癌基因    功能                 相关肿瘤","notes":"sis     生长因子               Erwing网瘤\nerb-B   受体酪氨酸激酶，EGF受体      星形细胞瘤、乳腺癌、卵巢癌、\n肺癌、胃癌、唾腺癌\nfms     受体酪氨酸激酶，CSF-1 受体   髓性白血病\n肺癌、结肠癌、膀胱癌、直肠\nras     G-蛋白\n癌\nsrc     非受体酪氨酸激酶           鲁斯氏肉瘤\nAbl-1   非受体酪氨酸激酶           慢性髓性白血病\nraf     MAPKKK，丝氨酸/苏氨酸激酶   腮腺肿瘤\nvav     信号转导连接蛋白           白血病\nBurkitt 淋巴瘤、肺癌、早幼\nmyc     转录因子\n粒白血病\nmyb     转录因子               结肠癌\nfos     转录因子               骨肉瘤\njun     转录因子\nerb-A   转录因子               急性非淋巴细胞白血病\nbcl-1   细胞凋亡               B细胞淋巴瘤","page":44,"level":"掌握","img":"assets/img/ch13/p044.jpg","anim":null,"fig":null,"points":null,"check":{"q":"在原癌基因产物对应关系中，myc编码的蛋白属于？","o":["A. 转录因子","B. 生长因子","C. G蛋白","D. 受体酪氨酸激酶"],"a":"A","e":"myc编码转录因子；sis为生长因子、erb-B/fms为受体酪氨酸激酶、ras为G蛋白。","oe":["正确，myc编码核内转录因子。","sis基因编码的产物是生长因子。","ras基因编码的产物是G蛋白。","erb-B、fms编码受体酪氨酸激酶。"],"basis":"myc 转录因子"},"cards":null,"mem":"sis因子，ras G蛋白，src/abl激酶，myc","big":"assets/img/ch13/big/p044.jpg"},{"i":44,"sec":"2.3.2 原癌基因(proto-onc","title":"Oncogene collaboration in transgenic mice.","notes":"【结合课本/笔记】美国国立卫生研究院（NIH）在1988年底发表的一份题为《什麽是当今科研领域的热门话题？》（“What is popular in research today？”）的调查报告中指出，目前全球研究最热门的是●三种疾病：●癌症（cancer）●心血管病（cardiovascular diseases）●爱滋病和肝炎等传染病（infectious diseases：AIDS，hepatitis）●五大研究方向：●细胞周期调控（cell cycle control）；●细胞凋亡（ cell apoptosis）；●细胞衰老（cellular senescence）；●信号转导（signal transduction）；●DNA的损伤与修复\n【中文讲解·对照课本/考点】\n考点：2.3.2 原癌基因(proto-oncogene) ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程\n• 原癌基因（proto-oncogene）：正常细胞基因组中存在与病毒癌基因相似的一类基因，\f产物是正常细胞增殖所必不可少的，突变为癌基因则导致细胞生长失控。\n\n【本页英文讲解】\n本页标题为“转基因小鼠中的癌基因协同作用(Oncogene collaboration in transgenic mice)”。原文仅有标题，其余内容需结合实验结论理解：单个癌基因往往不足以致瘤，多个癌基因(如myc与Ras)协同作用才能有效诱导肿瘤发生。考点：癌症发生的多步骤、多基因协同假说。对应翟中和教材关于癌基因协同致癌的内容。","page":45,"level":"掌握","img":"assets/img/ch13/p045.jpg","anim":null,"fig":null,"points":null,"check":{"q":"转基因小鼠实验中的“癌基因协同作用”说明？","o":["A. 任一癌基因单独即可稳定致瘤","B. 癌基因只与化学致癌物协同致癌","C. 癌基因协同作用与肿瘤发生无关","D. 单个癌基因往往不足以致瘤，需多个癌基因协同"],"a":"D","e":"癌基因协同作用表明单个癌基因常不足以致瘤，需多个癌基因（如myc与Ras）协同才能有效诱导肿瘤。","oe":["A. 错误：单个癌基因通常不足以诱导肿瘤，需协同作用","B. 错误：协同发生在癌基因之间，并非只与化学致癌物","C. 错误：该实验正说明癌基因协同与肿瘤发生密切相关","D. 正确：多个癌基因协同才有效致瘤，体现癌症多步骤多基因"]},"cards":null,"mem":"热门：周期/凋亡/衰老/信号/修复","big":"assets/img/ch13/big/p045.jpg"},{"i":45,"sec":"2.3.2 原癌基因(proto-onc","title":"原癌基因转为癌基因的几种可能","notes":"The accidents that can make a proto-oncogene\noveractive and convert it into an oncogene\n点突变\n基因扩增              染色体易位\n产生过量、正常量但生物活性异常的原癌基因编码的蛋白产\n物，最终导致细胞增殖失控and/or细胞凋亡减弱。\n【中文讲解·对照课本/考点】\n考点：2.3.2 原癌基因(proto-oncogene) ｜ 教材：第十四章 细胞增殖调控与癌细胞 · 第一节 增殖调控（p299–309）/ 第二节 癌细胞（p310–317）\n• 原癌基因（proto-oncogene）：正常细胞基因组中存在与病毒癌基因相似的一类基因，\f产物是正常细胞增殖所必不可少的，突变为癌基因则导致细胞生长失控。\n\n【本页讲解】\n本页讲解原癌基因转变为癌基因（oncogene）的几种可能机制。主要包括三类：点突变（point mutation）、基因扩增（gene amplification）和染色体易位（chromosomal translocation）。这些改变可产生过量的、或正常量但生物活性异常的原癌基因编码蛋白产物，最终导致细胞增殖失控和/或细胞凋亡减弱，从而促进肿瘤发生。考点联系翟中和《细胞生物学》第十四章细胞增殖调控与癌细胞第二节，需掌握原癌基因与癌基因的区别及其激活机制。","page":46,"level":"掌握","img":"assets/img/ch13/p046.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列哪项不属于原癌基因转变为癌基因的常见机制？","o":["A. 染色体易位","B. 基因扩增","C. 基因完全缺失","D. 点突变"],"a":"C","e":"原癌基因转变为癌基因的常见机制有点突变、基因扩增和染色体易位。","oe":["染色体易位也是常见激活机制之一。","基因扩增可致蛋白过量，是常见机制。","正确，原癌基因转变为癌基因的机制不含完全缺失。","点突变是较常见的激活机制之一。"],"basis":"点突变、基因扩增、染色体易位"},"cards":null,"mem":"原癌变癌：点突变、扩增、易位","big":"assets/img/ch13/big/p046.jpg"},{"i":46,"sec":"2.3.2 原癌基因(proto-onc","title":"1．点突变","notes":"ras基因家族，均以点突变为主，如膀胱癌细胞中克隆出来\n的c-Ha-ras基因与正常细胞的相比仅有一个核苷酸的差异。\n2．DNA重排\n原癌基因在正常情况下表达水平较低，当发生染色体的易\n位或倒位时，处于活跃转录基因强启动子的下游，而产生过\n度表达。\n3．插入激活\n病毒DNA插入宿主DNA中，引起插入突变。如逆转录病毒\nMoSV感染鼠类成纤维细胞后，它们不编码蛋白质，而含有启\n动子、增强子等调控成分，病毒基因组的LTR整合到细胞癌基\n因c-mos邻近处，使c-mos处于LTR的强启动子和增强子作用之\n下而被激活，导致成纤维细胞转化为肉瘤细胞。\n4．基因扩增\n在某些造血系统恶性肿瘤中，癌基因扩增是一个极常见的\n特征，如前髓细胞性白血病细胞系和这类病人的白血病细胞\n中，c-myc扩增8~32倍。","page":47,"level":"掌握","img":"assets/img/ch13/p047.jpg","anim":null,"fig":null,"points":null,"check":{"q":"膀胱癌细胞中c-Ha-ras基因与正常细胞相比的差异是？","o":["A. 整个基因缺失","B. 整条染色体丢失","C. 仅有一个核苷酸的差异","D. 基因扩增8倍"],"a":"C","e":"膀胱癌细胞中克隆的c-Ha-ras基因与正常细胞相比仅有一个核苷酸的差异，是点突变的典型例证。","oe":["A. 错误：该例为点突变而非基因缺失，缺失多致失活","B. 错误：染色体丢失多涉及抑癌基因，与该例点突变不符","C. 正确：c-Ha-ras仅一个核苷酸差异，属典型点突变激活","D. 错误：c-myc可见扩增8~32倍，c-Ha-ras差异是点突变"]},"cards":null,"mem":"点突变ras、重排、插入LTR、扩增myc","big":"assets/img/ch13/big/p047.jpg"},{"i":47,"sec":"2.3.2 原癌基因(proto-onc","title":"抑癌基因与原癌基因突变效果的比较","notes":"抑癌基因\n原癌基因\n显性突变\n隐性突变\n\n【读图讲解】\n该图比较抑癌基因与原癌基因突变的效应。左侧(a)抑癌基因：两个同源拷贝中仅一个突变时细胞仍正常生长，需两个拷贝都突变才会失去生长控制，属隐性突变。右侧(b)原癌基因：正常细胞生长依赖原癌基因产物，只要一个拷贝突变成为癌基因(oncogene)即导致生长失控，属显性突变。下方培养皿示意转化细胞堆积。要点：抑癌基因需“两次打击”隐性失活，原癌基因一次显性激活即可致癌。","page":48,"level":"掌握","img":"assets/img/ch13/p048.jpg","anim":null,"fig":null,"points":null,"check":{"q":"抑癌基因失活导致细胞生长失控通常需要？","o":["A. 只需一个拷贝突变","B. 基因扩增","C. 两个同源拷贝均发生突变","D. 单个拷贝表观沉默即可"],"a":"C","e":"抑癌基因属隐性突变，需两个同源拷贝都突变才失去生长控制；原癌基因一个拷贝突变即显性致癌。","oe":["A. 错误：只需一个拷贝突变是原癌基因的显性激活特点","B. 错误：基因扩增是原癌基因激活机制，非抑癌基因失活","C. 正确：抑癌基因需两个拷贝均突变（两次打击）才失活","D. 错误：单拷贝表观沉默通常不足以完全失活抑癌基因"]},"cards":null,"mem":"抑癌隐性两次打击，原癌显性一次","big":"assets/img/ch13/big/p048.jpg"}],"mcq":[{"id":"ch13_mcq_7","mod":"2.3.2 原癌基因(proto-oncogene)","modI":5,"q":"在癌基因所编码的五类主要的蛋白中，哪类蛋白的突变是细胞癌变的主要原因?（             ）。","o":["A．生长因子","B．转录因子","C．信号转导通路蛋白","D．细胞周期蛋白"],"a":"C","e":"信号转导通路蛋白突变是细胞癌变的主要原因，如人类各种癌症中约 30％的癌症 是信号通路中的 ras 基因突变引起的。","kp":"ch13_s5_40","oe":["生长因子类癌基因产物的突变并非细胞癌变的主要原因。","转录因子类癌基因产物的突变并非主要原因。","约30%癌症由ras等信号转导通路蛋白基因突变引起，是主要原因，正确。","细胞周期蛋白类并非细胞癌变的主要原因。"]},{"id":"ch13_mcq_8","mod":"2.3.2 原癌基因(proto-oncogene)","modI":5,"q":"抑癌基因之一是（          ）。","o":["A．c-fos","B．v-jun","C．v-raf","D．p53"],"a":"D","e":"前三个基因均为细胞增殖的正性调控基因。","kp":"ch13_s5_47","oe":["c-fos是原癌基因，属增殖正性调控基因。","v-jun为癌基因，属增殖正性调控基因。","v-raf为癌基因，属增殖正性调控基因。","p53是著名抑癌基因，其失活与多种肿瘤相关，正确。"]}],"judge":[{"id":"ch13_judge_4","modI":5,"q":"细胞周期蛋白及其磷酸化状态两者决定一个 Cdk 蛋白是否具有酶活性。（                  ）","a":"对","e":"cdk 与细胞周期蛋白的聚合是其活性所必需的，而且细胞周期蛋白／Cak 复合物的 激活依赖于 cdk 蛋白上某些特殊部位的磷酸化和另一些部位的去磷酸化。","kp":"ch13_s5_42","oe":["Cdk 需与周期蛋白结合，并经特定部位磷酸化或去磷酸化，才具酶活性。","若认为 Cdk 仅靠周期蛋白结合即可激活、与磷酸化无关，则说法错误。"]},{"id":"ch13_judge_5","modI":5,"q":"肿瘤细胞就是一类基因突变的干细胞。（             ）","a":"错","e":"肿瘤组织中并非所有细胞都是干细胞，只有少数细胞是肿瘤干细胞。","kp":"ch13_s5_47","oe":["肿瘤细胞具有无限增殖等干细胞样特性，易被笼统视为基因突变的干细胞。","肿瘤组织中仅少数为肿瘤干细胞，多数是分化程度不同的肿瘤细胞，不能等同。"]},{"id":"ch13_judge_8","modI":5,"q":"抑癌基因突变能转变成癌基因从而致癌。（              ）","a":"错","e":"抑癌基因发生突变后会失去抑癌功能。","kp":"ch13_s5_47","oe":["抑癌基因与原癌基因都涉及肿瘤发生，易混淆而认为前者可变为癌基因。","抑癌基因突变后是丧失抑癌功能，不会转变为癌基因，二者机制不同。"]},{"id":"ch13_judge_12","modI":5,"q":"在细胞周期的 G2 期早期和 M 期早期，周期蛋白的浓度最高。（                ）","a":"错","e":"G2 期早期的周期蛋白浓度不是最高的。","kp":"ch13_s5_40","oe":["M 期 cyclin 浓度高，易把 G2 期早期也一并认为最高，故误判。","cyclin 浓度在 M 期最高，G2 期早期尚未达峰值，故并非最高。"]}],"fill":[{"id":"ch13_fill_1","modI":5,"q":"细胞周期调控中的两个主要因子______和______，其中______是催化亚基，______相当 于调节亚基。","a":"周期蛋白；周期蛋白依赖的蛋白激酶；周期蛋白依赖的蛋白激酶；周期蛋白查看答 案","kp":"ch13_s5_44","oe":["两大因子即周期蛋白和周期蛋白依赖的蛋白激酶(CDK)。","另一因子是周期蛋白依赖的蛋白激酶，即CDK。","CDK具有激酶活性，是催化亚基，使靶蛋白磷酸化。","周期蛋白无酶活性，结合CDK并调节其活性，为调节亚基。"]},{"id":"ch13_fill_7","modI":5,"q":"MPF 和 SPF 是两种控制细胞周期的不同促进因子，前者由                      与______组  成，后者由                 与______组成。","a":"周期蛋白 B；周期蛋白 A","kp":"ch13_s5_40","oe":["MPF由p34cdc2与周期蛋白B组成，故第一空为周期蛋白B。","SPF由p34cdc2与周期蛋白A组成，故第二空为周期蛋白A。"]},{"id":"ch13_fill_11","modI":5,"q":"裂殖酵母细胞周期的引擎蛋白是______蛋白。","a":"P34cdc2","kp":"ch13_s5_42","oe":["裂殖酵母细胞周期的引擎蛋白是P34cdc2，即CDK1。"]},{"id":"ch13_fill_13","modI":5,"q":"细胞周期的引擎蛋白有______和______两类蛋白质。","a":"周期蛋白；CDK 蛋白","kp":"ch13_s5_42","oe":["细胞周期引擎蛋白之一是周期蛋白。","另一类是CDK蛋白即周期蛋白依赖的蛋白激酶。"]},{"id":"ch13_fill_14","modI":5,"q":"细胞周期的主要检验点有______、______、______和______。","a":"G1／S 检验点；S 期检验点；G2／M 检验点；纺锤体装配检验点","kp":"ch13_s5_42","oe":["G1/S检验点决定细胞是否进入S期进行DNA复制。","S期检验点监控DNA复制是否完成及有无损伤。","G2/M检验点决定细胞能否进入M期进行分裂。","纺锤体装配检验点确保染色体正确连接于纺锤体。"]},{"id":"ch13_fill_18","modI":5,"q":"癌基因编码的蛋白主要包括______、______、______、______、______、______和______。","a":"生长因子；生长因子受体；胞内信号转导通路分子；转录因子；细胞周期蛋白； 凋亡蛋白； DNA 修复蛋白","kp":"ch13_s5_45","oe":["有些癌基因编码生长因子，如sis基因产物PDGF。","有些编码生长因子受体，如erbB基因编码EGFR。","有些编码胞内信号转导通路分子，如ras基因。","有些编码转录因子，如myc、fos、jun等。","有些编码细胞周期蛋白，如cyclin D。","有些编码凋亡蛋白，如bcl-2可抑制凋亡。","有些编码DNA修复蛋白，影响基因组稳定性。"]},{"id":"ch13_fill_25","modI":5,"q":"控制 mRNA 的细胞质定位的信息位于______，mRNA 在细胞中特定部位的聚集和______、 ______有关。","a":"3′UTR 微管；微丝","kp":"ch13_s5_40","oe":["控制mRNA细胞质定位的信息位于其3′UTR。","mRNA在细胞特定部位的聚集与微管有关。","mRNA的定位和运输也与微丝有关。"]},{"id":"ch13_fill_28","modI":5,"q":"MPF 和 SPF 是两种控制细胞周期的不同促进因子，前者由 p34cdc2 与 组成，后者由 p34cdc2 与 组成。","a":"cyclin B；cyclin A","kp":"ch13_s5_40","oe":["MPF对应cyclin B，SPF对应cyclin A，二者均含p34cdc2。"]}],"short":[{"id":"ch13_short_2","modI":5,"q":"MPF（M 期或成熟促进因子）是如何通过实验发现的？","a":"MPF 是通过一下几个实验的发现的： （1）将 Hela 细胞同步于细胞周期的不同阶段然后和 M 期细胞混合，细胞融合后发现间期 细胞产生形态各异的染色质凝集现象。 （2）用孕酮处理未成熟的卵母细胞令其成熟，将其胞质注射到另一个未成熟卵母细胞中， 结果导致后者发生减数分裂，此成熟卵母细胞胞质可继续依上法诱导另一个受体卵母细胞成 熟。 （3）在有蛋白质合成抑制剂的条件下，孕酮不能诱导未成熟的卵母细胞成熟，而成熟卵母 细胞胞质可以诱导其成熟。 上述实验提示在 M 期细胞中可能存在一种诱导染色质凝集、诱导卵母细胞成熟的因子，命 名为促成熟因子（MPF），随后 MPF 被纯化，并证明含有 p32 和 p45 两种蛋白。","kp":"ch13_s5_41"},{"id":"ch13_short_3","modI":5,"q":"细胞周期调控系统的主要作用是什么？","a":"（1）在适当时候激活细胞周期各个时相的相关酶和蛋白，然后自身失活（正调控）； （2）确保每一时相事件的全部完成（负调控）；（3）对外界环境因子起反应（如多细胞生 物对增殖信号的反应）。","kp":"ch13_s5_44"},{"id":"ch13_short_4","modI":5,"q":"细胞周期调控的分子机制如何？","a":"细胞周期控制系统中有两类关键的蛋白家族：一类是周期蛋白依赖性的蛋白激酶 （cyclin-dependent protein kinase，Cdk）。它能使特定蛋白质的丝氨酸和苏氨酸残基磷酸化 引发细胞周期事件；第二类是周期蛋白（cyclin）。它能够同 Cdk 结合，并控制 Cdk 使适当 蛋白磷酸化的能力。周期蛋白同 Cdk 蛋白复合物的装配和去装配，决定着细胞周期的进程。 有两类主要的周期蛋白：一类是有丝分裂周期蛋白。它是在 G2 期以及将要进入有丝分裂期 时同 Cdk 蛋白分子结合；另一类是 Gl 周期蛋白。它是在 G1 期以及将要进入 S 期时同 Cdk 分子结合。","kp":"ch13_s5_44"},{"id":"ch13_short_6","modI":5,"q":"海胆的细胞周期蛋白 B 是如何鉴定到的？","a":"实验中将同步化的受精的海胆卵细胞培养在有放射性氨基酸的培养液中，每 10 min 取 样一次分离纯化蛋白质，然后通过凝胶电泳、放射自显影进行蛋白质分析。结果发现，经过 几轮细胞周期之后，放射性标记的蛋白质的量稳定增加。其中有一种蛋白峰在有丝分裂的早 期特别高，但是到了有丝分裂后期就急剧下降，然后在下一个细胞周期又慢慢积累直到有丝 分裂前达到高峰，这种蛋白质后来被命名为细胞周期蛋白 B（cyclin B）。科学家用基因工 程技术从海胆中分离了细胞周期蛋白 B 的 cDNA 克隆，然后用这种 cDNA 作探针从非洲爪 蟾中分离了同源的细胞周期蛋白 B 的 cDNA 克隆，最后用周期蛋白 B 制备的抗体证明了非 洲爪蟾中的 MPF 的一个亚基的确是细胞周期蛋白 B。","kp":"ch13_s5_40"},{"id":"ch13_short_8","modI":5,"q":"关卡（checkpoint）位于细胞周期的哪些阶段?每次“检查”什么？","a":"控制系统至少有三个关卡，G1 关卡（靠近 G1 末期）、G2 关卡（靠近 G2 末期）、中期 关卡（中期末）。每一个关卡处，由细胞所处的状态与环境决定细胞能否通过此关卡，进入 下一阶段。 （1）G1 关卡（限制点）检测细胞大小和环境，如果条件合适就会激发 DNA 复制，使控制 系统向前移动。（2）G2 关卡处，控制系统检测细胞大小、状态，以及 DNA 复制是否完毕。 （3）在中期关卡，控制系统检测所有染色体是否都与纺锤体相连并排列于赤道板上，检测 MPF 是否失活，否则不能进行有丝分裂和胞质分裂。","kp":"ch13_s5_42"},{"id":"ch13_short_10","modI":5,"q":"为什么抑癌基因是隐性基因，而癌基因表现为显性基因作用？","a":"如果抑癌基因的一个等位基因发生突变，该突变基因的产物就不能正常发挥功能；肿瘤 的形成是由于完全缺乏了功能正常的肿瘤抑制蛋白，由于另一个未突变的抑癌基因的等位基 因的产物能够充当其在细胞周期调控中的角色，细胞不会癌变，因此抑癌基因的突变表现为 隐性。对于癌基因来说，不正常的蛋白质产物足以致癌，因为这种基因产物的作用是刺激细 胞生长分裂，而不是进行负调控。即使存在功能正常的原癌基因产物（由另一未突变的等位 基因编码），细胞也会出现恶变，因此癌基因的作用是显性的。","kp":"ch13_s5_47"},{"id":"ch13_short_13","modI":5,"q":"为什么说 CDK 在细胞周期调控中具有重要作用？如何调控？","a":"参见 14.2 课后习题详解中第 3 题。","kp":"ch13_s5_44"},{"id":"ch13_short_16","modI":5,"q":"什么是原癌基因？为什么突变后会导致细胞癌变？","a":"（1）原癌基因的定义 原癌基因又称细胞癌基因，是指在正常细胞基因组中对细胞正常生命活动起主要调控作用的 基因，在发生突变或被异常激活后变成具有致癌能力的癌基因。 （2）原癌基因突变后导致细胞致癌的原因 ①原癌基因的编码区发生突变，改变了原有的基因结构，致使编码产物的性质发生变化，使 其不再具有正常的活性。 ②原癌基因的调节区发生突变，从而改变了结构基因表达方式，可能大大增加表达量。 ③通过染色体重排，使不在一起的基因序列同原癌基因排列在一起，可能会合成新的蛋白或 融合蛋白，改变原有基因的自然活性。 上述中任何一种突变，都有可能使细胞失去正常的分裂控制，从而向恶性方向转变即发生癌 变。","kp":"ch13_s5_47"},{"id":"ch13_short_22","modI":5,"q":"影响细胞增殖周期的因素有哪些？细胞增殖周期与许多医学问题密切相关，举例说明。","a":"（1）影响细胞增殖周期的因素 ①环境中控制细胞增殖的因素，特别是各种生长因子。不少生长因子受体具有蛋白激酶活性， 在生长调节中通过对各种靶蛋白磷酸化实现其对细胞增殖的调节作用； ②生长因子受体的传感机制，最终引起细胞内有关增殖基因的表达，调控细胞增殖； ③某些基因及其产物与细胞增殖调控的关系，其中包括癌基因、细胞分裂周期基因等。 （2）细胞增殖周期与医学问题密切相关的例子 细胞周期检验点功能的减弱，导致突变基因的累积和正常细胞的进化，只有当这些累积的突 变基因，破坏了细胞周期的驱动机制，细胞才进入失控性生长的境界（癌变）。 六、实验题","kp":"ch13_s5_45"},{"id":"ch13_short_24","modI":5,"q":"某实验室从酵母中克隆了一基因，并发现它的蛋白质产物与细胞周期的调控有关。为了 研究其在人细胞中同源的作用，请设计一套研究方案。","a":"依据前人研究这类基因时采用的方法，特别是 MPF 发现时各位科学家之间的合作研究 方法，进行相关试验设计。 （1）方法一 ①酵母基因的人源细胞表达及其表型的鉴定 将该基因构建到一个可以在人源细胞中表达的质粒载体中，然后用此质粒转染人源细胞，让 该基因在人源细胞中高表达，观察人细胞表型和一系列生化特征的的变化（表型变化如细胞 是否还可进行正常的细胞分裂，若不能则发生了哪些其他方面的形态变化等。生化特征如细 胞内调控周期循环的各种 CDK 和 cyclin 的变化，可以采用 western blot 技术进行检验）。 ②寻找人源细胞中的同源基因和同源蛋白 a．采用免疫动物法或者杂交瘤细胞制备方法制备抗体。 b．利用免疫共沉淀的方法，将抗体与人细胞裂解液孵育，得到相应的候选蛋白。对这些候 选蛋白进行鉴定，包括氨基酸序列和编码其的 mRNA、DNA 等序列，找到人细胞中的同种 基因。 （2）方法二 ①利用 BLAST 进行 BLASTx，进行简单的同源性分析，找到与其同源性较高的人类基因； ②将找出的人类同源基因进行克隆，并进行蛋白诱导表达； ③研究检测其蛋白功能。","kp":"ch13_s5_40"},{"id":"ch13_short_26","modI":5,"q":"为什么说肿瘤的发生是基因突变逐渐积累的结果？","a":"之所以说肿瘤的发生是基因突变逐渐积累的结果，原因如下： （1）癌细胞是一种变异的细胞，是产生癌症的病源，癌细胞与正常细胞不同，有无限生长、 转化和转移三大特点，难以消灭。 （2）癌症的发生一般并不是单一基因的突变，至少在一个细胞中发生 5～6 个基因突变，才 能赋予癌细胞所有的特征。 （3）与肿瘤发生相关的某一原癌基因的突变，并非马上形成癌，而是继续生长直至细胞群 体中新的偶发突变的产生。 （4）肿瘤的发生是一系列的原癌基因与抑癌基因的致癌突变的积累。 ①原癌基因的两个拷贝中只要一个基因发生突变，就会引起细胞增殖的失控。 ②抑癌基因有两个拷贝，其中一个拷贝正常，可保证正常的调控作用，两个拷贝都丢失或失 活，才能引起细胞增殖的失控。","kp":"ch13_s5_47"}],"calc":[{"id":"ch13_calc_3","modI":5,"q":"试述调控细胞周期的因素及分选机制。","a":"细胞增殖是一个多阶段，多因子参与的高低精确有序的活动过程，而这个过程是由不同 基因严格按照时间顺序表达的结果，也是基因与环境因素相互作用的结果。细胞周期的调控 严格有序、极其复杂的过程，涉及多个因子在多个层次上的作用，这些因子通常在细胞周期 某个特定时期（调控点）起作用。 （1）细胞周期蛋白（cyclin）家族和细胞周期蛋白依赖激酶：cyclin 家族有 cyclinA、B、C、 D、E、F、G、 H 等。CdK 家族有 CdKl、CdK2、CdK3、CdK4、CdK5 等。CdK 与 cyclin 结合形成的复合物可参与磷酸化多种蛋白质，这些磷酸化蛋白在细胞周期中对 DNA 复制和 有丝分裂事件起重要调节作用。 （2）促成熟因子（MPF）是一种在 G2 期合成能促进 M 期启动的调控因子。 （3）生长因子是一类与细胞膜上特异受体结合以调节细胞周期的多肽类物质，可来自细胞 的自分泌或旁分泌。这些因子与其他受体结合后，通过信号传导途径，激活细胞内多种蛋白 激酶，最终引起与细胞周期相关的蛋白质表达的改变进而调节细胞周期。 （4）抑素是一类细胞自身产生的对细胞周期过程有抑制作用的糖蛋白。 （5）RNA 剪接因子 SR 蛋白及 SR 蛋白的特异性激酶。 （6）癌基因与抑癌基因：在一些逆转录病毒的基因组中，存在一些 DNA 序列，可促进细 胞无限增殖而癌变，这些序列被称为病毒癌基因；许多细胞癌基因可编码一些生长因子受体。 通过与生长因子结合参与细胞周期的调控或者癌基因产物直接参与细胞内信号传导进而参 与细胞周期的调控；抑癌基因：正常细胞内，一类能抑制细胞恶性增殖的基因，称为抑癌基 因，如 Rb 基因、p53 基因等。","kp":"ch13_s5_42"},{"id":"ch13_calc_4","modI":5,"q":"真核细胞周期调控模型的主要特点和机制是什么？","a":"特点表现在三类周期蛋白-Cdk 复合物和三个关键的过渡和对细胞周期的控制。 真核细胞主要通过三类周期蛋白-Cdk 复合物的作用，控制细胞周期，这三种复合物分别是： G1 期、S 期和有丝分裂 Cdk 复合物。这些复合物都是由周期蛋白依赖性的蛋白激酶和周期 蛋白两个亚基组成的复合物。在 Cdc34 途径和 APC 途径中，蛋白复合物都是通过遍在蛋白 的蛋白酶体将一些特殊的底物，包括 S 期抑制物、后期抑制物、以及有丝分裂周期蛋白降 解进行周期调节。 细胞周期中三个关键的过渡，即 G1 期→S 期、中期→后期、后期→末期及胞质分裂期的过 渡。这些过渡都是通过触发蛋白质的降解进行的，所以都是不可逆转的，这样迫使细胞周期 只能沿一个方向进行。 三个过渡分别是通过 Cdc34 和 APC 途径的降解作用完成的。Cdc34 途径促使细胞从 G1→S 期过渡：在 G1 期的早、中期，在 DNA 的复制起点就装配了复制起始复合物，并且开始了 S 期的 CdkC 组份的转录；但是，S 期 CdkC 抑制物被 G1CdkC 磷酸化而激活，激活的 S 期 CdkC 抑制物抑制了 S 期 CdkC 的活性，从而使细胞停留在 G1 期。在 G1 期的后期，Cdc34 诱导 S 期 Cdk 抑制物的降解，释放出有活性的 s 期 Cdk 复合物，这种复合物能够激发细胞进入 S 期。 一旦 S 期 Cdk 的降解作用被激活，S-期 Cdk 复合物将与 DNA 形成预复制复合物中的蛋白质 的调节位点磷酸化，预复制起始复合物是 G1 期在 DNA 复制起点上装配的复合物。这些被 S 一期 Cdk 复合物磷酸化的蛋白质不仅能够激活 DNA 复制起始，还能够阻止新的预复制复合 物的装配。由于这种抑制作用，每条染色体在细胞周期中只复制一次，保证了合适的分配到 子细胞中的染色体数。 有丝分裂 Cdk 复合物是在 S 期和 G2 期合成的，但是它们的活性一直受到抑制直到 DNA 合 成完毕。一旦被激活，有丝分裂 Cdk 复合物就会诱导染色体凝聚、核膜解体、有丝分裂器 的装配以及凝聚的染色体在中期赤道板上排列。在所有凝聚的染色体都与适当的纺锤体微管 结合之后，有丝分裂 Cdk 复合物激活后期启动复合物（anaphase promoting complex，APC）。 这种多蛋白的复合物指导后期抑制物通过遍在蛋白介导的蛋白酶解作用进行降解，导致在中 期将姐妹染色单体结合在一起的蛋白复合物失活。因此这些抑制物的降解作用，允许有丝分 裂进入到后期。在后期末，APC 也可指导有丝分裂周期蛋白的蛋白酶体的降解。有丝分裂 Cdk 活性的降低，使得分离的姐妹染色单体去凝聚、核膜重新形成、在胞质分裂中细胞质的 分裂，最后形成子细胞。","kp":"ch13_s5_44"},{"id":"ch13_calc_7","modI":5,"q":"举例说明 CDK 在细胞周期中是如何执行调节功能的。","a":"以 CDK1 激酶在细胞周期中的调控为例进行说明。 （1）CDKl 激酶即 MPF，或 p34cdc2 激酶，由 p34cdc2 蛋白和周期蛋白 B 结合而成。p34cdc2 蛋 白在细胞周期中的含量相对稳定，而周期蛋白 B 的含量则呈现出周期性变化。周期蛋白 B 一般在 G1 晚期开始合成，通过 S 期，其含量不断增加，达到 G2 期，含量达到最大值。当 p34cdc2 蛋白与周期蛋白 B 结合后，表现出激酶活性。到 G2 晚期阶段，CDK1 活性达到最大 值并一直维持到 M 期的中期阶段。 （2）CDK1 激酶活性受到很多因素的综合调节。周期蛋白与 CDK1 结合是 CDK1 激酶活性 表现的前提条件。但是，周期蛋白与 CDK1 结合是 CDK1 活化的必要不充分条件，还需要 wee1／mik1 激酶和 CDK1 活化激酶催化 CDK1 的 Thr14、Tyr15、Thr161 磷酸化，然后， CDK1 在磷酸酶 Cdc25C 的催化下，其 Thr14 和 Tyr15 去磷酸化，最终表现出激酶活性。 （3）CDK1 激酶通过使某些蛋白磷酸化，改变其下游的某些蛋白质的构象从而启动其功能， 实现其调控细胞周期的目的。比如，组蛋白 H1 磷酸化，促进染色体凝集；核纤层蛋白磷酸 化，促进核纤层解聚；核仁蛋白磷酸化，促进核仁解体；p60c-Src 蛋白磷酸化，促进细胞骨架 重排；C-abl 蛋白磷酸化，促进调整细胞形态等。 （4）活化的 CDK1 促使分裂期细胞在分裂前期执行下列生化事件： ①染色质开始浓缩形成有丝分裂染色体； ②细胞骨架解聚，有丝分裂纺锤体开始装配； ③高尔基复合体、内质网等细胞器解体，形成小的膜泡。 （5）在有丝分裂的后期，活化的后期促进因子 APC 主要介导两类蛋白质降解：后期抑制因 子和有丝分裂周期蛋白。前者维持姐妹染色单体粘连，抑制后期启动；后者的降解意味着 CDK1 失去活性，有丝分裂即将结束，即染色体开始去凝集，核膜重建。","kp":"ch13_s5_40"},{"id":"ch13_calc_8","modI":5,"q":"说明癌症的发生与癌基因和抑癌基因的关系。为什么抑癌基因突变在细胞水平上是隐性 的，却表现为典型的显性孟德尔遗传？","a":"（1）癌症的发生与癌基因和抑癌基因的关系 癌症主要是由携带遗传信息的 DNA 的病理变化而引起的疾病，涉及多个基因位点的突变。 最常发生异常变化的两类基因是： ①癌基因：编码的产物与细胞的肿瘤性转化有关。它以显性的方式作用，对细胞生长起阳性 作用，并促进细胞转化。 ②抑癌基因：抑癌基因，又称肿瘤抑制基因或抗癌基因，正常时起抑制细胞增殖和肿瘤发生 的作用。 细胞的生长是推动细胞周期进行的基因产物与抑制其进行的基因产物之间微妙平衡的结果。 任何一种产物的异常，如一种癌基因的过度表达，或一种抑癌基因的失活，都可能导致细胞 生长的失控。细胞的癌变归根结底由癌基因和抑癌基因的突变或异常表达引起，破坏了正常 的细胞增殖的调控机制，形成具有无限分裂潜能的肿瘤细胞。 （2）抑癌基因突变在细胞水平上是隐性的，却表现为典型的显性孟德尔遗传的原因 ①抑癌基因有两个拷贝，其中一个拷贝正常，可保证正常的调控作用，一对等位基因的两个 拷贝都丢失或失活，才能引起细胞增殖的失控。 ②在细胞分裂过程中，如果出现纺锤体结构的缺陷，导致染色体的错误分离，或带有野生型 和突变型的染色体之间发生重组，就可能形成抑癌基因的两个拷贝都发生突变的细胞。等位 基因都发生突变很少发生在单个细胞中，在大量的有丝分裂进行过程中却必然会发生。一旦 产生两个拷贝的抑癌基因均失活的细胞，该细胞的分裂就会加速，基因突变也随之增加，从 而产生大量携带突变的后代。突变的累积，最终导致细胞癌变。例如家族性成视网膜细胞瘤 儿童患者从亲代获得一个有缺陷的 Rb 基因（一个拷贝是正常，另一个是异常的），只有当 正常的 Rb 基因拷贝通过自发突变才会形成成视网膜细胞瘤。","kp":"ch13_s5_47"}],"term":[{"id":"ch13_term_1","modI":5,"term":"细胞周期（cell cycle）。","def":"细胞周期（cell cycle），又称细胞分裂周期，是指各细胞的生活周期，即细胞从一次有 丝分裂结束到下一次有丝分裂完成所经历的一个有序过程。增殖中体细胞其细胞周期可分分 裂期 M 和间期。M 又分前期、前中期、中期、后期、末期。间期又分 G1 期、S 期、G2 期。","kps":"","kp":"ch13_s5_44"},{"id":"ch13_term_5","modI":5,"term":"细胞周期依赖激酶（CDK）。","def":"细胞周期依赖激酶（CDK），即周期蛋白依赖性蛋白激酶，是一类含有一段类似氨基 酸序列的蛋白，它们可以和周期蛋白结合并受后者的调，可以磷酸化其他蛋白，比如组蛋白 H1、核纤层蛋白等，在细胞周期调控中发挥重要的作用。","kps":"","kp":"ch13_s5_42"},{"id":"ch13_term_6","modI":5,"term":"细胞周期蛋白（cyclins）.。","def":"细胞周期蛋白（cyclins）是结合并调节 CDK 的活性的一类蛋白，其含量随细胞周期进 程变化而变化，一般在细胞间期内积累，在细胞分裂期消失，在下一个细胞周期中又重复出 现，其含有一段比较保守的氨基酸序列。","kps":"","kp":"ch13_s5_44"},{"id":"ch13_term_8","modI":5,"term":"泛素-蛋白酶体途径（ubiquitin-proteasome pathway）。","def":"泛素-蛋白酶体途径是细胞内降解短寿命蛋白质的重要途径，与细胞多种生理功能调节 密切相关。首先通过酶 El、E2 和 E3 的作用使将要被降解的蛋白质泛素化，再由蛋白酶体 使泛素化的蛋白质完全水解。","kps":"","kp":"ch13_s5_45"},{"id":"ch13_term_13","modI":5,"term":"checkpoint","def":"checkpoint 的中文名称是细胞周期检验点。细胞周期检验点是指细胞中对其之前阶段任 务完成情况进行检测的某个特定位点，若完成则可进入下一个细胞周期阶段，否则细胞将停 留在该位点所处的阶段。这是对细胞周期进行监控的重要机制。细胞周期检验点有 G1 期检 验点、S 期检验点、G2 期检验点、纺锤体装配检验点等。","kps":"","kp":"ch13_s5_40"},{"id":"ch13_term_14","modI":5,"term":"cyclin","def":"cyclin 的中文名称是细胞周期蛋白。细胞周期蛋白是一种参与细胞周期调控的蛋白，能 与 CDK 激酶的催化亚基结合，协助蛋白激酶完成催化功能，其浓度在细胞周期中是浮动的， 呈周期性变化，在不同周期，有着不同的浓度。","kps":"","kp":"ch13_s5_44"},{"id":"ch13_term_16","modI":5,"term":"CDK 蛋白","def":"CDK 蛋白是依赖于细胞周期蛋白的一类蛋白激酶，可以和周期蛋白结合并接受后者的 调节，可以磷酸化其他蛋白，在细胞周期中发挥重要的作用。CDK 蛋白包括 CDK1～13， 其中 CDK1 即 MPF。各种 CDK 均含有一段类似的 CDK 激活结构域，且不同 CDK 结合的 周期蛋白不同，在细胞周期中执行不同的调节功能。","kps":"","kp":"ch13_s5_40"}]},{"i":6,"name":"3.1 基因治疗：用遗传工程方法使病毒携","slides":[{"i":48,"sec":"3.1 基因治疗：用遗传工程方法使病毒携","title":"3 治疗","notes":"3.1 基因治疗：用遗传工程方法使病毒携\n带正常p53基因，然后通过病毒感染，将野生\n型p53导入肿瘤细胞。并且携带p53的病毒在\n培养细胞和实验动物上都可使癌变细胞恢复\n正常生长。\n问题：目前的载体还不能高效地将替代基\n因传递到肿瘤细胞，以产生明显的临床反应。","page":49,"level":"掌握","img":"assets/img/ch13/p049.jpg","anim":null,"fig":null,"points":null,"check":{"q":"目前p53基因治疗面临的主要问题是？","o":["A. 野生型p53不能抑制肿瘤生长","B. 载体不能高效地将替代基因传递到肿瘤细胞","C. 病毒无法感染培养细胞","D. p53会使正常细胞癌变"],"a":"B","e":"基因治疗用病毒携带正常p53导入肿瘤细胞可使癌变细胞恢复正常生长，但载体尚不能高效递送，临床反应不明显。","oe":["A. 错误：实验证明携带p53的病毒可使癌变细胞恢复生长","B. 正确：载体递送效率低是目前p53基因治疗的主要瓶颈","C. 错误：病毒能在培养细胞和实验动物中介导p53导入","D. 错误：野生型p53抑制而非促进肿瘤，不会使正常细胞癌变"]},"cards":null,"mem":"病毒携野生p53治癌，载体效低","big":"assets/img/ch13/big/p049.jpg"}],"mcq":[{"id":"ch13_amcq_1","mod":"3.1 基因治疗：用遗传工程方法使病毒携","modI":6,"q":"关于「基因治疗：用遗传工程方法使病毒携」，下列说法正确的是（　）","o":["A. 在相同条件下培养的恶性细胞则相互堆积形成","B. 3.1 基因治疗：用遗传工程方法使病毒携","C. 体外培养的正常细胞通常对血清有依赖性，补","D. 血清提供生长因子，如表皮生长因子、胰岛素"],"a":"B","e":"本页要点：3.1 基因治疗：用遗传工程方法使病毒携","kp":"ch13_s6_48","oe":["描述恶性细胞堆积，与基因治疗概念无关，故不选","基因治疗即用遗传工程使病毒携带目的基因导入细胞，正确","描述正常细胞血清依赖性，与基因治疗无关，故不选","描述血清生长因子，与基因治疗无关，故不选"]}],"judge":[],"fill":[],"short":[{"id":"ch13_short_19","modI":6,"q":"简述 p53 基因“基因卫士”的功能。","a":"p53 基因“基因卫士”的功能如下： （1）p53 基因时刻监控着细胞染色体 DNA 的完整性，一旦细胞染色体 DNA 遭到损害，p53 蛋白与基因的 DNA 的相应结合部位结合，起特殊转录因子的作用： ①活化 p21 基因转录，使细胞停滞于 G1 期，抑制解链酶的活性； ②与复制因子 A 相互作用，参与 DNA 的复制与修复，使 DNA 受损的细胞不再分裂，修复 损伤而维持基因组的稳定。 （2）如果修复失败，p53 蛋白即启动程序性死亡（凋亡）过程诱导细胞自杀，使细胞周期 停滞，阻止有癌变倾向的突变细胞的生成，从而达到抑制肿瘤发生的作用。","kp":"ch13_s6_48"}],"calc":[],"term":[]},{"i":7,"name":"3.2 抑制新的血管发生","slides":[{"i":49,"sec":"3.2 抑制新的血管发生","title":"3.2 抑制新的血管发生","notes":"内皮细胞，刺激其增殖形成新的血管。\n管用于输送营养和氧气给迅速生长的癌细胞，\n并运走废物。","page":50,"level":"掌握","img":"assets/img/ch13/p050.jpg","anim":null,"fig":null,"points":["癌细胞通过分泌生长因子，作用于血管的","随着肿瘤的增大，刺激新的血管形成。血","血管为癌细胞提供扩散到其他部位的路径。"],"check":{"q":"关于肿瘤血管生成及其意义，叙述正确的是（　）","o":["A. 癌细胞分泌生长因子刺激内皮细胞增殖形成新血管，供给营养并利于扩散","B. 肿瘤血管生成由正常细胞自发完成，与癌细胞分泌因子无关","C. 抑制血管发生会促进癌细胞向其他部位扩散","D. 新生成的血管只运走废物，不输送营养和氧气"],"a":"A","e":"癌细胞通过分泌生长因子作用于血管的内皮细胞，刺激其增殖形成新的血管；血管为迅速生长的癌细胞输送营养和氧气并运走废物，随着肿瘤增大刺激新的血管形成，血管也为癌细胞提供扩散到其他部位的路径。","oe":["正确：癌细胞分泌生长因子刺激内皮细胞成血管，供营养并利于扩散。","错误：肿瘤血管生成由癌细胞分泌生长因子作用于内皮细胞所致。","错误：抑制血管发生可切断营养供应并减少扩散，而非促进扩散。","错误：血管既输送营养和氧气，也运走废物。"]},"cards":null,"mem":"抑血管发生：断供营养与转移路","big":"assets/img/ch13/big/p050.jpg"},{"i":50,"sec":"3.2 抑制新的血管发生","title":"血管发生和肿瘤发生","notes":"1       2\n●只有肿瘤没有血管，则保持非常小(1-2mm)\n●肿瘤团产生刺激附近血管的内皮细胞向肿瘤细胞生\n长的血管发生因子\n●肿瘤一经形成血管，则无限制生长","page":51,"level":"掌握","img":"assets/img/ch13/p051.jpg","anim":null,"fig":null,"points":null,"check":{"q":"肿瘤若没有血管生成，其大小通常保持在？","o":["A. 1–2cm","B. 5mm以上","C. 1–2mm","D. 无限增长"],"a":"C","e":"只有肿瘤没有血管则保持很小(1–2mm)，肿瘤团产生血管发生因子刺激血管长入后便无限制生长。","oe":["A. 错误：1~2cm远超无血管肿瘤的营养扩散限度","B. 错误：无血管时肿瘤不能长到5mm以上，会保持微小","C. 正确：无血管的肿瘤体积很小，通常限于1~2mm","D. 错误：无限生长发生在肿瘤形成血管、获得血供之后"]},"cards":null,"mem":"瘤无血管仅1~2mm，成血管则无限生长","big":"assets/img/ch13/big/p051.jpg"},{"i":51,"sec":"3.2 抑制新的血管发生","title":"a. 血管内皮抑制因子处理，几番后不再生长，中止后","notes":"没产生对内皮抑制因子的抗性，肿瘤保持很小。\nb. 传统化学治疗，抗性细胞重新生长。","page":52,"level":"掌握","img":"assets/img/ch13/p052.jpg","anim":null,"fig":null,"points":null,"check":{"q":"与传统化学治疗相比，血管内皮抑制因子治疗肿瘤的突出特点是？","o":["A. 肿瘤不产生抗性，停药后仍保持很小","B. 起效更快，可迅速杀灭全部肿瘤","C. 直接杀伤所有增殖细胞","D. 完全没有副作用"],"a":"A","e":"血管内皮抑制因子处理后肿瘤不产生抗性且保持很小；传统化疗则出现抗性细胞重新生长。","oe":["正确，该疗法未产生抗性，肿瘤保持很小。","该疗法并非能速效杀灭全部肿瘤。","直接杀伤增殖细胞的是传统化疗，且易产生抗性。","该页并未提及其完全没有副作用。"],"basis":"没产生对内皮抑制因子的抗性，肿瘤保持很小。"},"cards":null,"mem":"抑素不产生抗性，化疗生抗性","big":"assets/img/ch13/big/p052.jpg"},{"i":52,"sec":"3.2 抑制新的血管发生","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• endothelial cell / capillary lumen / red blood cell —— 内皮细胞 / 毛细血管腔 / 红细胞\n• pseudopodial processes / tip cell / filopodia —— 伪足突起 / 尖端细胞 / 丝状伪足\n• capillary sprout hollows out to form tube —— 毛细血管芽中空化形成管腔\n• control / 60 hours after wounding / 100 μm —— 对照 / 创伤后60小时 / 100微米\n• Figure 23-33 / 23-34 Angiogenesis —— 图23-33/34 血管生成：内皮出芽形成新毛细血管\n【读图讲解】\n示图＋SEM：血管生成(angiogenesis)。内皮细胞(尖端细胞)伸出伪足引导毛细血管芽(capillary sprout)生长并成管腔；SEM 对比对照与创伤后 60 小时，示创伤诱导新生毛细血管增多。考点：血管生成由内皮细胞出芽完成。","page":53,"level":"掌握","img":"assets/img/ch13/p053.jpg","anim":null,"fig":null,"points":["redbloodcell","endothelialcell","capillary lumen","thisendothelial cell","capillary sprout","willgenerateanew","hollowsout to","capillarybranch"],"check":{"q":"血管生成过程中，引导新生毛细血管芽生长的细胞是？","o":["A. 红细胞","B. 内皮尖端细胞","C. 成纤维细胞","D. 癌细胞"],"a":"B","e":"血管生成时内皮细胞（尖端细胞）伸出伪足突起，引导毛细血管芽生长并中空化形成管腔。","oe":["A. 错误：红细胞存在于血管腔内，不引导血管芽生长","B. 正确：内皮尖端细胞伸出伪足引导毛细血管芽生长成管","C. 错误：成纤维细胞参与基质形成，非血管芽的引导细胞","D. 错误：癌细胞分泌血管生成因子，但不由其引导血管芽"]},"cards":null,"mem":"尖端内皮出芽，伪足引导成管腔","big":"assets/img/ch13/big/p053.jpg"},{"i":53,"sec":"3.2 抑制新的血管发生","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• HIGH O2 → LOW HIF —— 高氧→低HIF(缺氧诱导因子)\n• LOW O2 → HIGH HIF → secreted VEGF —— 低氧→高HIF→分泌VEGF\n• capillary sprout / small blood vessel —— 毛细血管芽 / 小血管\n• Figure 23-35 —— 图23-35 依氧需求调控血管生长：缺氧触发VEGF分泌促血管生成\n【读图讲解】\n调控机制图：组织缺氧调控血管生长。高 O₂→低 HIF；低 O₂→高 HIF→分泌 VEGF→刺激毛细血管芽生长。考点：HIF 为氧感受器，缺氧时稳定并上调 VEGF，促血管生成。","page":54,"level":"掌握","img":"assets/img/ch13/p054.jpg","anim":null,"fig":null,"points":["Figure23-35Theregulatorymechanism","controllingbloodvesselgrowth","LOWO2","according to a tissue's needfor oxygen.","Lackofoxygentriggersthesecretionof","VEGF,whichstimulates angiogenesis.","HIGHHIF","HIGHO2"],"check":{"q":"组织缺氧促进血管生成的分子机制是？","o":["A. 低氧使HIF升高，分泌VEGF刺激血管生成","B. 低氧使HIF降低，抑制VEGF","C. 高氧使VEGF大量分泌","D. HIF直接转化为VEGF蛋白"],"a":"A","e":"低氧使HIF（缺氧诱导因子）升高，促进VEGF分泌，刺激毛细血管芽生长；高氧时HIF降低。","oe":["A. 正确：低氧稳定HIF，HIF上调VEGF，促进血管生成","B. 错误：低氧使HIF升高而非降低，从而促进VEGF表达","C. 错误：高氧使HIF降低，VEGF分泌减少而非大量分泌","D. 错误：HIF是转录因子，促进VEGF基因表达而非转为VEGF"]},"cards":null,"mem":"高氧低HIF，低氧高HIF→VEGF促血管","big":"assets/img/ch13/big/p054.jpg"}],"mcq":[],"judge":[{"id":"ch13_judge_7","modI":7,"q":"从细胞生物学的角度看，肿瘤发生的原因是细胞分裂过快。（                 ）","a":"错","e":"是分裂失控，即细胞周期失去控制。","kp":"ch13_s7_50","oe":["肿瘤细胞增殖快，表面上看像是分裂过快所致，故易误判为对。","肿瘤本质是细胞周期失控、增殖与死亡失衡，而非单纯分裂速度加快。"]},{"id":"ch13_judge_10","modI":7,"q":"cyclin C 的表达是哺乳动物细胞通过 G1 期检验点的重要条件。（          ）","a":"错","e":"cyclin E 与 CDK2 的结合促使细胞由 G1 向 S 期转化。","kp":"ch13_s7_49","oe":["cyclin 家族成员众多，易把通过 G1 检验点误记为 cyclin C 的表达。","是cyclinE与CDK2结合促使细胞由G1期进入S期，cyclinC并非关键。"]}],"fill":[],"short":[{"id":"ch13_short_25","modI":7,"q":"现有一种新筛选出的抗肿瘤新药 A，给你一瓶肿瘤细胞，你怎样在细胞水平验证该新药 A 的药效？请你设计一个实验，包括实验方法、实验材料、实验仪器、实验过程，及对预期 的实验结果的分析等。","a":"（1）实验方法 由于抗肿瘤药物的作用是引起肿瘤细胞的凋亡，用新药 A 对人肿瘤细胞进行处理后，利用 细胞凋亡过程中会被特异性切割，形成大小差别为 200bp 左右片段的特点，通过琼脂糖凝胶 电泳检测其有无特征的核小体断裂形成的梯状条带来鉴定新药 A 的功效。 （2）实验材料 人肿瘤细胞。 （3）实验仪器 水平电泳仪、凝胶成像系统等。 （4）实验过程 ①将人肿瘤细胞放入合适培养基培养； ②将新药 A 加入培养基中； ③一段时间后从培养基中收集细胞，利用 SDS∕酚法提取细胞基因组 DNA； ④将提取到的 DNA 进行琼脂糖凝胶电泳； ⑤取电泳完的琼脂糖凝胶用 EB 进行染色，15min 后取出冲洗，在紫外下，利用凝胶成像系 统观察 DNA 电泳情况； ⑥观察实验结果并分析。 （5）预期实验结果及分析 ①若基因组 DNA 出现典型的相隔 200bp 的梯状条带，则说明新药 A 有抗肿瘤功效； ②若基因组 DNA 无典型的相隔 200bp 的梯状条带呈现，则说明新药 A 无抗肿瘤功效。","kp":"ch13_s7_50"}],"calc":[],"term":[]}],"mcq":[{"id":"ch13_mcq_1","mod":"2.3.1     肿瘤抑制基因(Tumor suppressor gene)","modI":4,"q":"MPF（CDK1）调控细胞周期中（         ）。","o":["A．G1 期向 M 期转换","B．G2 期向 M 期转换","C．G1 期向 S 期转换","D．S 期向 G2 期转换"],"a":"B","e":"MPF＝cdc2（CDK1）＋clyclin B，调控细胞由 G2 期向 M 期转换。","kp":"ch09_s3_6","oe":["MPF不调控G1→M，该转换不由MPF负责。","MPF(CDK1-cyclinB)调控细胞由G2期进入M期，正确。","G1→S由CDK2-cyclinE等调控，非MPF。","S期向G2期的转换并非由MPF调控。"]},{"id":"ch13_mcq_2","mod":"绪论 · 概览","modI":0,"q":"周期蛋白依赖性蛋白激酶中，充当调节亚基的是（              ）。","o":["A．周期蛋白","B．CDK 蛋白","C．MPF 蛋白","D．都不是"],"a":"A","e":"在 CDK-Cyclin 复合物中，CDK 为催化亚基，Cyclin 为调节亚基。","kp":"ch09_s4_0","oe":["CDK-Cyclin复合物中周期蛋白为调节亚基，正确。","CDK为催化亚基，具蛋白激酶活性。","MPF是CDK1与cyclinB的复合物，非单一调节亚基。","周期蛋白即为调节亚基，故“都不是”错误。"]},{"id":"ch13_mcq_3","mod":"绪论 · 概览","modI":0,"q":"MPF 的功能有（     ）。","o":["A．催化组蛋白 H1 的磷酸化","B．催化核限层蛋白磷酸化","C．作用于微管蛋白，控制着细胞周期中微管的动力学变化","D．以上都正确"],"a":"D","e":"MPF 调控细胞由 G2 期向 M 期转换，其功能是催化靶蛋白磷酸化，为细胞由间期 进入分裂期做好准备。","kp":"ch09_s3_8","oe":["MPF可催化组蛋白H1磷酸化，属其功能之一，正确。","MPF使核纤层蛋白磷酸化致核膜解体，属其功能，正确。","MPF作用于微管蛋白调控微管动态变化，属其功能，正确。","MPF兼具上述三方面功能，故以上都正确。"]},{"id":"ch13_mcq_4","mod":"2.2 病毒","modI":2,"q":"在细胞由 G2 进入 M 期过程中，MPF 中的 CDK 的 Thr14 和 Tyr15 的去磷酸化需要下列 哪种磷酸酶的催化（        ）。","o":["A．Weel","B．CAK","C．cdc25","D．cdc20"],"a":"C","e":"Weel 激酶使 Thr14 和 Tyr15 的磷酸化，CAK 催化 Thr161 的磷酸化。","kp":"ch09_s6_4","oe":["Weel是激酶，催化Thr14/Tyr15磷酸化而抑制MPF。","CAK催化Thr161磷酸化，而非去磷酸化。","cdc25磷酸酶催化Thr14和Tyr15去磷酸化，激活MPF，正确。","cdc20参与APC介导的泛素化，非该去磷酸化酶。"]},{"id":"ch13_mcq_5","mod":"2.2 病毒","modI":2,"q":"MPF 中的拍 p32 蛋白能被下列哪种蛋白的特异性抗体识别（             ）。","o":["A．p34","B．p56","C．cyclin B","D．p45"],"a":"A","e":"p32 同 p34 为同源物。","kp":"ch09_s3_7","oe":["p32与p34(cdc2)为同源物，可被抗p34抗体识别，正确。","p56与p32无同源性，不能识别p32。","cyclinB为调节亚基，与p32非同源物。","p45与p32无同源性，不能识别。"]},{"id":"ch13_mcq_6","mod":"绪论 · 概览","modI":0,"q":"将有丝分裂中期细胞与 G1 细胞融合，可诱导 G1 细胞出现早熟染色体凝集其形态为（       ）。","o":["A．单线状","B．双线状","C．粉末状","D．都不是"],"a":"A","e":"G0 期的 PCC 呈单细丝状，S 期的呈粉末状，G2 期的呈双线状。","kp":"ch09_s3_3","oe":["G1期细胞DNA尚未复制，早熟染色体凝集呈单线状，正确。","双线状对应DNA已复制的G2期细胞。","粉末状对应S期细胞，非G1期形态。","G1期呈单线状，故“都不是”错误。"]},{"id":"ch13_mcq_7","mod":"2.3.2 原癌基因(proto-oncogene)","modI":5,"q":"在癌基因所编码的五类主要的蛋白中，哪类蛋白的突变是细胞癌变的主要原因?（             ）。","o":["A．生长因子","B．转录因子","C．信号转导通路蛋白","D．细胞周期蛋白"],"a":"C","e":"信号转导通路蛋白突变是细胞癌变的主要原因，如人类各种癌症中约 30％的癌症 是信号通路中的 ras 基因突变引起的。","kp":"ch13_s5_2","oe":["生长因子类癌基因产物的突变并非细胞癌变的主要原因。","转录因子类癌基因产物的突变并非主要原因。","约30%癌症由ras等信号转导通路蛋白基因突变引起，是主要原因，正确。","细胞周期蛋白类并非细胞癌变的主要原因。"]},{"id":"ch13_mcq_8","mod":"2.3.2 原癌基因(proto-oncogene)","modI":5,"q":"抑癌基因之一是（          ）。","o":["A．c-fos","B．v-jun","C．v-raf","D．p53"],"a":"D","e":"前三个基因均为细胞增殖的正性调控基因。","kp":"ch13_s4_4","oe":["c-fos是原癌基因，属增殖正性调控基因。","v-jun为癌基因，属增殖正性调控基因。","v-raf为癌基因，属增殖正性调控基因。","p53是著名抑癌基因，其失活与多种肿瘤相关，正确。"]},{"id":"ch13_mcq_9","mod":"2.2 病毒","modI":2,"q":"有活性的 CDK1 激酶符合下列何种描述？（             ）[南开大学 2011 研]","o":["A．与周期蛋白以复合物形式存在","B．Thr161 去磷酸化","C．Thr14 和 Tyr15 磷酸化","D．与之结合的周期蛋白泛素化"],"a":"A","e":"CDK 激酶激活的途径：①CDK 蛋白本身不具有蛋白激酶活性；②当周期蛋白 B/A 含量积累到一定值时，二者相互结合形成复合体，但不表现出激酶活性；周期蛋白与 CDK 的结合是 CDK 激酶活性表现的先决条件；③在 wee1∕mik1 和 CAK 激酶的催化下 CDK 的 Thr14、Tyr15、Thr161 磷酸化，形成高度磷酸化的周期蛋白 CDK 复合体，但仍不具备激酶 活性；④在磷酸酶 Cdc25C 的催化下，Thr14 和 Tyr15 去磷酸化，CDK 激酶活性才能表现出 来。Thr161 位点保持磷酸化状态是 CDK1 激酶活性表现所必需的前提。","kp":"ch09_s6_3","oe":["CDK1须与周期蛋白B结合成复合物才具激酶活性，正确。","Thr161须保持磷酸化才有活性，去磷酸化则失活。","Thr14、Tyr15须去磷酸化才激活，磷酸化则抑制。","结合的周期蛋白泛素化导致其降解、CDK失活。"]},{"id":"ch13_mcq_10","mod":"绪论 · 概览","modI":0,"q":"癌细胞的主要特点之一是（           ）。[军事医学科学院 2006 研]","o":["A．细胞间黏附性增强","B．缺少接触抑制作用","C．对生长因子的需求量上升","D．增殖力下降"],"a":"B","e":"A 项，癌细胞几乎丧失细胞间的黏着，相互之间不产生抑制作用，更有利于快速繁 殖。C 项，由于癌细胞的增殖能力增强，其对生长因子的需求量下降。D 项，癌细胞的一个 典型特征就是增殖力增强。","kp":"ch13_s0_3","oe":["癌细胞细胞间黏附性下降而非增强。","癌细胞丧失接触抑制，可堆积重叠、无限增殖，正确。","癌细胞自分泌生长因子，对生长因子需求下降。","癌细胞的增殖能力增强而非下降。"]},{"id":"ch13_mcq_11","mod":"2.3.1     肿瘤抑制基因(Tumor suppressor gene)","modI":4,"q":"调节细胞进出 S 期所必需的蛋白质激酶是（              ）。","o":["A．MPF","B．SPF","C．CDC","D．AC","E．PKC"],"a":"B","e":"A 项，MPF 是 M 期促进因子，能够调控细胞周期从 G2 到 M 期。B 项，SPF 是 S 期促进因子，能够调控细胞周期从 G1 到 S 期。C 项，CDC 是蛋白激酶催化亚基。D 项，AC 即腺苷酸环化酶，是膜整合蛋白，能够将 ATP 转变成 cAMP 引起细胞的信号应答，是 G 蛋 白偶联系统中的效应物。E 项，PKC 是信号调节系统中的蛋白激酶，主要起到激活下游级 联反应的作用。","kp":"ch09_s1_4","oe":["MPF调控G2→M，不调控G1→S。","SPF(S期促进因子)调控细胞由G1进入S期，正确。","CDC为蛋白激酶催化亚基，非使细胞进入S期的专一因子。","腺苷酸环化酶催化ATP生成cAMP，与S期进入无关。","PKC是信号通路蛋白激酶，非S期促进因子。"]},{"id":"ch13_amcq_1","mod":"2.1 化学致癌物与辐射对癌的影响","modI":1,"q":"关于「化学致癌物与辐射对癌的影响」，下列说法正确的是（　）","o":["A. 在相同条件下培养的恶性细胞则相互堆积形成","B. 苯胺衍生物，砷、石棉，苯，铅，芥子气，煤","C. 体外培养的正常细胞通常对血清有依赖性，补","D. 血清提供生长因子，如表皮生长因子、胰岛素"],"a":"B","e":"本页要点：苯胺衍生物，砷、石棉，苯，铅，芥子气，煤","kp":"ch13_s1_0","oe":["描述恶性细胞失去接触抑制而堆积，与化学致癌物无关","苯胺衍生物、砷、石棉、苯等属化学致癌物，正确","描述正常细胞对血清的依赖性，非化学致癌物，故不选","描述血清提供生长因子，与化学致癌物列举无关，故不选"]},{"id":"ch13_amcq_1","mod":"3.1 基因治疗：用遗传工程方法使病毒携","modI":6,"q":"关于「基因治疗：用遗传工程方法使病毒携」，下列说法正确的是（　）","o":["A. 在相同条件下培养的恶性细胞则相互堆积形成","B. 3.1 基因治疗：用遗传工程方法使病毒携","C. 体外培养的正常细胞通常对血清有依赖性，补","D. 血清提供生长因子，如表皮生长因子、胰岛素"],"a":"B","e":"本页要点：3.1 基因治疗：用遗传工程方法使病毒携","kp":"ch13_s6_0","oe":["描述恶性细胞堆积，与基因治疗概念无关，故不选","基因治疗即用遗传工程使病毒携带目的基因导入细胞，正确","描述正常细胞血清依赖性，与基因治疗无关，故不选","描述血清生长因子，与基因治疗无关，故不选"]}],"judge":[{"id":"ch13_judge_1","modI":0,"q":"在有蛋白质合成抑制剂存在的情况下，孕酮和成熟卵细胞的细胞质都能诱导卵母细胞成 熟。（      ）","a":"错","e":"在有蛋白质合成抑制剂存在的情况下．成熟卵细胞的细胞质都能诱导卵母细胞成熟， 而孕酮不能，因为不能合成 MPF。","kp":"ch09_s3_4","oe":["有人以为成熟卵细胞质含 MPF、孕酮也经细胞质起作用，故误判为都能诱导。","成熟卵细胞质含现成 MPF 可诱导成熟，孕酮需合成 MPF，被抑制剂阻断故不能。"]},{"id":"ch13_judge_2","modI":4,"q":"磷酸化的 CDK2／cyclinE 不一定表现出激酶活力。（      ）","a":"对","e":"正如 CDK1 在 Thr14 和 Tyr15 磷酸化时无活性，只有 Thr14 和 Tyr15 去磷酸化。才 能被激活。","kp":"ch09_s6_4","oe":["CDK 需在特定 Thr 去磷酸化才被激活，磷酸化状态不当时可无激酶活性。","误以为只要 CDK2 与 cyclinE 结合并磷酸化，就必然具有激酶活力。"]},{"id":"ch13_judge_3","modI":0,"q":"在泛素化途径降解蛋白质过程中，泛素随靶蛋白一同被蛋白酶体降解。（                     ）","a":"错","e":"泛素并不被降解，它可以循环利用。","kp":"ch09_s6_13","oe":["泛素标记靶蛋白并引导其进入蛋白酶体，易让人以为泛素也一并被降解。","泛素起标签作用，靶蛋白降解后泛素被释放并可循环利用，自身不被降解。"]},{"id":"ch13_judge_4","modI":5,"q":"细胞周期蛋白及其磷酸化状态两者决定一个 Cdk 蛋白是否具有酶活性。（                  ）","a":"对","e":"cdk 与细胞周期蛋白的聚合是其活性所必需的，而且细胞周期蛋白／Cak 复合物的 激活依赖于 cdk 蛋白上某些特殊部位的磷酸化和另一些部位的去磷酸化。","kp":"ch09_s6_3","oe":["Cdk 需与周期蛋白结合，并经特定部位磷酸化或去磷酸化，才具酶活性。","若认为 Cdk 仅靠周期蛋白结合即可激活、与磷酸化无关，则说法错误。"]},{"id":"ch13_judge_5","modI":5,"q":"肿瘤细胞就是一类基因突变的干细胞。（             ）","a":"错","e":"肿瘤组织中并非所有细胞都是干细胞，只有少数细胞是肿瘤干细胞。","kp":"ch13_s0_0","oe":["肿瘤细胞具有无限增殖等干细胞样特性，易被笼统视为基因突变的干细胞。","肿瘤组织中仅少数为肿瘤干细胞，多数是分化程度不同的肿瘤细胞，不能等同。"]},{"id":"ch13_judge_6","modI":3,"q":"癌的发生涉及两类基因：原癌基因和肿瘤抑制基因，这两类基因中的任何一个拷贝突变 都会导致癌变。（       ）","a":"错","e":"只有当肿瘤抑制基因两个拷贝都丢失了或两个拷 rA 都失活了才会使细胞失去增殖 的控制，只要肿瘤抑制基因有一个拷贝是正常的，就能够正常调节细胞的周期。","kp":"ch13_s3_0","oe":["原癌基因一个拷贝突变即可致癌，易把此规律错误地推到抑癌基因上。","抑癌基因需两个拷贝都失活才致癌，仅一个拷贝突变仍能正常调控细胞周期。"]},{"id":"ch13_judge_7","modI":7,"q":"从细胞生物学的角度看，肿瘤发生的原因是细胞分裂过快。（                 ）","a":"错","e":"是分裂失控，即细胞周期失去控制。","kp":"ch13_s0_0","oe":["肿瘤细胞增殖快，表面上看像是分裂过快所致，故易误判为对。","肿瘤本质是细胞周期失控、增殖与死亡失衡，而非单纯分裂速度加快。"]},{"id":"ch13_judge_8","modI":5,"q":"抑癌基因突变能转变成癌基因从而致癌。（              ）","a":"错","e":"抑癌基因发生突变后会失去抑癌功能。","kp":"ch13_s5_7","oe":["抑癌基因与原癌基因都涉及肿瘤发生，易混淆而认为前者可变为癌基因。","抑癌基因突变后是丧失抑癌功能，不会转变为癌基因，二者机制不同。"]},{"id":"ch13_judge_9","modI":0,"q":"正常细胞发生癌变时游离的核糖体增多，而附着的核糖体和内质网的数目相应减少。 （     ）","a":"错","e":"正常细胞发生癌变后，与癌细胞恶性增殖、扩散等过程相关的蛋白成分会过表达， 从而使得粗面内质网的数目增多，附着核糖体的数目增多。","kp":"ch13_s0_0","oe":["癌细胞增殖旺盛需大量蛋白，易误以为游离核糖体增多而粗面内质网减少。","癌变时与恶性增殖相关的蛋白过表达，粗面内质网及附着核糖体反而增多。"]},{"id":"ch13_judge_10","modI":7,"q":"cyclin C 的表达是哺乳动物细胞通过 G1 期检验点的重要条件。（          ）","a":"错","e":"cyclin E 与 CDK2 的结合促使细胞由 G1 向 S 期转化。","kp":"ch09_s2_3","oe":["cyclin 家族成员众多，易把通过 G1 检验点误记为 cyclin C 的表达。","是cyclinE与CDK2结合促使细胞由G1期进入S期，cyclinC并非关键。"]},{"id":"ch13_judge_11","modI":4,"q":"在正常的二倍体细胞中，每一种抑癌基因都有两个拷贝，任何一个拷贝发生突变都会失 去抑癌作用。（           ）","a":"错","e":"在正常的二倍体细胞中，每一种肿瘤抑制基因有两个拷贝，只有当两个拷贝都丢失 或两个拷贝都失活才会使细胞失去增殖的控制，只要有一个拷贝是正常的，就能够正常调节 细胞的周期。相反，只要有一个拷贝的原癌基因突变，就会致癌。","kp":"ch13_s4_0","oe":["受原癌基因一个拷贝突变即致癌的影响，易类推到抑癌基因而误判。","二倍体细胞中抑癌基因需两个拷贝都丢失或失活才失去抑癌作用。"]},{"id":"ch13_judge_12","modI":5,"q":"在细胞周期的 G2 期早期和 M 期早期，周期蛋白的浓度最高。（                ）","a":"错","e":"G2 期早期的周期蛋白浓度不是最高的。","kp":"ch09_s4_0","oe":["M 期 cyclin 浓度高，易把 G2 期早期也一并认为最高，故误判。","cyclin 浓度在 M 期最高，G2 期早期尚未达峰值，故并非最高。"]},{"id":"ch13_judge_13","modI":0,"q":"Bc12 是一种原癌基因，它和一般的癌基因不同，它能够延长细胞的生存，而不是促进细 胞的增殖。（          ）","a":"对","e":"","kp":"ch13_s5_2","oe":["Bcl-2 属原癌基因，通过抑制凋亡延长细胞存活，符合其抗凋亡功能。","若认为 Bcl-2 是通过促进细胞增殖致癌，则混淆了其抗凋亡机制。"]},{"id":"ch13_judge_14","modI":0,"q":"永生细胞和癌细胞的主要共同点就是既没有细胞分裂次数的限制，也没有细胞间的接触 抑制。（         ）","a":"错","e":"永生细胞间有接触抑制。","kp":"ch13_s0_4","oe":["永生细胞与癌细胞都能无限传代，易被误认为两者都失去接触抑制。","永生细胞仍保留接触抑制，只有癌细胞才同时丧失接触抑制。"]},{"id":"ch13_judge_15","modI":0,"q":"在不利于细胞分裂的情形下，高等动物细胞通常会选择在 G2 检验点暂停，等待继续进行 细胞分裂的信号。（            ）","a":"对","e":"","kp":"ch09_s2_3","oe":["细胞在 G2 期检查 DNA 复制是否完成、损伤是否修复，不利时暂停等信号。","若认为细胞只在 G1 检验点受阻、不存在 G2 检验点，则不符合事实。"]}],"fill":[{"id":"ch13_fill_1","modI":5,"q":"细胞周期调控中的两个主要因子______和______，其中______是催化亚基，______相当 于调节亚基。","a":"周期蛋白；周期蛋白依赖的蛋白激酶；周期蛋白依赖的蛋白激酶；周期蛋白查看答 案","kp":"ch09_s5_0","oe":["两大因子即周期蛋白和周期蛋白依赖的蛋白激酶(CDK)。","另一因子是周期蛋白依赖的蛋白激酶，即CDK。","CDK具有激酶活性，是催化亚基，使靶蛋白磷酸化。","周期蛋白无酶活性，结合CDK并调节其活性，为调节亚基。"]},{"id":"ch13_fill_2","modI":4,"q":"CyclinB 的合成在 G1 晚期开始合成，在细胞中逐渐积累，到______末时达到最大值。","a":"G2","kp":"ch09_s4_0","oe":["CyclinB从G1晚期开始合成积累，到G2期末达到最大值。"]},{"id":"ch13_fill_3","modI":4,"q":"CDK1 分子中第 161 位苏氨酸的磷酸化是______的作用。","a":"激酶 CAK","kp":"ch09_s6_4","oe":["CDK1第161位苏氨酸的磷酸化由CDK活化激酶CAK催化。"]},{"id":"ch13_fill_4","modI":4,"q":"在泛素化途径降解蛋白质过程中，涉及______、______、______三种酶。","a":"泛素激活酶（E1）；泛素结合酶（E2）；泛素连接酶（E3）","kp":"ch09_s6_13","oe":["泛素激活酶E1消耗ATP将泛素激活。","泛素结合酶E2接受并转运活化的泛素。","泛素连接酶E3识别底物并介导其泛素化。"]},{"id":"ch13_fill_5","modI":4,"q":"APC 即______，其主要作用是______，______是它的有效正调控因子。","a":"后期促进因子；调节 M 期周期蛋白泛素化途径降解；cdc20 蛋白","kp":"ch09_s6_17","oe":["APC即后期促进复合物，又称后期促进因子。","APC通过泛素化途径促使M期周期蛋白降解。","cdc20是APC的有效正调控因子，激活其活性。"]},{"id":"ch13_fill_6","modI":4,"q":"细胞成熟促进因子包括两类蛋白质：①______；②______。","a":"P34cdc2 蛋白激酶；细胞周期蛋白","kp":"ch09_s3_7","oe":["成熟促进因子MPF含P34cdc2蛋白激酶。","MPF另一成分为细胞周期蛋白，起调节作用。"]},{"id":"ch13_fill_7","modI":5,"q":"MPF 和 SPF 是两种控制细胞周期的不同促进因子，前者由                      与______组 成，后者由                 与______组成。","a":"周期蛋白 B；周期蛋白 A","kp":"ch09_s3_7","oe":["MPF由p34cdc2与周期蛋白B组成，故第一空为周期蛋白B。","SPF由p34cdc2与周期蛋白A组成，故第二空为周期蛋白A。"]},{"id":"ch13_fill_8","modI":2,"q":"Cdk 是一种蛋白激酶，必须与______结合后才具有活性。","a":"细胞周期蛋白","kp":"ch09_s5_0","oe":["CDK单独无活性，必须与细胞周期蛋白结合才被激活。"]},{"id":"ch13_fill_9","modI":4,"q":"Cdk 是一种周期蛋白依赖性的蛋白激酶，可使靶蛋白的______残基磷酸化。","a":"丝氨酸或苏氨酸","kp":"ch09_s5_0","oe":["CDK属丝氨酸/苏氨酸蛋白激酶，使靶蛋白相应残基磷酸化。"]},{"id":"ch13_fill_10","modI":2,"q":"在早熟染色体凝集实验中 G1 期的染色体呈现______，G2 期是______，而 S 期是______。","a":"细线状；双线状；粉末状","kp":"ch09_s3_3","oe":["G1期染色质尚未复制，PCC呈细线状。","G2期DNA已复制完成，PCC呈双线状。","S期DNA复制未完成，PCC呈粉末状。"]},{"id":"ch13_fill_11","modI":5,"q":"裂殖酵母细胞周期的引擎蛋白是______蛋白。","a":"P34cdc2","kp":"ch09_s6_24","oe":["裂殖酵母细胞周期的引擎蛋白是P34cdc2，即CDK1。"]},{"id":"ch13_fill_12","modI":4,"q":"MPF 包括______和______两种蛋白质。","a":"周期蛋白 B；CDKl 蛋白","kp":"ch09_s3_7","oe":["MPF含周期蛋白B这一调节亚基。","MPF另一成分是CDK1（p34cdc2）蛋白激酶。"]},{"id":"ch13_fill_13","modI":5,"q":"细胞周期的引擎蛋白有______和______两类蛋白质。","a":"周期蛋白；CDK 蛋白","kp":"ch09_s5_0","oe":["细胞周期引擎蛋白之一是周期蛋白。","另一类是CDK蛋白即周期蛋白依赖的蛋白激酶。"]},{"id":"ch13_fill_14","modI":5,"q":"细胞周期的主要检验点有______、______、______和______。","a":"G1／S 检验点；S 期检验点；G2／M 检验点；纺锤体装配检验点","kp":"ch09_s2_3","oe":["G1/S检验点决定细胞是否进入S期进行DNA复制。","S期检验点监控DNA复制是否完成及有无损伤。","G2/M检验点决定细胞能否进入M期进行分裂。","纺锤体装配检验点确保染色体正确连接于纺锤体。"]},{"id":"ch13_fill_15","modI":0,"q":"周期蛋白 B 的降解依赖______途径。","a":"泛素-蛋白酶体降解","kp":"ch09_s6_13","oe":["周期蛋白B经泛素化后被蛋白酶体识别并降解。"]},{"id":"ch13_fill_16","modI":2,"q":"______是指在病毒基因组中存在的能促使细胞无限增殖进而癌变的 DNA 序列。","a":"病毒癌基因","kp":"ch13_s5_0","oe":["病毒癌基因是病毒基因组中能使细胞无限增殖癌变的序列。"]},{"id":"ch13_fill_17","modI":0,"q":"______是细胞增殖的负性调节因子，能够抑制癌细胞的恶性增殖，突变后有可能使细胞 发生癌变。","a":"抑癌基因","kp":"ch13_s4_0","oe":["抑癌基因抑制细胞增殖，突变失活后可能导致细胞癌变。"]},{"id":"ch13_fill_18","modI":5,"q":"癌基因编码的蛋白主要包括______、______、______、______、______、______和______。","a":"生长因子；生长因子受体；胞内信号转导通路分子；转录因子；细胞周期蛋白； 凋亡蛋白； DNA 修复蛋白","kp":"ch13_s5_2","oe":["有些癌基因编码生长因子，如sis基因产物PDGF。","有些编码生长因子受体，如erbB基因编码EGFR。","有些编码胞内信号转导通路分子，如ras基因。","有些编码转录因子，如myc、fos、jun等。","有些编码细胞周期蛋白，如cyclin D。","有些编码凋亡蛋白，如bcl-2可抑制凋亡。","有些编码DNA修复蛋白，影响基因组稳定性。"]},{"id":"ch13_fill_19","modI":4,"q":"转录因子从功能上分为______和______。","a":"通用转录因子；特异转录因子","kp":"ch13_s5_2","oe":["通用转录因子参与所有基因转录起始，如TFIID。","特异转录因子识别特定基因的调控序列并调控其表达。"]},{"id":"ch13_fill_20","modI":4,"q":"转录因子包括两个结构域，一个是______，结合特异的 DNA 序列；另一个是______， 通过与其他蛋白作用而激活转录。","a":"DNA 结合结构域；转录激活结构域","kp":"ch13_s5_2","oe":["DNA结合结构域识别并结合靶基因特异的DNA序列。","转录激活结构域通过与其他蛋白作用而激活转录。"]},{"id":"ch13_fill_21","modI":0,"q":"YEIID 是专一结合在基因上游调控序列的______盒上，它决定转录正确的其始位置。","a":"TATA","kp":"ch13_s0_0","oe":["TFIID专一结合基因上游TATA盒，决定转录起始位置。"]},{"id":"ch13_fill_22","modI":3,"q":"癌的发生涉及两类基因：肿瘤抑制基因与癌基因。肿瘤抑制基因是细胞生长的______, 它们编码的蛋白质抑制细胞生长，并阻止细胞癌变。癌基因则是细胞生长的______,它们编 码的蛋白质使细胞生长不受控制，并促进细胞癌变。","a":"制动器；加速器","kp":"ch13_s3_0","oe":["抑癌基因是细胞生长的制动器，抑制细胞过度增殖。","癌基因是细胞生长的加速器，使生长不受控制。"]},{"id":"ch13_fill_23","modI":0,"q":"英国科学家______在多肽链序列测定和 DNA 序列测定方面做出重大的贡献。","a":"Sanger","kp":"ch13_s0_15","oe":["英国科学家Sanger在蛋白质和DNA序列测定方面贡献卓著。"]},{"id":"ch13_fill_24","modI":0,"q":"CpG 岛常常位于______，其中的______位常常被甲基化，DNA 甲基化与基因表达的 ______有关。","a":"转录调控区；5-C；阻抑","kp":"ch13_s1_3","oe":["CpG岛常位于基因的转录调控区（启动子区）。","其中胞嘧啶第5位碳常被甲基化成5-甲基胞嘧啶。","DNA甲基化通常与基因表达的阻抑（沉默）有关。"]},{"id":"ch13_fill_25","modI":5,"q":"控制 mRNA 的细胞质定位的信息位于______，mRNA 在细胞中特定部位的聚集和______、 ______有关。","a":"3′UTR 微管；微丝","kp":"ch13_s0_0","oe":["控制mRNA细胞质定位的信息位于其3′UTR。","mRNA在细胞特定部位的聚集与微管有关。","mRNA的定位和运输也与微丝有关。"]},{"id":"ch13_fill_26","modI":0,"q":"动物体内细胞分裂调节失控而无限增殖的细胞称为______，其中具有转移能力的称为 ______。","a":"肿瘤细胞；恶性肿瘤（癌症）","kp":"ch13_s0_0","oe":["细胞分裂调节失控而无限增殖的细胞称为肿瘤细胞。","其中具有转移能力的称为恶性肿瘤，即癌症。"]},{"id":"ch13_fill_27","modI":0,"q":"让 M 期的细胞与间期的细胞融合，诱导间期细胞产生 PCC。G1 期的 PCC 呈单线状，S 期呈______状，G2 期的呈______状。[浙江师范大学 2011 研]","a":"粉末；双线","kp":"ch09_s3_3","oe":["S期DNA正在复制，PCC呈粉末状。","G2期DNA已复制完成，PCC呈双线状。"]},{"id":"ch13_fill_28","modI":5,"q":"MPF 和 SPF 是两种控制细胞周期的不同促进因子，前者由 p34cdc2 与 组成，后者由 p34cdc2 与 组成。[南开大学 2008 研]","a":"cyclin B；cyclin A","kp":"ch09_s3_7","oe":["MPF对应cyclin B，SPF对应cyclin A，二者均含p34cdc2。"]},{"id":"ch13_fill_29","modI":0,"q":"不同时期的间期细胞与 M 期细胞融合产生______。[上海交通大学 2007 研]","a":"超前凝聚染色体","kp":"ch09_s3_3","oe":["间期细胞与M期细胞融合，间期染色质被诱导提前凝集。"]}],"term":[{"id":"ch13_term_1","modI":5,"term":"细胞周期（cell cycle）。","def":"细胞周期（cell cycle），又称细胞分裂周期，是指各细胞的生活周期，即细胞从一次有 丝分裂结束到下一次有丝分裂完成所经历的一个有序过程。增殖中体细胞其细胞周期可分分 裂期 M 和间期。M 又分前期、前中期、中期、后期、末期。间期又分 G1 期、S 期、G2 期。","kps":"","kp":"ch09_s1_0"},{"id":"ch13_term_2","modI":2,"term":"检验点（checkpoint）。","def":"检验点（checkpoint），又称限制点，指细胞对一些环境因素有一敏感点，可以限制细 胞通过周期，是控制 cell 增殖的关键。","kps":"","kp":"ch09_s2_3"},{"id":"ch13_term_3","modI":0,"term":"成熟促进因子（MPF）。","def":"成熟促进因子（MPF）是指由 CDK1 和周期蛋白 B 结合而成，调控细胞由 G2 期向 M 期转化的一种酶。","kps":"","kp":"ch09_s3_5"},{"id":"ch13_term_4","modI":2,"term":"染色体超前凝集（PCC）。","def":"染色体超前凝集（PCC）是指与 M 期细胞融合的间期细胞发生的形态各异的染色体凝 集。","kps":"","kp":"ch09_s3_3"},{"id":"ch13_term_5","modI":5,"term":"细胞周期依赖激酶（CDK）。","def":"细胞周期依赖激酶（CDK），即周期蛋白依赖性蛋白激酶，是一类含有一段类似氨基 酸序列的蛋白，它们可以和周期蛋白结合并受后者的调，可以磷酸化其他蛋白，比如组蛋白 H1、核纤层蛋白等，在细胞周期调控中发挥重要的作用。","kps":"","kp":"ch09_s5_0"},{"id":"ch13_term_6","modI":5,"term":"细胞周期蛋白（cyclins）.。","def":"细胞周期蛋白（cyclins）是结合并调节 CDK 的活性的一类蛋白，其含量随细胞周期进 程变化而变化，一般在细胞间期内积累，在细胞分裂期消失，在下一个细胞周期中又重复出 现，其含有一段比较保守的氨基酸序列。","kps":"","kp":"ch09_s4_0"},{"id":"ch13_term_7","modI":0,"term":"后期促进因子复合体（anaphase-promoting complex，APC）。","def":"后期促进因子复合体 APC 主要介导两类蛋白降解：后期抑制因子和有丝分裂周期蛋白。 前者维持姐妹染色单体粘连，抑制后期启动；后者的降解意味着有丝分裂即将结束，即染色 体开始去凝集，核膜重建。APC 可被 Cdc20 激活。但是，在有丝分裂前期，Cdc20 和 Mad2 蛋白位于染色体的动粒上，在染色体结合有丝分裂纺锤体的微管前将不能从动粒上释放，由 于 Mad2 与 Cdc20 结合而抑制 Cdc20 的活性。所以只有所有染色体都与纺锤体微管结合后， Cde20 释放出来作用于 APC，APC 才有活性，才启动细胞向后期转换。","kps":"","kp":"ch09_s6_17"},{"id":"ch13_term_8","modI":5,"term":"泛素-蛋白酶体途径（ubiquitin-proteasome pathway）。","def":"泛素-蛋白酶体途径是细胞内降解短寿命蛋白质的重要途径，与细胞多种生理功能调节 密切相关。首先通过酶 El、E2 和 E3 的作用使将要被降解的蛋白质泛素化，再由蛋白酶体 使泛素化的蛋白质完全水解。","kps":"","kp":"ch09_s6_13"},{"id":"ch13_term_9","modI":3,"term":"复制起始点识别复合体（origin recognition complex，Ore）。","def":"复制起始点识别复合体含有 6 个亚单位，识别 DNA 复制起始位点并与之结合，是 DNA 复制起始所必需的。","kps":"","kp":"ch09_s1_4"},{"id":"ch13_term_10","modI":4,"term":"抑癌基因（turmor．suppressor gene）。","def":"编码的蛋白质直接或间接抑制细胞周期进程的基因，该基因发生的功能丢失突变是致癌 的。许多肿瘤抑制基因（如 RB，APC，BRCAl）的单个突变体等位的遗传能大大提高形成 某种类型肿瘤的危险性。抑癌基因又称肿瘤抑制基因，是细胞的制动器（brake），它们编 码的蛋白质抑制细胞生长，并阻止细胞癌变。在正常的二倍体细胞中，每一种抑癌基因都有 两个拷贝，只有当两个拷贝都丢失了或两个拷贝都失活了才会使细胞失去增殖的控制，只要 有一个拷贝是正常的，就能够正常调节细胞的周期。从此意义上说，抑癌基因的突变是功能 丧失性突变。","kps":"","kp":"ch13_s4_0"},{"id":"ch13_term_11","modI":2,"term":"肿瘤坏死因子（Tumor necrosis factor (TNF)）","def":"肿瘤坏死因子是主要的死亡配体，最初发现存在于注射细菌脂多糖后的小鼠血清中，能 够使肿瘤组织出血坏死。肿瘤坏死因子主要由激活的单核-巨噬细胞分泌，诱导细胞凋亡和 诱发炎症反应是其主要的生理效应。肿瘤坏死因子的生物学功能是通过与细胞表面的受体结 合来实现的。","kps":"","kp":"ch13_s0_0"},{"id":"ch13_term_12","modI":4,"term":"癌基因 VS 肿瘤抑制因子 相关试题：oncogene（Oncogene vs. tumor suppressor）","def":"（1）癌基因 癌基因是控制细胞生长和分裂的正常基因，其突变能引起正常细胞癌变。癌基因可分为病毒 癌基因和细胞癌基因两大类。病毒癌基因是指反转录病毒的基因组里带有可使受病毒感染的 宿主细胞发生癌变的基因。细胞癌基因即原癌基因，是指在正常细胞基因组中对细胞正常生 命活动起主要调控作用的基因，在发生突变或被异常激活后变成具有致癌能力的癌基因。 （2）肿瘤抑制因子 肿瘤抑制因子又称抑癌基因，是正常细胞增殖过程中的负调控因子，它编码的蛋白在细胞周 期的检验点上起阻遏周期进程的作用。抑癌基因有两个拷贝，其中一个拷贝正常，可保证正 常的调控作用，两个拷贝都丢失或失活，才能引起细胞增殖的失控。 抑癌基因与癌基因之间的区别：癌基因的突变性质为显性，抑癌基因的突变性质为隐性。","kps":"","kp":"ch13_s5_7"},{"id":"ch13_term_13","modI":5,"term":"checkpoint（Checkpoint）","def":"checkpoint 的中文名称是细胞周期检验点。细胞周期检验点是指细胞中对其之前阶段任 务完成情况进行检测的某个特定位点，若完成则可进入下一个细胞周期阶段，否则细胞将停 留在该位点所处的阶段。这是对细胞周期进行监控的重要机制。细胞周期检验点有 G1 期检 验点、S 期检验点、G2 期检验点、纺锤体装配检验点等。","kps":"","kp":"ch09_s2_3"},{"id":"ch13_term_14","modI":5,"term":"cyclin（Cyclin）","def":"cyclin 的中文名称是细胞周期蛋白。细胞周期蛋白是一种参与细胞周期调控的蛋白，能 与 CDK 激酶的催化亚基结合，协助蛋白激酶完成催化功能，其浓度在细胞周期中是浮动的， 呈周期性变化，在不同周期，有着不同的浓度。","kps":"","kp":"ch09_s4_0"},{"id":"ch13_term_15","modI":0,"term":"早熟染色体凝集（Premature chromosome condensation (PCC)）","def":"早熟染色体凝集（PCC）是指 M 期细胞与其他间期细胞在一定介质（如仙台病毒）介 导下发生融合，继续培养一段时间后，与 M 期细胞融合的间期细胞发生了形态各异的染色 体凝集现象。G1 期 PCC 为细单线状，S 期 PCC 为粉末状，G2 期 PCC 为双线染色体状。","kps":"","kp":"ch09_s3_3"},{"id":"ch13_term_16","modI":5,"term":"CDK 蛋白（Cyclin-dependent kinase (CDK)）","def":"CDK 蛋白是依赖于细胞周期蛋白的一类蛋白激酶，可以和周期蛋白结合并接受后者的 调节，可以磷酸化其他蛋白，在细胞周期中发挥重要的作用。CDK 蛋白包括 CDK1～13， 其中 CDK1 即 MPF。各种 CDK 均含有一段类似的 CDK 激活结构域，且不同 CDK 结合的 周期蛋白不同，在细胞周期中执行不同的调节功能。","kps":"","kp":"ch09_s5_0"}],"short":[{"id":"ch13_short_1","modI":0,"q":"简述 CDK1（MPF）激酶的活化过程。","a":"CDK1 激酶活化的过程如下： （1）首先调节亚基周期蛋白 B 或 A 必须与 CDK1 结合。 （2）weel／mikl 激酶使的 CDK1 的 Thr14 和 Tyr15 磷酸化，CAK（CDK1-activating kinase） 催化 Thr161 的磷酸化。 （3）磷酸酶 Cdc25c 催化 Thr14 和 Tyr15 去磷酸化。 （4）CDK1 表现出蛋白激酶活性，调控细胞周期的进程。","kp":"ch09_s6_3","kps":"①周期蛋白B/A结合CDK1；②weel/mikl磷酸化Tyr15，CAK磷酸化Thr161；③Cdc25脱磷酸激活"},{"id":"ch13_short_2","modI":5,"q":"MPF（M 期或成熟促进因子）是如何通过实验发现的？","a":"MPF 是通过一下几个实验的发现的： （1）将 Hela 细胞同步于细胞周期的不同阶段然后和 M 期细胞混合，细胞融合后发现间期 细胞产生形态各异的染色质凝集现象。 （2）用孕酮处理未成熟的卵母细胞令其成熟，将其胞质注射到另一个未成熟卵母细胞中， 结果导致后者发生减数分裂，此成熟卵母细胞胞质可继续依上法诱导另一个受体卵母细胞成 熟。 （3）在有蛋白质合成抑制剂的条件下，孕酮不能诱导未成熟的卵母细胞成熟，而成熟卵母 细胞胞质可以诱导其成熟。 上述实验提示在 M 期细胞中可能存在一种诱导染色质凝集、诱导卵母细胞成熟的因子，命 名为促成熟因子（MPF），随后 MPF 被纯化，并证明含有 p32 和 p45 两种蛋白。","kp":"ch09_s3_4","kps":"①各期Hela与M期细胞融合，间期核染色质凝集；②孕酮诱导卵母细胞成熟，胞质注射可再诱导；③蛋白合成抑制剂下孕酮失效"},{"id":"ch13_short_3","modI":5,"q":"细胞周期调控系统的主要作用是什么？","a":"（1）在适当时候激活细胞周期各个时相的相关酶和蛋白，然后自身失活（正调控）； （2）确保每一时相事件的全部完成（负调控）；（3）对外界环境因子起反应（如多细胞生 物对增殖信号的反应）。","kp":"ch09_s3_0","kps":"①适时激活各时相酶和蛋白后自身失活（正调控）；②确保每一时相事件完成（负调控）；③对外界环境因子如增殖信号起反应"},{"id":"ch13_short_4","modI":5,"q":"细胞周期调控的分子机制如何？","a":"细胞周期控制系统中有两类关键的蛋白家族：一类是周期蛋白依赖性的蛋白激酶 （cyclin-dependent protein kinase，Cdk）。它能使特定蛋白质的丝氨酸和苏氨酸残基磷酸化 引发细胞周期事件；第二类是周期蛋白（cyclin）。它能够同 Cdk 结合，并控制 Cdk 使适当 蛋白磷酸化的能力。周期蛋白同 Cdk 蛋白复合物的装配和去装配，决定着细胞周期的进程。 有两类主要的周期蛋白：一类是有丝分裂周期蛋白。它是在 G2 期以及将要进入有丝分裂期 时同 Cdk 蛋白分子结合；另一类是 Gl 周期蛋白。它是在 G1 期以及将要进入 S 期时同 Cdk 分子结合。","kp":"ch09_s3_0","kps":"Cdk使蛋白丝/苏氨酸磷酸化引发周期事件；cyclin与Cdk结合并控制其活性；复合物装配决定周期进程"},{"id":"ch13_short_5","modI":0,"q":"将 G1 期细胞与 S 期细胞融合，观察融合后细胞核的变化。试描述现象并对此进行解释。","a":"G-期细胞融合后其核内染色质变得较伸展，DNA 开始复制。这是因为 S 期细胞内的蛋 白质因子启动了 G1 期细胞内的 DNA 复制。","kp":"ch09_s3_3","kps":"现象：G1期核染色质变伸展、DNA开始复制；解释：S期细胞内存在蛋白质因子，启动了G1期细胞内的DNA复制"},{"id":"ch13_short_6","modI":5,"q":"海胆的细胞周期蛋白 B 是如何鉴定到的？","a":"实验中将同步化的受精的海胆卵细胞培养在有放射性氨基酸的培养液中，每 10 min 取 样一次分离纯化蛋白质，然后通过凝胶电泳、放射自显影进行蛋白质分析。结果发现，经过 几轮细胞周期之后，放射性标记的蛋白质的量稳定增加。其中有一种蛋白峰在有丝分裂的早 期特别高，但是到了有丝分裂后期就急剧下降，然后在下一个细胞周期又慢慢积累直到有丝 分裂前达到高峰，这种蛋白质后来被命名为细胞周期蛋白 B（cyclin B）。科学家用基因工 程技术从海胆中分离了细胞周期蛋白 B 的 cDNA 克隆，然后用这种 cDNA 作探针从非洲爪 蟾中分离了同源的细胞周期蛋白 B 的 cDNA 克隆，最后用周期蛋白 B 制备的抗体证明了非 洲爪蟾中的 MPF 的一个亚基的确是细胞周期蛋白 B。","kp":"ch09_s4_0","kps":"放射性氨基酸培养同步化海胆卵，凝胶电泳加自显影；某蛋白M早期高、后期降、下周期渐积至M前达峰，命名cyclin B"},{"id":"ch13_short_7","modI":0,"q":"试述真核生物 G2／M 转换的机制。","a":"真核生物 G2／M 的转换实际上就是 MPF 的完全激活。P34cdc2 与周期蛋白 B 结合，形成 的是无活性的 MPF。然后在激酶 weel 和 mikl 的作用下，将 P34cdc2 的 Tyr15 和 Thr167 磷酸 化，形成的是无活性的前 MPF，然后在 Cdc25 磷酸酶的作用下，将 Tyr15 位的磷酸脱去， 形成活性 MPF，使一系列的底物发生磷酸化，进入 M 期。由此看来，Tyr15 位的磷酸化起 抑制作用，Thr167 磷酸化起激活作用。","kp":"ch09_s3_6","kps":"Cdc2与周期蛋白B结合成无活性MPF；weel/mikl磷酸化Tyr15、Thr167；Cdc25脱磷酸激活MPF"},{"id":"ch13_short_8","modI":5,"q":"关卡（checkpoint）位于细胞周期的哪些阶段?每次“检查”什么？","a":"控制系统至少有三个关卡，G1 关卡（靠近 G1 末期）、G2 关卡（靠近 G2 末期）、中期 关卡（中期末）。每一个关卡处，由细胞所处的状态与环境决定细胞能否通过此关卡，进入 下一阶段。 （1）G1 关卡（限制点）检测细胞大小和环境，如果条件合适就会激发 DNA 复制，使控制 系统向前移动。（2）G2 关卡处，控制系统检测细胞大小、状态，以及 DNA 复制是否完毕。 （3）在中期关卡，控制系统检测所有染色体是否都与纺锤体相连并排列于赤道板上，检测 MPF 是否失活，否则不能进行有丝分裂和胞质分裂。","kp":"ch09_s2_3","kps":"G1关卡查细胞大小与环境，合适则启动DNA复制；G2关卡查大小及DNA复制完成；中期关卡查染色体排列及MPF失活"},{"id":"ch13_short_9","modI":0,"q":"何为癌细胞？癌细胞的基本生物学特征包括哪些？","a":"癌细胞是指由于基因突变，正常细胞的生长分化失控，脱离了衰老和死亡的正常途径， 而具有无限增殖特性的细胞。其基本特征有： （1）细胞生长与分裂失去控制，具有无限增殖能力，成为“永生”细胞； （2）具有侵润性和扩散性； （3）细胞间相互作用改变； （4）mRNA 表达谱系及蛋白表达谱系或蛋白活性改变； （5）染色体非整倍性。","kp":"ch13_s0_3","kps":"因基因突变致生长分化失控、脱离衰老死亡、无限增殖的细胞；特征：无限增殖成永生、浸润扩散、细胞间作用改变、染色体非整倍性"},{"id":"ch13_short_10","modI":5,"q":"为什么抑癌基因是隐性基因，而癌基因表现为显性基因作用？","a":"如果抑癌基因的一个等位基因发生突变，该突变基因的产物就不能正常发挥功能；肿瘤 的形成是由于完全缺乏了功能正常的肿瘤抑制蛋白，由于另一个未突变的抑癌基因的等位基 因的产物能够充当其在细胞周期调控中的角色，细胞不会癌变，因此抑癌基因的突变表现为 隐性。对于癌基因来说，不正常的蛋白质产物足以致癌，因为这种基因产物的作用是刺激细 胞生长分裂，而不是进行负调控。即使存在功能正常的原癌基因产物（由另一未突变的等位 基因编码），细胞也会出现恶变，因此癌基因的作用是显性的。","kp":"ch13_s5_7","kps":"抑癌基因凭另一正常等位产物代偿，需两等位失活才癌变故隐性；癌基因异常产物足以致癌，一个等位突变即恶变故显性"},{"id":"ch13_short_11","modI":0,"q":"良性和恶性肿瘤的主要异同是什么？","a":"都由于细胞生长失控而造成，但良性肿瘤缺乏在体内转移的能力，所以可通过手术根除； 而转移性的恶性肿瘤的细胞可脱离原来的位置，侵入邻近的组织或更远的位置，并在新的位 点迅速生长。恶性肿瘤常由良性肿瘤转化而来。","kp":"ch13_s0_14","kps":"同：均因细胞生长失控；异：良性缺乏转移能力、可手术根除；恶性可脱离原位、侵入邻近或远处组织并迅速生长；恶性常由良性转化"},{"id":"ch13_short_12","modI":4,"q":"P53 蛋白含有哪些功能结构域?哪些在肿瘤细胞中发生了突变？","a":"P53 包括一个转录激活结构域，一个识别特异的由 10 个碱基对组成的回文序列的 DNA 结合结构域，一个寡聚体化结构域，和一个结合非特异性损伤 DNA（单链）的 C 端结构域。 大部分的致癌突变位于位点特异性 DNA 结合结构域中。 ②基因扩增。某些造血系统恶性肿瘤（如前髓细胞性白血病）中，c-myc 扩增 8～32 倍。 ③DNA 重排。染色体的易位使原癌基因处于活跃转录基因强启动子的下游，将产生过度表 达。如 Burkitt 淋巴瘤细胞的染色体易位，使 c-myc 与 IG 重链基因的调控区为邻。 ④插入激活。某些不含 v-onc 的弱转化逆转录病毒具有冗长末端重复序列（LTR），含有启 动子、增强子，插入基因组后引起下游基因过表达。","kp":"ch13_s4_4","kps":"结构域：转录激活域、识别10bp回文序列的DNA结合域、寡聚体化域、结合损伤单链DNA的C端域；致癌突变多在DNA结合域"},{"id":"ch13_short_13","modI":5,"q":"为什么说 CDK 在细胞周期调控中具有重要作用？如何调控？","a":"参见 14.2 课后习题详解中第 3 题。","kp":"ch09_s5_0","kps":"CDK为周期调控核心，与cyclin成复合物磷酸化底物驱动周期；受CAK、weel/mikl、Cdc25等调控"},{"id":"ch13_short_14","modI":0,"q":"请简要叙述肿瘤细胞相对于正常细胞而言，在细胞水平上所特有的基本特征。 相关试题：癌细胞具有哪些不同于正常细胞的特性？","a":"肿瘤细胞相对于正常细胞而言的特征有： （1）细胞生长和分裂失去控制 正常细胞执行其特定的生理功能(如肝细胞和神经细胞)，会有新生细胞的增殖、衰老细胞的 死亡，在动态平衡中维持组织与器官的稳定，这是一种严格受控的过程。癌细胞生长失去控 制，成为永生细胞，核质比例增大，分裂速度加快，破坏了正常组织的结构与功能。 （2）具有浸润性和扩散性 恶性肿瘤细胞（癌细胞）的细胞间黏着性下降，具有浸润性和扩散性，易于浸润周围健康组 织，或通过血液循环或淋巴途径转移并在其他部位黏着和增殖。此外，癌细胞在分化程度上 低于正常细胞和良性肿瘤细胞，失去了原组织细胞的某些结构和功能。 （3）细胞间相互作用改变 癌细胞冲破了细胞识别作用的束缚，在转移过程中，除了会产生水解酶类（如用于水解基底 膜成分的酶类），而且要异常表达某些膜蛋白，以便与别处细胞黏着和继续增殖，并借此逃 避免疫系统的监视，防止天然杀伤细胞等的识别和攻击。 （4）表达谱改变或蛋白活性改变 对癌细胞与正常细胞中基因表达谱进行检测比较，不同的转录片段仅占整个基因表达谱中很 少一部分；蛋白质表达谱系中，常出现一些在胚胎细胞中所表达的蛋白质，还异常表达与其 恶性增殖、扩散等过程相关的蛋白质组分。由于癌细胞基因突变位点不同，表型不稳定，决 定了癌细胞异质性的特征。 （5）体外培养的恶性转化细胞的特征 应用人工诱导技术培养出恶性转化细胞，同癌细胞一样具有无限增殖的潜能，在体外培养时 贴壁性下降，可不依附在培养器皿壁上生长，有些还可进行悬浮式培养；失去运动和分裂的 接触抑制，在软琼脂培养基中可形成细胞克隆。当将恶性转化细胞注入易感染动物体内时， 往往会形成肿瘤。","kp":"ch13_s0_3","kps":"生长分裂失控、无限增殖成永生、核质比增大；细胞间黏着性下降、具浸润扩散性、易转移、分化低；细胞间作用改变、失去接触抑制"},{"id":"ch13_short_15","modI":2,"q":"为什么说肿瘤既是一种基因性疾病，又是一种细胞性疾病？","a":"（1）肿瘤是一种基因性疾病的原因 肿瘤的发生是基因突变逐渐累积的结果。在分子层面上，肿瘤细胞的基因已经不同于正常细 胞的基因，肿瘤是发生一系列基因突变的累积结果，因此认为它是一种基因性疾病。 （2）肿瘤是一种细胞性疾病的原因 在细胞层面上，肿瘤细胞发生了很多异常变化。 ①细胞之间的黏着性降低，具有浸润性和转移性； ②细胞生长与分裂失去控制； ③体外培养的恶性转化细胞：具有无限增殖的潜能，贴壁性下降，有些可进行悬浮式培养； 失去运动和分裂的接触抑制，在软琼脂培养基中可形成细胞克隆。 因此从这个层面上讲，肿瘤又是一种细胞性疾病。","kp":"ch13_s3_0","kps":"基因性：肿瘤是基因突变累积结果，基因不同于正常细胞；细胞性：黏着性降低、浸润转移、生长分裂失控、无限增殖、软琼脂可成克隆"},{"id":"ch13_short_16","modI":5,"q":"什么是原癌基因？为什么突变后会导致细胞癌变？","a":"（1）原癌基因的定义 原癌基因又称细胞癌基因，是指在正常细胞基因组中对细胞正常生命活动起主要调控作用的 基因，在发生突变或被异常激活后变成具有致癌能力的癌基因。 （2）原癌基因突变后导致细胞致癌的原因 ①原癌基因的编码区发生突变，改变了原有的基因结构，致使编码产物的性质发生变化，使 其不再具有正常的活性。 ②原癌基因的调节区发生突变，从而改变了结构基因表达方式，可能大大增加表达量。 ③通过染色体重排，使不在一起的基因序列同原癌基因排列在一起，可能会合成新的蛋白或 融合蛋白，改变原有基因的自然活性。 上述中任何一种突变，都有可能使细胞失去正常的分裂控制，从而向恶性方向转变即发生癌 变。","kp":"ch13_s5_0","kps":"原癌基因是正常基因组中调控生命活动的基因，突变或异常激活后成癌基因；编码区突变、调节区突变、染色体重排致分裂失控"},{"id":"ch13_short_17","modI":0,"q":"简述发现海胆周期蛋白 B 的实验过程。","a":"发现海胆周期蛋白 B 的实验过程如下： （1）以 Tim Hunt 为代表的科学家以海胆卵为实验材料，对细胞周期进行深入研究。1983 年，他们报道在海胆卵细胞中存在两种特殊蛋白质。这两种蛋白质的含量随细胞周期进程变 化而变化，一般在细胞间期内积累，在细胞分裂期内消失，在下一个细胞周期中又重复这一 消长过程。因此他们将这两种蛋白质命名为周期蛋白（cyclin）。 （2）这些周期蛋白很快被分离和克隆出来，并被证明广泛存在于从酵母到人类等各种真核 生物中。 （3）用柱层析从蛙卵中纯化 MPF 之后，James Maller 和 Tim Hunt 实验室合作，证明周期蛋 白 B 是 MPF 的一种成分。","kp":"ch09_s4_0","kps":"Tim Hunt以海胆卵为材料，发现随周期消长的蛋白，间期积累、分裂期消失，命名cyclin；克隆证明其为MPF组分"},{"id":"ch13_short_18","modI":2,"q":"简述 MPF 的组成和在 G2∕M 期进程中的作用。","a":"（1）MPF 的组成 MPF 即成熟促进因子，是一种促进细胞成熟和分裂的调控性蛋白激酶。成熟促进因子的生 化成分是两个亚单位，一个是 Cdc2 蛋白，一个是周期蛋白 B。Cdc2 蛋白（p34cdc2）为催化 亚基，周期蛋白为调节亚基，二者结合后，表现出蛋白激酶活性。 （2）MPF 在 G2∕M 期进程中的作用 当 Cdc2 蛋白和周期蛋白结合后，MPF（CDK1）表现出蛋白激酶活性，磷酸化下游的蛋白 质分子，促进细胞周期由 G2 向 M 期转化，从而促进细胞成熟或分裂，Cdc2 蛋白是其催化 亚单位，周期蛋白是其调节亚单位。","kp":"ch09_s3_7","kps":"组成：Cdc2(p34cdc2)为催化亚基、周期蛋白B为调节亚基，结合后具蛋白激酶活性；促G2向M期转化，促细胞成熟分裂"},{"id":"ch13_short_19","modI":6,"q":"简述 p53 基因“基因卫士”的功能。","a":"p53 基因“基因卫士”的功能如下： （1）p53 基因时刻监控着细胞染色体 DNA 的完整性，一旦细胞染色体 DNA 遭到损害，p53 蛋白与基因的 DNA 的相应结合部位结合，起特殊转录因子的作用： ①活化 p21 基因转录，使细胞停滞于 G1 期，抑制解链酶的活性； ②与复制因子 A 相互作用，参与 DNA 的复制与修复，使 DNA 受损的细胞不再分裂，修复 损伤而维持基因组的稳定。 （2）如果修复失败，p53 蛋白即启动程序性死亡（凋亡）过程诱导细胞自杀，使细胞周期 停滞，阻止有癌变倾向的突变细胞的生成，从而达到抑制肿瘤发生的作用。","kp":"ch13_s4_4","kps":"监控DNA完整性；受损时作转录因子：活化p21使细胞停滞于G1、抑制解链酶、与复制因子A互作参与修复；修复失败则启动凋亡"},{"id":"ch13_short_20","modI":0,"q":"Ras 蛋白在信号转导中的作用，谈谈突变 Ras 致癌的可能机制。 相关试题：Ras 蛋白是细胞信号转导途径中的一个重要分子开关。ras 基因突变会导致蛋白 GTP 酶活性丧失，并且会导致正常细胞发生癌变。请解释这一现象。","a":"（1）Ras 蛋白在信号转导中的作用 Ras 蛋白是一种小的 GTP 结合蛋白，具有 GTP 酶活性，位于胞质侧，结合 GTP 时为活化态， 结合 GDP 时失活。Ras 蛋白具有分子开关作用，激活磷酸化级联反应。GAP 增强 Ras 蛋白 的 GTP 酶活性。 （2）突变 Ras 致癌的可能机制 发生突变的 Ras 蛋白能够与 GTP 结合，但不能将其水解成 GDP，从而使自身锁定于活化状 态，导致变性、细胞转化和肿瘤发生。","kp":"ch13_s5_2","kps":"Ras为小GTP结合蛋白，GTP结合活化、GDP结合失活，是分子开关，GAP增强其酶活性；突变Ras不能水解GTP"},{"id":"ch13_short_21","modI":4,"q":"概述细胞周期蛋白 B 在分裂后期的降解途径、机理和调控因素。","a":"（1）细胞周期蛋白 B 降解途径 细胞周期蛋白 B（cyclin B）在分裂后期的降解是通过泛素化-蛋白酶体降解途径。蛋白质的 泛素化需要泛素活化酶（E1）、泛素结合酶（E2，又称泛素载体蛋白）和泛素连接酶（E3） 的先后催化来完成，具体过程如下： ①E1 活化泛素分子； ②泛素分子转移至 E2； ③E3 催化形成异肽键； ④靶蛋白（cyclin B）被泛素化； ⑤蛋白酶体识别泛素化靶蛋白、ATP 水解驱动泛素移除、靶蛋白解折叠转入蛋白酶体核心 内被降解。 （2）周期蛋白 B 在分裂后期降解的机理 染色体与纺锤体结合后，Mad2 从动粒上消失，对 Cdc2 的抑制解除，Cdc2 是后期促进复合 物 APC 的正调控因子，因而能激活 APC，APC 是一种泛素化途径中的 E3 连接酶，促进 cyclin B 的降解。泛素化途径通过 E1、E2、E3 三个酶对需要降解的蛋白质打上多泛素链标签，具 有这个标签的蛋白质最终被蛋白酶体水解。 （3）周期蛋白 B 在分裂后期降解的调控因素 cyclin B 的调控因素包括其自身的破坏框和 APC，其自身破坏框氨基酸残基的突变或者 APC 的突变都能使 cyclin B 的降解被阻断。","kp":"ch09_s6_13","kps":"泛素-蛋白酶体途径；E1→E2→E3催化异肽键、泛素化靶蛋白；蛋白酶体ATP依赖降解；Mad2消失解除Cdc2抑制"},{"id":"ch13_short_22","modI":5,"q":"影响细胞增殖周期的因素有哪些？细胞增殖周期与许多医学问题密切相关，举例说明。","a":"（1）影响细胞增殖周期的因素 ①环境中控制细胞增殖的因素，特别是各种生长因子。不少生长因子受体具有蛋白激酶活性， 在生长调节中通过对各种靶蛋白磷酸化实现其对细胞增殖的调节作用； ②生长因子受体的传感机制，最终引起细胞内有关增殖基因的表达，调控细胞增殖； ③某些基因及其产物与细胞增殖调控的关系，其中包括癌基因、细胞分裂周期基因等。 （2）细胞增殖周期与医学问题密切相关的例子 细胞周期检验点功能的减弱，导致突变基因的累积和正常细胞的进化，只有当这些累积的突 变基因，破坏了细胞周期的驱动机制，细胞才进入失控性生长的境界（癌变）。 六、实验题","kp":"ch09_s3_0","kps":"生长因子及受体蛋白激酶磷酸化靶蛋白；受体传感机制引发增殖基因表达；癌基因、细胞分裂周期基因；检验点减弱致突变累积→癌变"},{"id":"ch13_short_23","modI":4,"q":"细胞周期运转到分裂中期时，周期蛋白 A 和周期蛋白 B 通过泛素化途径降解。 （1）简述蛋白质的泛素化降解途径； （2）在上述泛素化降解途径中，蛋白降解的特异性（亦即确保只有该降解的蛋白被降解） 是如何实现的？ （3）周期蛋白 A 和 B 的分子结构中含有一段由 9 个氨基酸序列组成的破坏框。请设计一个 实验，证明该破坏框在周期蛋白 A 和 B 的泛素化降解途径中起了重要作用。 （4）如何证明周期蛋白 A 和 B 的存在对于驱动细胞周期从 M 期中期向后期的转化是必须 的？请提出两种不同的实验方案。","a":"（1）蛋白质的泛素化降解途径 泛素依赖性降解途径对于控制蛋白质寿命具有重要作用。蛋白质的泛素化需要泛素活化酶 （E1）、泛素结合酶（E2，又称泛素载体蛋白）和泛素连接酶（E3）的先后催化来完成， 具体过程如下： ①E1 活化泛素分子； ②泛素分子转移至 E2； ③E3 催化形成异肽键； ④靶蛋白被泛素化； ⑤蛋白酶体识别泛素化靶蛋白、ATP 水解驱动泛素移除、靶蛋白解折叠转入蛋白酶体核心 内被降解。 （2）确保只有该降解的蛋白被降解的机制 蛋白降解的特异性是因为降解的蛋白有其特异的 E3。E3 是泛素与底物蛋白特异性结合的决 定者，参与泛素对底物蛋白的识别，是决定泛素依赖的蛋白降解特异性的关键因子。 （3）证明该破坏框在周期蛋白 A 和 B 的泛素化降解途径中起重要作用的实验设计 将周期蛋白 A 和 B 的破坏框突变，引入到细胞中表达，结果显示周期蛋白 A 和 B 不能通过 泛素化途径降解。结论：此破坏框在周期蛋白 A 和 B 的泛素化降解途径中起了重要作用。 （4）证明周期蛋白 A 和 B 的存在对于驱动细胞周期从 M 期中期向后期的转化是必须的实 验方案 ①方案一：采用 siRNA 分别将编码周期蛋白 A、编码周期蛋白 B 的基因突变，使之不能表 达，通过收集培养细胞，观察其细胞周期变化情况。 具体设计三组： a．突变编码周期蛋白 A 基因； b．突变编码周期蛋白 B 基因； c．同时突变编码周期蛋白 A 基因和编码周期蛋白 B 基因。 结果：三组实验的细胞周期均停留在 M 期中期。 结论：周期蛋白 A 和 B 的存在对于驱动细胞周期从 M 期中期向后期的转化是必须的。 ②方案二：采用基因敲除分别将编码周期蛋白 A、编码周期蛋白 B 的基因突变，使之不能 表达，通过收集培养细胞，观察其细胞周期变化情况。实验分组同方案一。 结果：三组实验的细胞周期均停留在 M 期中期。 结论：周期蛋白 A 和 B 的存在对于驱动细胞周期从 M 期中期向后期的转化是必须的。","kp":"ch09_s6_13","kps":"①E1→E2→E3泛素化、蛋白酶体降解；②特异E3决定底物；③突变破坏框测稳定性；④敲除/抑制周期蛋白A/B看M期转化"},{"id":"ch13_short_24","modI":5,"q":"某实验室从酵母中克隆了一基因，并发现它的蛋白质产物与细胞周期的调控有关。为了 研究其在人细胞中同源的作用，请设计一套研究方案。","a":"依据前人研究这类基因时采用的方法，特别是 MPF 发现时各位科学家之间的合作研究 方法，进行相关试验设计。 （1）方法一 ①酵母基因的人源细胞表达及其表型的鉴定 将该基因构建到一个可以在人源细胞中表达的质粒载体中，然后用此质粒转染人源细胞，让 该基因在人源细胞中高表达，观察人细胞表型和一系列生化特征的的变化（表型变化如细胞 是否还可进行正常的细胞分裂，若不能则发生了哪些其他方面的形态变化等。生化特征如细 胞内调控周期循环的各种 CDK 和 cyclin 的变化，可以采用 western blot 技术进行检验）。 ②寻找人源细胞中的同源基因和同源蛋白 a．采用免疫动物法或者杂交瘤细胞制备方法制备抗体。 b．利用免疫共沉淀的方法，将抗体与人细胞裂解液孵育，得到相应的候选蛋白。对这些候 选蛋白进行鉴定，包括氨基酸序列和编码其的 mRNA、DNA 等序列，找到人细胞中的同种 基因。 （2）方法二 ①利用 BLAST 进行 BLASTx，进行简单的同源性分析，找到与其同源性较高的人类基因； ②将找出的人类同源基因进行克隆，并进行蛋白诱导表达； ③研究检测其蛋白功能。","kp":"ch09_s5_0","kps":"酵母基因转染人细胞高表达、观察表型；Western blot检CDK/cyclin变化；免疫动物或杂交瘤制抗体寻同源蛋白"},{"id":"ch13_short_25","modI":7,"q":"现有一种新筛选出的抗肿瘤新药 A，给你一瓶肿瘤细胞，你怎样在细胞水平验证该新药 A 的药效？请你设计一个实验，包括实验方法、实验材料、实验仪器、实验过程，及对预期 的实验结果的分析等。","a":"（1）实验方法 由于抗肿瘤药物的作用是引起肿瘤细胞的凋亡，用新药 A 对人肿瘤细胞进行处理后，利用 细胞凋亡过程中会被特异性切割，形成大小差别为 200bp 左右片段的特点，通过琼脂糖凝胶 电泳检测其有无特征的核小体断裂形成的梯状条带来鉴定新药 A 的功效。 （2）实验材料 人肿瘤细胞。 （3）实验仪器 水平电泳仪、凝胶成像系统等。 （4）实验过程 ①将人肿瘤细胞放入合适培养基培养； ②将新药 A 加入培养基中； ③一段时间后从培养基中收集细胞，利用 SDS∕酚法提取细胞基因组 DNA； ④将提取到的 DNA 进行琼脂糖凝胶电泳； ⑤取电泳完的琼脂糖凝胶用 EB 进行染色，15min 后取出冲洗，在紫外下，利用凝胶成像系 统观察 DNA 电泳情况； ⑥观察实验结果并分析。 （5）预期实验结果及分析 ①若基因组 DNA 出现典型的相隔 200bp 的梯状条带，则说明新药 A 有抗肿瘤功效； ②若基因组 DNA 无典型的相隔 200bp 的梯状条带呈现，则说明新药 A 无抗肿瘤功效。","kp":"ch13_s0_0","kps":"方法：检凋亡DNA梯状条带；材料：人肿瘤细胞；仪器：电泳仪、凝胶成像系统；步骤：加药→提DNA→琼脂糖电泳→EB染色"},{"id":"ch13_short_26","modI":5,"q":"为什么说肿瘤的发生是基因突变逐渐积累的结果？","a":"之所以说肿瘤的发生是基因突变逐渐积累的结果，原因如下： （1）癌细胞是一种变异的细胞，是产生癌症的病源，癌细胞与正常细胞不同，有无限生长、 转化和转移三大特点，难以消灭。 （2）癌症的发生一般并不是单一基因的突变，至少在一个细胞中发生 5～6 个基因突变，才 能赋予癌细胞所有的特征。 （3）与肿瘤发生相关的某一原癌基因的突变，并非马上形成癌，而是继续生长直至细胞群 体中新的偶发突变的产生。 （4）肿瘤的发生是一系列的原癌基因与抑癌基因的致癌突变的积累。 ①原癌基因的两个拷贝中只要一个基因发生突变，就会引起细胞增殖的失控。 ②抑癌基因有两个拷贝，其中一个拷贝正常，可保证正常的调控作用，两个拷贝都丢失或失 活，才能引起细胞增殖的失控。","kp":"ch13_s3_0","kps":"癌细胞无限生长、转化、转移；需5～6个基因突变；原癌与抑癌基因突变积累；原癌一拷贝突变即失控，抑癌两拷贝均变才失控"},{"id":"ch13_short_27","modI":0,"q":"什么是肿瘤干细胞？","a":"肿瘤干细胞是一群存在于某些肿瘤组织中的干细胞样细胞，具有自我更新、无限增殖、 转移和抗化学毒物损伤的能力。目前认为肿瘤干细胞的存在是导致肿瘤化疗失败的主要原因。 与一般的肿瘤细胞相比，肿瘤干细胞具有以下特性： （1）高致瘤性 很少量的肿瘤干细胞在体外培养，就能生成集落；将很少量的肿瘤干细胞注入实验动物体内， 即可形成肿瘤。 （2）强耐药性 多数肿瘤干细胞的细胞膜上表达 ATP 结合盒（ABC）家族膜转运蛋白，可运输并外排代谢 产物、药物、毒性物质、内源性脂质、多肽、核苷酸及固醇类等多种物质，使之对许多化疗 药物产生耐药性。","kp":"ch13_s0_0","kps":"肿瘤组织中干细胞样细胞；自我更新、无限增殖、转移、抗化学毒物；高致瘤性；强耐药性（ABC转运蛋白外排药）；化疗失败主因"},{"id":"ch13_short_y1","modI":3,"q":"比较癌基因与抑癌基因在作用、显隐性和突变方式上的差异。","a":"①作用：癌基因编码的产物促进细胞增殖、促进细胞转化，对细胞生长起阳性（促进）作用；抑癌基因正常时抑制细胞增殖和肿瘤发生，起阴性（抑制）作用。②突变方式与显隐性：癌基因通常为显性，一个拷贝突变/过度表达即可起作用（如Ras点突变）；抑癌基因在细胞水平为隐性，需两个拷贝都失活才失去功能（如p53、Rb）。③来源：癌基因由原癌基因经突变、扩增、易位等激活；抑癌基因由正常抑癌基因突变或缺失失活。④结果：二者异常均破坏细胞增殖的调控平衡，导致细胞生长失控和肿瘤发生。","kps":"作用:促增殖vs抑制;显隐性:显性(1拷贝)vs隐性(2拷贝);例:Ras vs p53/Rb;均破坏增殖平衡","type":"比较型","kp":"ch13_s5_7"}],"calc":[{"id":"ch13_calc_1","modI":4,"q":"为什么说蛋白质磷酸化-去磷酸化和泛素介导的蛋白质水解（UPP）的互相协调推动细胞 周期的运转？","a":"之所以说蛋白质磷酸化-去磷酸化和泛素介导的蛋白质水解（UPP）的互相协调推动细 胞周期的运转，是因为： （1）对细胞起核心作用的是 CDK 激酶，通过不同的周期蛋白与不同种类的 CDK 结合，在 细胞周期的不同周期表现出活性，因而对细胞周期的不同时期进行调节。 （2）CDK 激酶主要通过磷酸化与细胞周期进程相关的蛋白质，使它们在适当的时期表现出 相应的功能，促进细胞周期的运转，比如在 G2 向 M 期过渡的时候，MPF 被激活后，它可 以使组蛋白 H1 磷酸化，促进染色体凝集，使核纤层蛋白磷酸化，促使核纤层解聚，还可以 作用于微管蛋白，控制细胞周期中微管的动力学变化等，这些促使细胞由间期进入分裂期。 （3）去磷酸化在细胞周期中也起到很重要的作用，比如，CDK1 在非活性状态下其 Thr14 和 Tyr15 是磷酸化的，只有在 Cdc25 的作用下，使 Thr14 和 Tyr15 去磷酸化后才能表现出激 酶活性，从而调控细胞周期。再如，细胞运转到分裂中期后，被 MPF 磷酸化的蛋白去磷酸 化，细胞周期便从 M 期中期向后期转化。 （4）CDK 激酶被激活，其首先要与周期蛋白结合，而周期蛋白的浓度是随着细胞周期进程 的变化而变化的，从而使 CDK 激酶在特定时期表现活性，使得细胞周期正常运转，而周期 蛋白的周期性降解是通过泛素介导的蛋白质水解系统（UPPS）介导的。 综上所述，正是通过对蛋白质的磷酸化-去磷酸化和泛素介导的蛋白质水解系统对蛋白质的 降解，调控细胞周期中诸多蛋白的功能，并使其在正确的时间上执行功能，保证细胞周期的 正常运转。","kp":"ch09_s6_3","kps":"CDK/cyclin核心;磷酸化(MPF磷酸化H1/核纤层/微管);去磷酸化(Cdc25去磷酸化激活CDK1);UPP降解周期蛋白→单向运转"},{"id":"ch13_calc_2","modI":4,"q":"试述有丝分裂促进因子 MPF 在细胞周期中所起的作用，常用的研究细胞周期的方法有哪 些？","a":"（1）细胞周期中，M 期占用的时间最短，但细胞的形态变化最大。此阶段细胞的主要 生化特点是：RNA 合成停止，蛋白质合成减少，染色体高度螺旋化。由 G 期进入 M 期是细 胞周期中的另一个关键时期，M 期细胞质中存在一种染色质浓缩物质，即 M 期促进因子 MPF。如果将 M 期细胞与 G1、G2 或 S 期细胞融合，不论这些细胞中原来染色体状态如何， 都能使其浓缩。 （2）细胞周期常用研究方法：①细胞同步化法。可使处于不同细胞周期的细胞共同进入某 一特定阶段，即细胞同步化，有利于对细胞周期调控的研究。可分为物理法和化学法。物理 法有温度法、辐射法以及有丝分裂抖落法。化学法有 DNA 合成阻断法和细胞中期阻断法。 ②细胞周期调控研究法：免疫组化法、显微注射法、细胞融合法等。③3H-TdR 掺入法。利 用 3H-TdR 掺入法将同位素标记的 DNA 合成前体 TdR 掺入到 DNA 分子中．    可以对 S 期 DNA 合成动态过程加以研究，同时可以用于细胞周期的时间测定。","kp":"ch09_s3_8","kps":"MPF作用(G2→M、融合诱导PCC);研究方法:同步化、免疫组化/显微注射/细胞融合、3H-TdR"},{"id":"ch13_calc_3","modI":5,"q":"试述调控细胞周期的因素及分选机制。","a":"细胞增殖是一个多阶段，多因子参与的高低精确有序的活动过程，而这个过程是由不同 基因严格按照时间顺序表达的结果，也是基因与环境因素相互作用的结果。细胞周期的调控 严格有序、极其复杂的过程，涉及多个因子在多个层次上的作用，这些因子通常在细胞周期 某个特定时期（调控点）起作用。 （1）细胞周期蛋白（cyclin）家族和细胞周期蛋白依赖激酶：cyclin 家族有 cyclinA、B、C、 D、E、F、G、 H 等。CdK 家族有 CdKl、CdK2、CdK3、CdK4、CdK5 等。CdK 与 cyclin 结合形成的复合物可参与磷酸化多种蛋白质，这些磷酸化蛋白在细胞周期中对 DNA 复制和 有丝分裂事件起重要调节作用。 （2）促成熟因子（MPF）是一种在 G2 期合成能促进 M 期启动的调控因子。 （3）生长因子是一类与细胞膜上特异受体结合以调节细胞周期的多肽类物质，可来自细胞 的自分泌或旁分泌。这些因子与其他受体结合后，通过信号传导途径，激活细胞内多种蛋白 激酶，最终引起与细胞周期相关的蛋白质表达的改变进而调节细胞周期。 （4）抑素是一类细胞自身产生的对细胞周期过程有抑制作用的糖蛋白。 （5）RNA 剪接因子 SR 蛋白及 SR 蛋白的特异性激酶。 （6）癌基因与抑癌基因：在一些逆转录病毒的基因组中，存在一些 DNA 序列，可促进细 胞无限增殖而癌变，这些序列被称为病毒癌基因；许多细胞癌基因可编码一些生长因子受体。 通过与生长因子结合参与细胞周期的调控或者癌基因产物直接参与细胞内信号传导进而参 与细胞周期的调控；抑癌基因：正常细胞内，一类能抑制细胞恶性增殖的基因，称为抑癌基 因，如 Rb 基因、p53 基因等。","kp":"ch09_s3_0","kps":"调控因素:cyclin/CDK、MPF、生长因子;分选(检验点)机制"},{"id":"ch13_calc_4","modI":5,"q":"真核细胞周期调控模型的主要特点和机制是什么？","a":"特点表现在三类周期蛋白-Cdk 复合物和三个关键的过渡和对细胞周期的控制。 真核细胞主要通过三类周期蛋白-Cdk 复合物的作用，控制细胞周期，这三种复合物分别是： G1 期、S 期和有丝分裂 Cdk 复合物。这些复合物都是由周期蛋白依赖性的蛋白激酶和周期 蛋白两个亚基组成的复合物。在 Cdc34 途径和 APC 途径中，蛋白复合物都是通过遍在蛋白 的蛋白酶体将一些特殊的底物，包括 S 期抑制物、后期抑制物、以及有丝分裂周期蛋白降 解进行周期调节。 细胞周期中三个关键的过渡，即 G1 期→S 期、中期→后期、后期→末期及胞质分裂期的过 渡。这些过渡都是通过触发蛋白质的降解进行的，所以都是不可逆转的，这样迫使细胞周期 只能沿一个方向进行。 三个过渡分别是通过 Cdc34 和 APC 途径的降解作用完成的。Cdc34 途径促使细胞从 G1→S 期过渡：在 G1 期的早、中期，在 DNA 的复制起点就装配了复制起始复合物，并且开始了 S 期的 CdkC 组份的转录；但是，S 期 CdkC 抑制物被 G1CdkC 磷酸化而激活，激活的 S 期 CdkC 抑制物抑制了 S 期 CdkC 的活性，从而使细胞停留在 G1 期。在 G1 期的后期，Cdc34 诱导 S 期 Cdk 抑制物的降解，释放出有活性的 s 期 Cdk 复合物，这种复合物能够激发细胞进入 S 期。 一旦 S 期 Cdk 的降解作用被激活，S-期 Cdk 复合物将与 DNA 形成预复制复合物中的蛋白质 的调节位点磷酸化，预复制起始复合物是 G1 期在 DNA 复制起点上装配的复合物。这些被 S 一期 Cdk 复合物磷酸化的蛋白质不仅能够激活 DNA 复制起始，还能够阻止新的预复制复合 物的装配。由于这种抑制作用，每条染色体在细胞周期中只复制一次，保证了合适的分配到 子细胞中的染色体数。 有丝分裂 Cdk 复合物是在 S 期和 G2 期合成的，但是它们的活性一直受到抑制直到 DNA 合 成完毕。一旦被激活，有丝分裂 Cdk 复合物就会诱导染色体凝聚、核膜解体、有丝分裂器 的装配以及凝聚的染色体在中期赤道板上排列。在所有凝聚的染色体都与适当的纺锤体微管 结合之后，有丝分裂 Cdk 复合物激活后期启动复合物（anaphase promoting complex，APC）。 这种多蛋白的复合物指导后期抑制物通过遍在蛋白介导的蛋白酶解作用进行降解，导致在中 期将姐妹染色单体结合在一起的蛋白复合物失活。因此这些抑制物的降解作用，允许有丝分 裂进入到后期。在后期末，APC 也可指导有丝分裂周期蛋白的蛋白酶体的降解。有丝分裂 Cdk 活性的降低，使得分离的姐妹染色单体去凝聚、核膜重新形成、在胞质分裂中细胞质的 分裂，最后形成子细胞。","kp":"ch09_s3_0","kps":"三类cyclin-CDK(G1/S/M);三个关键过渡(G1→S、中→后、后→末);Cdc34/APC降解不可逆"},{"id":"ch13_calc_5","modI":4,"q":"简述 p34 ／cyclin B 蛋白激酶的发现过程。 cdc2","a":"p34cdc2／cyclin B 蛋白激酶的发现过程如下： （1）1970 年，R．T．Johnson 和 P．N．Rao 发现将 M 期细胞与其他间期细胞融合，可诱 导间期细胞染色质提前凝集成染色体，提示在 M 期细胞内可能存在一种诱导染色体凝缩的 因子，即细胞有丝分裂促进因子（MPF）； （2）1971 年，Y．Masui 和 C．L．Markert 用非洲爪蟾卵做实验，明确提出了 MPF 这一概 念； （3）1988 年，Lohka 等人从非洲爪蟾卵中分离出了微克级纯化的 MPF，证明其含 p32 和 p45 两种蛋白质，表现出蛋白激酶活性； （4）L．Hartwell 等获得了数十个芽殖酵母温度敏感型突变株，发现在限定温度下失去正常 分裂繁殖能力的现象是由于基因发生突变而引起的； （5）Paul Nurse 以裂殖酵母为材料发现，cdc2 基因突变导致细胞停留在 G2／M 期的交界处。 cdc2 基因的表达产物分子量为 34kDa，与其他蛋白质结合后具有激酶活性，能为 MPF 的 p32 抗体识别，能增强 MPF 活性，表明其为 p32 的同源物； （6）1983 年，Tim Hunt 首次发现海胆卵受精后，在其卵裂过程中两种蛋白质的含量随细胞 周期剧烈变化，分别命名为 cyclin A 和 cyclin B。后来证明酵母的 p56cdc13 为 cyclin B 的同源 物。 至此，MPF 蛋白的生化成分被确定了下来，它含有两个亚单位，Cdc2 蛋白为其催化亚单位， 周期蛋白为其调节亚单位。但二者结合后，表现出蛋白激酶活性。","kp":"ch09_s3_4","kps":"发现史:1970 Johnson/Rao融合PCC→MPF;1971 Masui/Markert爪蟾;1988 Lohka纯化;Hartwell芽殖酵母cdc;Nurse裂殖酵母cdc2"},{"id":"ch13_calc_6","modI":4,"q":"细胞周期中有哪些主要检验点，各起何作用？","a":"细胞周期中的主要检验点及其作用如下： （1）G1 期检验点：在 G1 期的晚期阶段，分裂的细胞可以通过一个特定时期进入 S 期，开 始细胞核 DNA 合成，并继续运行直到完成细胞分裂，这个特定时期称为检验点。在酵母中 称为起始点（start），在哺乳动物中称为限制点（R 点）。G1 期检验点的主要事件包括： DNA 是否损伤，细胞外环境是否适宜，细胞体积是否足够大等。防止 DNA 损伤或是突变 的细胞进入 S 期。 （2）S 期检验点：在 S 期内发生 DNA 损伤如 DNA 双链发生断裂时，S 期内部检验点被激 活，从而抑制复制起始点的启动，使 DNA 复制速度减慢，S 期延长，同时激活 DNA 修复 和复制叉的恢复等机制。S 期检验点的主要事件是 DNA 复制是否完成。出行损伤或未完成 则使 DNA 修复或减缓合成速度。 （3）G2 期检验点：细胞能否顺利进入 M 期要受到 G2 期检验点的控制，G2 期检验点的主要 事件包括：DNA 是否损伤，细胞是否已生长到合适大小，环境因素是否利于细胞分裂等。 阻止带有 DNA 损伤的细胞进入 M 期，使得细胞有充足的时间将损伤的 DNA 得以修复。 （4）中-后期检验点（纺锤体组装检验点）：可以阻止染色体分离，直到姐妹染色单体正确 地连接于有丝分裂纺锤体上。纺锤体组装检验点的主要事件包括：监控纺锤体微管与染色单 体动粒的连接，染色体在赤道面的队列和向纺锤体两极的分离等。若这些事件未正确完成， 检验点将阻止细胞从分裂中期进入后期。","kp":"ch09_s2_3","kps":"检验点:G1(R/start)、S、G2、纺锤体装配;作用"},{"id":"ch13_calc_7","modI":5,"q":"举例说明 CDK 在细胞周期中是如何执行调节功能的。","a":"以 CDK1 激酶在细胞周期中的调控为例进行说明。 （1）CDKl 激酶即 MPF，或 p34cdc2 激酶，由 p34cdc2 蛋白和周期蛋白 B 结合而成。p34cdc2 蛋 白在细胞周期中的含量相对稳定，而周期蛋白 B 的含量则呈现出周期性变化。周期蛋白 B 一般在 G1 晚期开始合成，通过 S 期，其含量不断增加，达到 G2 期，含量达到最大值。当 p34cdc2 蛋白与周期蛋白 B 结合后，表现出激酶活性。到 G2 晚期阶段，CDK1 活性达到最大 值并一直维持到 M 期的中期阶段。 （2）CDK1 激酶活性受到很多因素的综合调节。周期蛋白与 CDK1 结合是 CDK1 激酶活性 表现的前提条件。但是，周期蛋白与 CDK1 结合是 CDK1 活化的必要不充分条件，还需要 wee1／mik1 激酶和 CDK1 活化激酶催化 CDK1 的 Thr14、Tyr15、Thr161 磷酸化，然后， CDK1 在磷酸酶 Cdc25C 的催化下，其 Thr14 和 Tyr15 去磷酸化，最终表现出激酶活性。 （3）CDK1 激酶通过使某些蛋白磷酸化，改变其下游的某些蛋白质的构象从而启动其功能， 实现其调控细胞周期的目的。比如，组蛋白 H1 磷酸化，促进染色体凝集；核纤层蛋白磷酸 化，促进核纤层解聚；核仁蛋白磷酸化，促进核仁解体；p60c-Src 蛋白磷酸化，促进细胞骨架 重排；C-abl 蛋白磷酸化，促进调整细胞形态等。 （4）活化的 CDK1 促使分裂期细胞在分裂前期执行下列生化事件： ①染色质开始浓缩形成有丝分裂染色体； ②细胞骨架解聚，有丝分裂纺锤体开始装配； ③高尔基复合体、内质网等细胞器解体，形成小的膜泡。 （5）在有丝分裂的后期，活化的后期促进因子 APC 主要介导两类蛋白质降解：后期抑制因 子和有丝分裂周期蛋白。前者维持姐妹染色单体粘连，抑制后期启动；后者的降解意味着 CDK1 失去活性，有丝分裂即将结束，即染色体开始去凝集，核膜重建。","kp":"ch09_s6_3","kps":"CDK1/cyclinB;周期蛋白周期性;磷酸化/去磷酸化调节(wee1/mik1、CAK、Cdc25)"},{"id":"ch13_calc_8","modI":5,"q":"说明癌症的发生与癌基因和抑癌基因的关系。为什么抑癌基因突变在细胞水平上是隐性 的，却表现为典型的显性孟德尔遗传？","a":"（1）癌症的发生与癌基因和抑癌基因的关系 癌症主要是由携带遗传信息的 DNA 的病理变化而引起的疾病，涉及多个基因位点的突变。 最常发生异常变化的两类基因是： ①癌基因：编码的产物与细胞的肿瘤性转化有关。它以显性的方式作用，对细胞生长起阳性 作用，并促进细胞转化。 ②抑癌基因：抑癌基因，又称肿瘤抑制基因或抗癌基因，正常时起抑制细胞增殖和肿瘤发生 的作用。 细胞的生长是推动细胞周期进行的基因产物与抑制其进行的基因产物之间微妙平衡的结果。 任何一种产物的异常，如一种癌基因的过度表达，或一种抑癌基因的失活，都可能导致细胞 生长的失控。细胞的癌变归根结底由癌基因和抑癌基因的突变或异常表达引起，破坏了正常 的细胞增殖的调控机制，形成具有无限分裂潜能的肿瘤细胞。 （2）抑癌基因突变在细胞水平上是隐性的，却表现为典型的显性孟德尔遗传的原因 ①抑癌基因有两个拷贝，其中一个拷贝正常，可保证正常的调控作用，一对等位基因的两个 拷贝都丢失或失活，才能引起细胞增殖的失控。 ②在细胞分裂过程中，如果出现纺锤体结构的缺陷，导致染色体的错误分离，或带有野生型 和突变型的染色体之间发生重组，就可能形成抑癌基因的两个拷贝都发生突变的细胞。等位 基因都发生突变很少发生在单个细胞中，在大量的有丝分裂进行过程中却必然会发生。一旦 产生两个拷贝的抑癌基因均失活的细胞，该细胞的分裂就会加速，基因突变也随之增加，从 而产生大量携带突变的后代。突变的累积，最终导致细胞癌变。例如家族性成视网膜细胞瘤 儿童患者从亲代获得一个有缺陷的 Rb 基因（一个拷贝是正常，另一个是异常的），只有当 正常的 Rb 基因拷贝通过自发突变才会形成成视网膜细胞瘤。","kp":"ch13_s5_7","kps":"癌基因(显性、促转化)与抑癌基因(隐性、抑制);两拷贝;显性孟德尔遗传的解释"},{"id":"ch13_calc_y2","modI":4,"q":"说明CDK1-cyclinB（MPF）的活化机制及其在G2/M转换和染色体凝集中的作用。","a":"①MPF由CDK1和cyclinB组成；cyclinB在G2期积累到高峰。②CDK1活化需cyclinB结合及CAK对Thr161的磷酸化，同时wee1/mik1对Thr14、Tyr15的磷酸化使其保持抑制态；Cdc25去除Thr14/Tyr15磷酸后MPF被激活。③活化的MPF磷酸化多种底物：磷酸化组蛋白H1促进染色体凝集；磷酸化核纤层蛋白使核纤层解聚、核膜崩解；作用于微管蛋白调控纺锤体装配。④这些事件共同驱动细胞由G2期进入M期。⑤M期后期cyclinB经泛素-蛋白酶体降解，MPF失活，细胞退出M期。","kps":"CDK1+cyclinB;CAK磷酸化Thr161;wee1/mik1抑制;Cdc25激活;底物H1/核纤层/微管;驱动G2→M;cyclinB降解失活","type":"机制型","kp":"ch09_s6_3"},{"id":"ch13_calc_y3","modI":5,"q":"设计实验验证某基因的抑癌功能。","a":"思路：通过功能缺失与获得检测该基因对增殖和成瘤的影响。①功能缺失：在正常细胞中用CRISPR/RNAi敲除或敲低该基因，检测细胞增殖（生长曲线、克隆形成）、接触抑制是否丧失、是否能在软琼脂中生长。②功能获得：在肿瘤细胞中重新表达该基因，检测增殖是否受抑、是否诱导凋亡或衰老。③体内实验：将敲除细胞接种裸鼠，观察是否成瘤；或将回补细胞接种，观察成瘤能力是否下降。④对照：野生型细胞、空载体对照。预期：敲除后增殖加快、失去接触抑制并可成瘤；回补后成瘤能力下降，说明该基因为抑癌基因。","kps":"敲除/敲低测增殖与接触抑制;软琼脂;回补肿瘤细胞;裸鼠成瘤;对照;预期敲除促瘤、回补抑瘤","type":"实验设计型","kp":"ch13_s4_0"}],"appcards":[{"front":"简述 CDK1（MPF）激酶的活化过程。","back":"CDK1 激酶活化的过程如下： （1）首先调节亚基周期蛋白 B 或 A 必须与 CDK1 结合。 （2）weel／mikl 激酶使的 CDK1 的 Thr14 和 Tyr15 磷酸化，CAK（CDK1-activating kinase） 催化 Thr161 的磷酸化。 （3）磷酸酶 Cdc25c 催化 Thr14 和 Tyr15 去磷酸化。 （4）CDK1 表现出蛋白激酶活性，调控细胞周期的进程。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"MPF（M 期或成熟促进因子）是如何通过实验发现的？","back":"MPF 是通过一下几个实验的发现的： （1）将 Hela 细胞同步于细胞周期的不同阶段然后和 M 期细胞混合，细胞融合后发现间期 细胞产生形态各异的染色质凝集现象。 （2）用孕酮处理未成熟的卵母细胞令其成熟，将其胞质注射到另一个未成熟卵母细胞中， 结果导致后者发生减数分裂，此成熟卵母细胞胞质可继续依上法诱导另一个受体卵母细胞成 熟。 （3）在有蛋白质合成抑制剂的条件下，孕酮不能诱导未成熟的卵母细胞成熟，而成熟卵母 细胞胞质可以诱导其成熟。 上述实验提示在 M 期细胞中可能存在一种诱导染色质凝集、诱导卵母细胞成熟的因子，命 名为促成熟因子（MPF），随后 MPF 被纯化，并证明含有 p32 和 p45 两种蛋白。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"细胞周期调控系统的主要作用是什么？","back":"（1）在适当时候激活细胞周期各个时相的相关酶和蛋白，然后自身失活（正调控）； （2）确保每一时相事件的全部完成（负调控）；（3）对外界环境因子起反应（如多细胞生 物对增殖信号的反应）。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"细胞周期调控的分子机制如何？","back":"细胞周期控制系统中有两类关键的蛋白家族：一类是周期蛋白依赖性的蛋白激酶 （cyclin-dependent protein kinase，Cdk）。它能使特定蛋白质的丝氨酸和苏氨酸残基磷酸化 引发细胞周期事件；第二类是周期蛋白（cyclin）。它能够同 Cdk 结合，并控制 Cdk 使适当 蛋白磷酸化的能力。周期蛋白同 Cdk 蛋白复合物的装配和去装配，决定着细胞周期的进程。 有两类主要的周期蛋白：一类是有丝分裂周期蛋白。它是在 G2 期以及将要进入有丝分裂期 时同 Cdk 蛋白分子结合；另一类是 Gl 周期蛋白。它是在 G1 期以及将要进入 S 期时同 Cdk 分子结合。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"将 G1 期细胞与 S 期细胞融合，观察融合后细胞核的变化。试描述现象并对此进行解释。","back":"G-期细胞融合后其核内染色质变得较伸展，DNA 开始复制。这是因为 S 期细胞内的蛋 白质因子启动了 G1 期细胞内的 DNA 复制。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"海胆的细胞周期蛋白 B 是如何鉴定到的？","back":"实验中将同步化的受精的海胆卵细胞培养在有放射性氨基酸的培养液中，每 10 min 取 样一次分离纯化蛋白质，然后通过凝胶电泳、放射自显影进行蛋白质分析。结果发现，经过 几轮细胞周期之后，放射性标记的蛋白质的量稳定增加。其中有一种蛋白峰在有丝分裂的早 期特别高，但是到了有丝分裂后期就急剧下降，然后在下一个细胞周期又慢慢积累直到有丝 分裂前达到高峰，这种蛋白质后来被命名为细胞周期蛋白 B（cyclin B）。科学家用基因工 程技术从海胆中分离了细胞周期蛋白 B 的 cDNA 克隆，然后用这种 cDNA 作探针从非洲爪 蟾中分离了同源的细胞周期蛋白 B 的 cDNA 克隆，最后用周期蛋白 B 制备的抗体证明了非 洲爪蟾中的 MPF 的一个亚基的确是细胞周期蛋白 B。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"试述真核生物 G2／M 转换的机制。","back":"真核生物 G2／M 的转换实际上就是 MPF 的完全激活。P34cdc2 与周期蛋白 B 结合，形成 的是无活性的 MPF。然后在激酶 weel 和 mikl 的作用下，将 P34cdc2 的 Tyr15 和 Thr167 磷酸 化，形成的是无活性的前 MPF，然后在 Cdc25 磷酸酶的作用下，将 Tyr15 位的磷酸脱去， 形成活性 MPF，使一系列的底物发生磷酸化，进入 M 期。由此看来，Tyr15 位的磷酸化起 抑制作用，Thr167 磷酸化起激活作用。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"关卡（checkpoint）位于细胞周期的哪些阶段?每次“检查”什么？","back":"控制系统至少有三个关卡，G1 关卡（靠近 G1 末期）、G2 关卡（靠近 G2 末期）、中期 关卡（中期末）。每一个关卡处，由细胞所处的状态与环境决定细胞能否通过此关卡，进入 下一阶段。 （1）G1 关卡（限制点）检测细胞大小和环境，如果条件合适就会激发 DNA 复制，使控制 系统向前移动。（2）G2 关卡处，控制系统检测细胞大小、状态，以及 DNA 复制是否完毕。 （3）在中期关卡，控制系统检测所有染色体是否都与纺锤体相连并排列于赤道板上，检测 MPF 是否失活，否则不能进行有丝分裂和胞质分裂。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"何为癌细胞？癌细胞的基本生物学特征包括哪些？","back":"癌细胞是指由于基因突变，正常细胞的生长分化失控，脱离了衰老和死亡的正常途径， 而具有无限增殖特性的细胞。其基本特征有： （1）细胞生长与分裂失去控制，具有无限增殖能力，成为“永生”细胞； （2）具有侵润性和扩散性； （3）细胞间相互作用改变； （4）mRNA 表达谱系及蛋白表达谱系或蛋白活性改变； （5）染色体非整倍性。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"为什么抑癌基因是隐性基因，而癌基因表现为显性基因作用？","back":"如果抑癌基因的一个等位基因发生突变，该突变基因的产物就不能正常发挥功能；肿瘤 的形成是由于完全缺乏了功能正常的肿瘤抑制蛋白，由于另一个未突变的抑癌基因的等位基 因的产物能够充当其在细胞周期调控中的角色，细胞不会癌变，因此抑癌基因的突变表现为 隐性。对于癌基因来说，不正常的蛋白质产物足以致癌，因为这种基因产物的作用是刺激细 胞生长分裂，而不是进行负调控。即使存在功能正常的原癌基因产物（由另一未突变的等位 基因编码），细胞也会出现恶变，因此癌基因的作用是显性的。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"良性和恶性肿瘤的主要异同是什么？","back":"都由于细胞生长失控而造成，但良性肿瘤缺乏在体内转移的能力，所以可通过手术根除； 而转移性的恶性肿瘤的细胞可脱离原来的位置，侵入邻近的组织或更远的位置，并在新的位 点迅速生长。恶性肿瘤常由良性肿瘤转化而来。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"P53 蛋白含有哪些功能结构域?哪些在肿瘤细胞中发生了突变？","back":"P53 包括一个转录激活结构域，一个识别特异的由 10 个碱基对组成的回文序列的 DNA 结合结构域，一个寡聚体化结构域，和一个结合非特异性损伤 DNA（单链）的 C 端结构域。 大部分的致癌突变位于位点特异性 DNA 结合结构域中。 ②基因扩增。某些造血系统恶性肿瘤（如前髓细胞性白血病）中，c-myc 扩增 8～32 倍。 ③DNA 重排。染色体的易位使原癌基因处于活跃转录基因强启动子的下游，将产生过度表 达。如 Burkitt 淋巴瘤细胞的染色体易位，使 c-myc 与 IG 重链基因的调控区为邻。 ④插入激活。某些不含 v-onc 的弱转化逆转录病毒具有冗长末端重复序列（LTR），含有启 动子、增强子，插入基因组后引起下游基因过表达。","mod":4,"modName":"2.3.1 肿瘤抑制基因(Tumor suppressor gene)","points":""},{"front":"为什么说 CDK 在细胞周期调控中具有重要作用？如何调控？","back":"参见 14.2 课后习题详解中第 3 题。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"请简要叙述肿瘤细胞相对于正常细胞而言，在细胞水平上所特有的基本特征。 相关试题：癌细胞具有哪些不同于正常细胞的特性？","back":"肿瘤细胞相对于正常细胞而言的特征有： （1）细胞生长和分裂失去控制 正常细胞执行其特定的生理功能(如肝细胞和神经细胞)，会有新生细胞的增殖、衰老细胞的 死亡，在动态平衡中维持组织与器官的稳定，这是一种严格受控的过程。癌细胞生长失去控 制，成为永生细胞，核质比例增大，分裂速度加快，破坏了正常组织的结构与功能。 （2）具有浸润性和扩散性 恶性肿瘤细胞（癌细胞）的细胞间黏着性下降，具有浸润性和扩散性，易于浸润周围健康组 织，或通过血液循环或淋巴途径转移并在其他部位黏着和增殖。此外，癌细胞在分化程度上 低于正常细胞和良性肿瘤细胞，失去了原组织细胞的某些结构和功能。 （3）细胞间相互作用改变 癌细胞冲破了细胞识别作用的束缚，在转移过程中，除了会产生水解酶类（如用于水解基底 膜成分的酶类），而且要异常表达某些膜蛋白，以便与别处细胞黏着和继续增殖，并借此逃 避免疫系统的监视，防止天然杀伤细胞等的识别和攻击。 （4）表达谱改变或蛋白活性改变 对癌细胞与正常细胞中基因表达谱进行检测比较，不同的转录片段仅占整个基因表达谱中很 少一部分；蛋白质表达谱系中，常出现一些在胚胎细胞中所表达的蛋白质，还异常表达与其 恶性增殖、扩散等过程相关的蛋白质组分。由于癌细胞基因突变位点不同，表型不稳定，决 定了癌细胞异质性的特征。 （5）体外培养的恶性转化细胞的特征 应用人工诱导技术培养出恶性转化细胞，同癌细胞一样具有无限增殖的潜能，在体外培养时 贴壁性下降，可不依附在培养器皿壁上生长，有些还可进行悬浮式培养；失去运动和分裂的 接触抑制，在软琼脂培养基中可形成细胞克隆。当将恶性转化细胞注入易感染动物体内时， 往往会形成肿瘤。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"为什么说肿瘤既是一种基因性疾病，又是一种细胞性疾病？","back":"（1）肿瘤是一种基因性疾病的原因 肿瘤的发生是基因突变逐渐累积的结果。在分子层面上，肿瘤细胞的基因已经不同于正常细 胞的基因，肿瘤是发生一系列基因突变的累积结果，因此认为它是一种基因性疾病。 （2）肿瘤是一种细胞性疾病的原因 在细胞层面上，肿瘤细胞发生了很多异常变化。 ①细胞之间的黏着性降低，具有浸润性和转移性； ②细胞生长与分裂失去控制； ③体外培养的恶性转化细胞：具有无限增殖的潜能，贴壁性下降，有些可进行悬浮式培养； 失去运动和分裂的接触抑制，在软琼脂培养基中可形成细胞克隆。 因此从这个层面上讲，肿瘤又是一种细胞性疾病。","mod":2,"modName":"2.2 病毒","points":""},{"front":"什么是原癌基因？为什么突变后会导致细胞癌变？","back":"（1）原癌基因的定义 原癌基因又称细胞癌基因，是指在正常细胞基因组中对细胞正常生命活动起主要调控作用的 基因，在发生突变或被异常激活后变成具有致癌能力的癌基因。 （2）原癌基因突变后导致细胞致癌的原因 ①原癌基因的编码区发生突变，改变了原有的基因结构，致使编码产物的性质发生变化，使 其不再具有正常的活性。 ②原癌基因的调节区发生突变，从而改变了结构基因表达方式，可能大大增加表达量。 ③通过染色体重排，使不在一起的基因序列同原癌基因排列在一起，可能会合成新的蛋白或 融合蛋白，改变原有基因的自然活性。 上述中任何一种突变，都有可能使细胞失去正常的分裂控制，从而向恶性方向转变即发生癌 变。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"简述发现海胆周期蛋白 B 的实验过程。","back":"发现海胆周期蛋白 B 的实验过程如下： （1）以 Tim Hunt 为代表的科学家以海胆卵为实验材料，对细胞周期进行深入研究。1983 年，他们报道在海胆卵细胞中存在两种特殊蛋白质。这两种蛋白质的含量随细胞周期进程变 化而变化，一般在细胞间期内积累，在细胞分裂期内消失，在下一个细胞周期中又重复这一 消长过程。因此他们将这两种蛋白质命名为周期蛋白（cyclin）。 （2）这些周期蛋白很快被分离和克隆出来，并被证明广泛存在于从酵母到人类等各种真核 生物中。 （3）用柱层析从蛙卵中纯化 MPF 之后，James Maller 和 Tim Hunt 实验室合作，证明周期蛋 白 B 是 MPF 的一种成分。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"简述 MPF 的组成和在 G2∕M 期进程中的作用。","back":"（1）MPF 的组成 MPF 即成熟促进因子，是一种促进细胞成熟和分裂的调控性蛋白激酶。成熟促进因子的生 化成分是两个亚单位，一个是 Cdc2 蛋白，一个是周期蛋白 B。Cdc2 蛋白（p34cdc2）为催化 亚基，周期蛋白为调节亚基，二者结合后，表现出蛋白激酶活性。 （2）MPF 在 G2∕M 期进程中的作用 当 Cdc2 蛋白和周期蛋白结合后，MPF（CDK1）表现出蛋白激酶活性，磷酸化下游的蛋白 质分子，促进细胞周期由 G2 向 M 期转化，从而促进细胞成熟或分裂，Cdc2 蛋白是其催化 亚单位，周期蛋白是其调节亚单位。","mod":2,"modName":"2.2 病毒","points":""},{"front":"简述 p53 基因“基因卫士”的功能。","back":"p53 基因“基因卫士”的功能如下： （1）p53 基因时刻监控着细胞染色体 DNA 的完整性，一旦细胞染色体 DNA 遭到损害，p53 蛋白与基因的 DNA 的相应结合部位结合，起特殊转录因子的作用： ①活化 p21 基因转录，使细胞停滞于 G1 期，抑制解链酶的活性； ②与复制因子 A 相互作用，参与 DNA 的复制与修复，使 DNA 受损的细胞不再分裂，修复 损伤而维持基因组的稳定。 （2）如果修复失败，p53 蛋白即启动程序性死亡（凋亡）过程诱导细胞自杀，使细胞周期 停滞，阻止有癌变倾向的突变细胞的生成，从而达到抑制肿瘤发生的作用。","mod":6,"modName":"3.1 基因治疗：用遗传工程方法使病毒携","points":""},{"front":"Ras 蛋白在信号转导中的作用，谈谈突变 Ras 致癌的可能机制。 相关试题：Ras 蛋白是细胞信号转导途径中的一个重要分子开关。ras 基因突变会导致蛋白 GTP 酶活性丧失，并且会导致正常细胞发生癌变。请解释这一现象。","back":"（1）Ras 蛋白在信号转导中的作用 Ras 蛋白是一种小的 GTP 结合蛋白，具有 GTP 酶活性，位于胞质侧，结合 GTP 时为活化态， 结合 GDP 时失活。Ras 蛋白具有分子开关作用，激活磷酸化级联反应。GAP 增强 Ras 蛋白 的 GTP 酶活性。 （2）突变 Ras 致癌的可能机制 发生突变的 Ras 蛋白能够与 GTP 结合，但不能将其水解成 GDP，从而使自身锁定于活化状 态，导致变性、细胞转化和肿瘤发生。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"概述细胞周期蛋白 B 在分裂后期的降解途径、机理和调控因素。","back":"（1）细胞周期蛋白 B 降解途径 细胞周期蛋白 B（cyclin B）在分裂后期的降解是通过泛素化-蛋白酶体降解途径。蛋白质的 泛素化需要泛素活化酶（E1）、泛素结合酶（E2，又称泛素载体蛋白）和泛素连接酶（E3） 的先后催化来完成，具体过程如下： ①E1 活化泛素分子； ②泛素分子转移至 E2； ③E3 催化形成异肽键； ④靶蛋白（cyclin B）被泛素化； ⑤蛋白酶体识别泛素化靶蛋白、ATP 水解驱动泛素移除、靶蛋白解折叠转入蛋白酶体核心 内被降解。 （2）周期蛋白 B 在分裂后期降解的机理 染色体与纺锤体结合后，Mad2 从动粒上消失，对 Cdc2 的抑制解除，Cdc2 是后期促进复合 物 APC 的正调控因子，因而能激活 APC，APC 是一种泛素化途径中的 E3 连接酶，促进 cyclin B 的降解。泛素化途径通过 E1、E2、E3 三个酶对需要降解的蛋白质打上多泛素链标签，具 有这个标签的蛋白质最终被蛋白酶体水解。 （3）周期蛋白 B 在分裂后期降解的调控因素 cyclin B 的调控因素包括其自身的破坏框和 APC，其自身破坏框氨基酸残基的突变或者 APC 的突变都能使 cyclin B 的降解被阻断。","mod":4,"modName":"2.3.1 肿瘤抑制基因(Tumor suppressor gene)","points":""},{"front":"影响细胞增殖周期的因素有哪些？细胞增殖周期与许多医学问题密切相关，举例说明。","back":"（1）影响细胞增殖周期的因素 ①环境中控制细胞增殖的因素，特别是各种生长因子。不少生长因子受体具有蛋白激酶活性， 在生长调节中通过对各种靶蛋白磷酸化实现其对细胞增殖的调节作用； ②生长因子受体的传感机制，最终引起细胞内有关增殖基因的表达，调控细胞增殖； ③某些基因及其产物与细胞增殖调控的关系，其中包括癌基因、细胞分裂周期基因等。 （2）细胞增殖周期与医学问题密切相关的例子 细胞周期检验点功能的减弱，导致突变基因的累积和正常细胞的进化，只有当这些累积的突 变基因，破坏了细胞周期的驱动机制，细胞才进入失控性生长的境界（癌变）。 六、实验题","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"细胞周期运转到分裂中期时，周期蛋白 A 和周期蛋白 B 通过泛素化途径降解。 （1）简述蛋白质的泛素化降解途径； （2）在上述泛素化降解途径中，蛋白降解的特异性（亦即确保只有该降解的蛋白被降解） 是如何实现的？ （3）周期蛋白 A 和 B 的分子结构中含有一段由 9 个氨基酸序列组成的破坏框。请设计一个 实验，证明该破坏框在周期蛋白 A 和 B 的泛素化降解途径中起了重要作用。 （4）如何证明周期蛋白 A 和 B 的存在对于驱动细胞周期从 M 期中期向后期的转化是必须 的？请提出两种不同的实验方案。","back":"（1）蛋白质的泛素化降解途径 泛素依赖性降解途径对于控制蛋白质寿命具有重要作用。蛋白质的泛素化需要泛素活化酶 （E1）、泛素结合酶（E2，又称泛素载体蛋白）和泛素连接酶（E3）的先后催化来完成， 具体过程如下： ①E1 活化泛素分子； ②泛素分子转移至 E2； ③E3 催化形成异肽键； ④靶蛋白被泛素化； ⑤蛋白酶体识别泛素化靶蛋白、ATP 水解驱动泛素移除、靶蛋白解折叠转入蛋白酶体核心 内被降解。 （2）确保只有该降解的蛋白被降解的机制 蛋白降解的特异性是因为降解的蛋白有其特异的 E3。E3 是泛素与底物蛋白特异性结合的决 定者，参与泛素对底物蛋白的识别，是决定泛素依赖的蛋白降解特异性的关键因子。 （3）证明该破坏框在周期蛋白 A 和 B 的泛素化降解途径中起重要作用的实验设计 将周期蛋白 A 和 B 的破坏框突变，引入到细胞中表达，结果显示周期蛋白 A 和 B 不能通过 泛素化途径降解。结论：此破坏框在周期蛋白 A 和 B 的泛素化降解途径中起了重要作用。 （4）证明周期蛋白 A 和 B 的存在对于驱动细胞周期从 M 期中期向后期的转化是必须的实 验方案 ①方案一：采用 siRNA 分别将编码周期蛋白 A、编码周期蛋白 B 的基因突变，使之不能表 达，通过收集培养细胞，观察其细胞周期变化情况。 具体设计三组： a．突变编码周期蛋白 A 基因； b．突变编码周期蛋白 B 基因； c．同时突变编码周期蛋白 A 基因和编码周期蛋白 B 基因。 结果：三组实验的细胞周期均停留在 M 期中期。 结论：周期蛋白 A 和 B 的存在对于驱动细胞周期从 M 期中期向后期的转化是必须的。 ②方案二：采用基因敲除分别将编码周期蛋白 A、编码周期蛋白 B 的基因突变，使之不能 表达，通过收集培养细胞，观察其细胞周期变化情况。实验分组同方案一。 结果：三组实验的细胞周期均停留在 M 期中期。 结论：周期蛋白 A 和 B 的存在对于驱动细胞周期从 M 期中期向后期的转化是必须的。","mod":4,"modName":"2.3.1 肿瘤抑制基因(Tumor suppressor gene)","points":""},{"front":"某实验室从酵母中克隆了一基因，并发现它的蛋白质产物与细胞周期的调控有关。为了 研究其在人细胞中同源的作用，请设计一套研究方案。","back":"依据前人研究这类基因时采用的方法，特别是 MPF 发现时各位科学家之间的合作研究 方法，进行相关试验设计。 （1）方法一 ①酵母基因的人源细胞表达及其表型的鉴定 将该基因构建到一个可以在人源细胞中表达的质粒载体中，然后用此质粒转染人源细胞，让 该基因在人源细胞中高表达，观察人细胞表型和一系列生化特征的的变化（表型变化如细胞 是否还可进行正常的细胞分裂，若不能则发生了哪些其他方面的形态变化等。生化特征如细 胞内调控周期循环的各种 CDK 和 cyclin 的变化，可以采用 western blot 技术进行检验）。 ②寻找人源细胞中的同源基因和同源蛋白 a．采用免疫动物法或者杂交瘤细胞制备方法制备抗体。 b．利用免疫共沉淀的方法，将抗体与人细胞裂解液孵育，得到相应的候选蛋白。对这些候 选蛋白进行鉴定，包括氨基酸序列和编码其的 mRNA、DNA 等序列，找到人细胞中的同种 基因。 （2）方法二 ①利用 BLAST 进行 BLASTx，进行简单的同源性分析，找到与其同源性较高的人类基因； ②将找出的人类同源基因进行克隆，并进行蛋白诱导表达； ③研究检测其蛋白功能。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"现有一种新筛选出的抗肿瘤新药 A，给你一瓶肿瘤细胞，你怎样在细胞水平验证该新药 A 的药效？请你设计一个实验，包括实验方法、实验材料、实验仪器、实验过程，及对预期 的实验结果的分析等。","back":"（1）实验方法 由于抗肿瘤药物的作用是引起肿瘤细胞的凋亡，用新药 A 对人肿瘤细胞进行处理后，利用 细胞凋亡过程中会被特异性切割，形成大小差别为 200bp 左右片段的特点，通过琼脂糖凝胶 电泳检测其有无特征的核小体断裂形成的梯状条带来鉴定新药 A 的功效。 （2）实验材料 人肿瘤细胞。 （3）实验仪器 水平电泳仪、凝胶成像系统等。 （4）实验过程 ①将人肿瘤细胞放入合适培养基培养； ②将新药 A 加入培养基中； ③一段时间后从培养基中收集细胞，利用 SDS∕酚法提取细胞基因组 DNA； ④将提取到的 DNA 进行琼脂糖凝胶电泳； ⑤取电泳完的琼脂糖凝胶用 EB 进行染色，15min 后取出冲洗，在紫外下，利用凝胶成像系 统观察 DNA 电泳情况； ⑥观察实验结果并分析。 （5）预期实验结果及分析 ①若基因组 DNA 出现典型的相隔 200bp 的梯状条带，则说明新药 A 有抗肿瘤功效； ②若基因组 DNA 无典型的相隔 200bp 的梯状条带呈现，则说明新药 A 无抗肿瘤功效。","mod":7,"modName":"3.2 抑制新的血管发生","points":""},{"front":"为什么说肿瘤的发生是基因突变逐渐积累的结果？","back":"之所以说肿瘤的发生是基因突变逐渐积累的结果，原因如下： （1）癌细胞是一种变异的细胞，是产生癌症的病源，癌细胞与正常细胞不同，有无限生长、 转化和转移三大特点，难以消灭。 （2）癌症的发生一般并不是单一基因的突变，至少在一个细胞中发生 5～6 个基因突变，才 能赋予癌细胞所有的特征。 （3）与肿瘤发生相关的某一原癌基因的突变，并非马上形成癌，而是继续生长直至细胞群 体中新的偶发突变的产生。 （4）肿瘤的发生是一系列的原癌基因与抑癌基因的致癌突变的积累。 ①原癌基因的两个拷贝中只要一个基因发生突变，就会引起细胞增殖的失控。 ②抑癌基因有两个拷贝，其中一个拷贝正常，可保证正常的调控作用，两个拷贝都丢失或失 活，才能引起细胞增殖的失控。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"什么是肿瘤干细胞？","back":"肿瘤干细胞是一群存在于某些肿瘤组织中的干细胞样细胞，具有自我更新、无限增殖、 转移和抗化学毒物损伤的能力。目前认为肿瘤干细胞的存在是导致肿瘤化疗失败的主要原因。 与一般的肿瘤细胞相比，肿瘤干细胞具有以下特性： （1）高致瘤性 很少量的肿瘤干细胞在体外培养，就能生成集落；将很少量的肿瘤干细胞注入实验动物体内， 即可形成肿瘤。 （2）强耐药性 多数肿瘤干细胞的细胞膜上表达 ATP 结合盒（ABC）家族膜转运蛋白，可运输并外排代谢 产物、药物、毒性物质、内源性脂质、多肽、核苷酸及固醇类等多种物质，使之对许多化疗 药物产生耐药性。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"为什么说蛋白质磷酸化-去磷酸化和泛素介导的蛋白质水解（UPP）的互相协调推动细胞 周期的运转？","back":"之所以说蛋白质磷酸化-去磷酸化和泛素介导的蛋白质水解（UPP）的互相协调推动细 胞周期的运转，是因为： （1）对细胞起核心作用的是 CDK 激酶，通过不同的周期蛋白与不同种类的 CDK 结合，在 细胞周期的不同周期表现出活性，因而对细胞周期的不同时期进行调节。 （2）CDK 激酶主要通过磷酸化与细胞周期进程相关的蛋白质，使它们在适当的时期表现出 相应的功能，促进细胞周期的运转，比如在 G2 向 M 期过渡的时候，MPF 被激活后，它可 以使组蛋白 H1 磷酸化，促进染色体凝集，使核纤层蛋白磷酸化，促使核纤层解聚，还可以 作用于微管蛋白，控制细胞周期中微管的动力学变化等，这些促使细胞由间期进入分裂期。 （3）去磷酸化在细胞周期中也起到很重要的作用，比如，CDK1 在非活性状态下其 Thr14 和 Tyr15 是磷酸化的，只有在 Cdc25 的作用下，使 Thr14 和 Tyr15 去磷酸化后才能表现出激 酶活性，从而调控细胞周期。再如，细胞运转到分裂中期后，被 MPF 磷酸化的蛋白去磷酸 化，细胞周期便从 M 期中期向后期转化。 （4）CDK 激酶被激活，其首先要与周期蛋白结合，而周期蛋白的浓度是随着细胞周期进程 的变化而变化的，从而使 CDK 激酶在特定时期表现活性，使得细胞周期正常运转，而周期 蛋白的周期性降解是通过泛素介导的蛋白质水解系统（UPPS）介导的。 综上所述，正是通过对蛋白质的磷酸化-去磷酸化和泛素介导的蛋白质水解系统对蛋白质的 降解，调控细胞周期中诸多蛋白的功能，并使其在正确的时间上执行功能，保证细胞周期的 正常运转。","mod":4,"modName":"2.3.1 肿瘤抑制基因(Tumor suppressor gene)","points":""},{"front":"试述有丝分裂促进因子 MPF 在细胞周期中所起的作用，常用的研究细胞周期的方法有哪 些？","back":"（1）细胞周期中，M 期占用的时间最短，但细胞的形态变化最大。此阶段细胞的主要 生化特点是：RNA 合成停止，蛋白质合成减少，染色体高度螺旋化。由 G 期进入 M 期是细 胞周期中的另一个关键时期，M 期细胞质中存在一种染色质浓缩物质，即 M 期促进因子 MPF。如果将 M 期细胞与 G1、G2 或 S 期细胞融合，不论这些细胞中原来染色体状态如何， 都能使其浓缩。 （2）细胞周期常用研究方法：①细胞同步化法。可使处于不同细胞周期的细胞共同进入某 一特定阶段，即细胞同步化，有利于对细胞周期调控的研究。可分为物理法和化学法。物理 法有温度法、辐射法以及有丝分裂抖落法。化学法有 DNA 合成阻断法和细胞中期阻断法。 ②细胞周期调控研究法：免疫组化法、显微注射法、细胞融合法等。③3H-TdR 掺入法。利 用 3H-TdR 掺入法将同位素标记的 DNA 合成前体 TdR 掺入到 DNA 分子中．    可以对 S 期 DNA 合成动态过程加以研究，同时可以用于细胞周期的时间测定。","mod":4,"modName":"2.3.1 肿瘤抑制基因(Tumor suppressor gene)","points":""},{"front":"试述调控细胞周期的因素及分选机制。","back":"细胞增殖是一个多阶段，多因子参与的高低精确有序的活动过程，而这个过程是由不同 基因严格按照时间顺序表达的结果，也是基因与环境因素相互作用的结果。细胞周期的调控 严格有序、极其复杂的过程，涉及多个因子在多个层次上的作用，这些因子通常在细胞周期 某个特定时期（调控点）起作用。 （1）细胞周期蛋白（cyclin）家族和细胞周期蛋白依赖激酶：cyclin 家族有 cyclinA、B、C、 D、E、F、G、 H 等。CdK 家族有 CdKl、CdK2、CdK3、CdK4、CdK5 等。CdK 与 cyclin 结合形成的复合物可参与磷酸化多种蛋白质，这些磷酸化蛋白在细胞周期中对 DNA 复制和 有丝分裂事件起重要调节作用。 （2）促成熟因子（MPF）是一种在 G2 期合成能促进 M 期启动的调控因子。 （3）生长因子是一类与细胞膜上特异受体结合以调节细胞周期的多肽类物质，可来自细胞 的自分泌或旁分泌。这些因子与其他受体结合后，通过信号传导途径，激活细胞内多种蛋白 激酶，最终引起与细胞周期相关的蛋白质表达的改变进而调节细胞周期。 （4）抑素是一类细胞自身产生的对细胞周期过程有抑制作用的糖蛋白。 （5）RNA 剪接因子 SR 蛋白及 SR 蛋白的特异性激酶。 （6）癌基因与抑癌基因：在一些逆转录病毒的基因组中，存在一些 DNA 序列，可促进细 胞无限增殖而癌变，这些序列被称为病毒癌基因；许多细胞癌基因可编码一些生长因子受体。 通过与生长因子结合参与细胞周期的调控或者癌基因产物直接参与细胞内信号传导进而参 与细胞周期的调控；抑癌基因：正常细胞内，一类能抑制细胞恶性增殖的基因，称为抑癌基 因，如 Rb 基因、p53 基因等。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"真核细胞周期调控模型的主要特点和机制是什么？","back":"特点表现在三类周期蛋白-Cdk 复合物和三个关键的过渡和对细胞周期的控制。 真核细胞主要通过三类周期蛋白-Cdk 复合物的作用，控制细胞周期，这三种复合物分别是： G1 期、S 期和有丝分裂 Cdk 复合物。这些复合物都是由周期蛋白依赖性的蛋白激酶和周期 蛋白两个亚基组成的复合物。在 Cdc34 途径和 APC 途径中，蛋白复合物都是通过遍在蛋白 的蛋白酶体将一些特殊的底物，包括 S 期抑制物、后期抑制物、以及有丝分裂周期蛋白降 解进行周期调节。 细胞周期中三个关键的过渡，即 G1 期→S 期、中期→后期、后期→末期及胞质分裂期的过 渡。这些过渡都是通过触发蛋白质的降解进行的，所以都是不可逆转的，这样迫使细胞周期 只能沿一个方向进行。 三个过渡分别是通过 Cdc34 和 APC 途径的降解作用完成的。Cdc34 途径促使细胞从 G1→S 期过渡：在 G1 期的早、中期，在 DNA 的复制起点就装配了复制起始复合物，并且开始了 S 期的 CdkC 组份的转录；但是，S 期 CdkC 抑制物被 G1CdkC 磷酸化而激活，激活的 S 期 CdkC 抑制物抑制了 S 期 CdkC 的活性，从而使细胞停留在 G1 期。在 G1 期的后期，Cdc34 诱导 S 期 Cdk 抑制物的降解，释放出有活性的 s 期 Cdk 复合物，这种复合物能够激发细胞进入 S 期。 一旦 S 期 Cdk 的降解作用被激活，S-期 Cdk 复合物将与 DNA 形成预复制复合物中的蛋白质 的调节位点磷酸化，预复制起始复合物是 G1 期在 DNA 复制起点上装配的复合物。这些被 S 一期 Cdk 复合物磷酸化的蛋白质不仅能够激活 DNA 复制起始，还能够阻止新的预复制复合 物的装配。由于这种抑制作用，每条染色体在细胞周期中只复制一次，保证了合适的分配到 子细胞中的染色体数。 有丝分裂 Cdk 复合物是在 S 期和 G2 期合成的，但是它们的活性一直受到抑制直到 DNA 合 成完毕。一旦被激活，有丝分裂 Cdk 复合物就会诱导染色体凝聚、核膜解体、有丝分裂器 的装配以及凝聚的染色体在中期赤道板上排列。在所有凝聚的染色体都与适当的纺锤体微管 结合之后，有丝分裂 Cdk 复合物激活后期启动复合物（anaphase promoting complex，APC）。 这种多蛋白的复合物指导后期抑制物通过遍在蛋白介导的蛋白酶解作用进行降解，导致在中 期将姐妹染色单体结合在一起的蛋白复合物失活。因此这些抑制物的降解作用，允许有丝分 裂进入到后期。在后期末，APC 也可指导有丝分裂周期蛋白的蛋白酶体的降解。有丝分裂 Cdk 活性的降低，使得分离的姐妹染色单体去凝聚、核膜重新形成、在胞质分裂中细胞质的 分裂，最后形成子细胞。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"简述 p34 ／cyclin B 蛋白激酶的发现过程。 cdc2","back":"p34cdc2／cyclin B 蛋白激酶的发现过程如下： （1）1970 年，R．T．Johnson 和 P．N．Rao 发现将 M 期细胞与其他间期细胞融合，可诱 导间期细胞染色质提前凝集成染色体，提示在 M 期细胞内可能存在一种诱导染色体凝缩的 因子，即细胞有丝分裂促进因子（MPF）； （2）1971 年，Y．Masui 和 C．L．Markert 用非洲爪蟾卵做实验，明确提出了 MPF 这一概 念； （3）1988 年，Lohka 等人从非洲爪蟾卵中分离出了微克级纯化的 MPF，证明其含 p32 和 p45 两种蛋白质，表现出蛋白激酶活性； （4）L．Hartwell 等获得了数十个芽殖酵母温度敏感型突变株，发现在限定温度下失去正常 分裂繁殖能力的现象是由于基因发生突变而引起的； （5）Paul Nurse 以裂殖酵母为材料发现，cdc2 基因突变导致细胞停留在 G2／M 期的交界处。 cdc2 基因的表达产物分子量为 34kDa，与其他蛋白质结合后具有激酶活性，能为 MPF 的 p32 抗体识别，能增强 MPF 活性，表明其为 p32 的同源物； （6）1983 年，Tim Hunt 首次发现海胆卵受精后，在其卵裂过程中两种蛋白质的含量随细胞 周期剧烈变化，分别命名为 cyclin A 和 cyclin B。后来证明酵母的 p56cdc13 为 cyclin B 的同源 物。 至此，MPF 蛋白的生化成分被确定了下来，它含有两个亚单位，Cdc2 蛋白为其催化亚单位， 周期蛋白为其调节亚单位。但二者结合后，表现出蛋白激酶活性。","mod":4,"modName":"2.3.1 肿瘤抑制基因(Tumor suppressor gene)","points":""},{"front":"细胞周期中有哪些主要检验点，各起何作用？","back":"细胞周期中的主要检验点及其作用如下： （1）G1 期检验点：在 G1 期的晚期阶段，分裂的细胞可以通过一个特定时期进入 S 期，开 始细胞核 DNA 合成，并继续运行直到完成细胞分裂，这个特定时期称为检验点。在酵母中 称为起始点（start），在哺乳动物中称为限制点（R 点）。G1 期检验点的主要事件包括： DNA 是否损伤，细胞外环境是否适宜，细胞体积是否足够大等。防止 DNA 损伤或是突变 的细胞进入 S 期。 （2）S 期检验点：在 S 期内发生 DNA 损伤如 DNA 双链发生断裂时，S 期内部检验点被激 活，从而抑制复制起始点的启动，使 DNA 复制速度减慢，S 期延长，同时激活 DNA 修复 和复制叉的恢复等机制。S 期检验点的主要事件是 DNA 复制是否完成。出行损伤或未完成 则使 DNA 修复或减缓合成速度。 （3）G2 期检验点：细胞能否顺利进入 M 期要受到 G2 期检验点的控制，G2 期检验点的主要 事件包括：DNA 是否损伤，细胞是否已生长到合适大小，环境因素是否利于细胞分裂等。 阻止带有 DNA 损伤的细胞进入 M 期，使得细胞有充足的时间将损伤的 DNA 得以修复。 （4）中-后期检验点（纺锤体组装检验点）：可以阻止染色体分离，直到姐妹染色单体正确 地连接于有丝分裂纺锤体上。纺锤体组装检验点的主要事件包括：监控纺锤体微管与染色单 体动粒的连接，染色体在赤道面的队列和向纺锤体两极的分离等。若这些事件未正确完成， 检验点将阻止细胞从分裂中期进入后期。","mod":4,"modName":"2.3.1 肿瘤抑制基因(Tumor suppressor gene)","points":""},{"front":"举例说明 CDK 在细胞周期中是如何执行调节功能的。","back":"以 CDK1 激酶在细胞周期中的调控为例进行说明。 （1）CDKl 激酶即 MPF，或 p34cdc2 激酶，由 p34cdc2 蛋白和周期蛋白 B 结合而成。p34cdc2 蛋 白在细胞周期中的含量相对稳定，而周期蛋白 B 的含量则呈现出周期性变化。周期蛋白 B 一般在 G1 晚期开始合成，通过 S 期，其含量不断增加，达到 G2 期，含量达到最大值。当 p34cdc2 蛋白与周期蛋白 B 结合后，表现出激酶活性。到 G2 晚期阶段，CDK1 活性达到最大 值并一直维持到 M 期的中期阶段。 （2）CDK1 激酶活性受到很多因素的综合调节。周期蛋白与 CDK1 结合是 CDK1 激酶活性 表现的前提条件。但是，周期蛋白与 CDK1 结合是 CDK1 活化的必要不充分条件，还需要 wee1／mik1 激酶和 CDK1 活化激酶催化 CDK1 的 Thr14、Tyr15、Thr161 磷酸化，然后， CDK1 在磷酸酶 Cdc25C 的催化下，其 Thr14 和 Tyr15 去磷酸化，最终表现出激酶活性。 （3）CDK1 激酶通过使某些蛋白磷酸化，改变其下游的某些蛋白质的构象从而启动其功能， 实现其调控细胞周期的目的。比如，组蛋白 H1 磷酸化，促进染色体凝集；核纤层蛋白磷酸 化，促进核纤层解聚；核仁蛋白磷酸化，促进核仁解体；p60c-Src 蛋白磷酸化，促进细胞骨架 重排；C-abl 蛋白磷酸化，促进调整细胞形态等。 （4）活化的 CDK1 促使分裂期细胞在分裂前期执行下列生化事件： ①染色质开始浓缩形成有丝分裂染色体； ②细胞骨架解聚，有丝分裂纺锤体开始装配； ③高尔基复合体、内质网等细胞器解体，形成小的膜泡。 （5）在有丝分裂的后期，活化的后期促进因子 APC 主要介导两类蛋白质降解：后期抑制因 子和有丝分裂周期蛋白。前者维持姐妹染色单体粘连，抑制后期启动；后者的降解意味着 CDK1 失去活性，有丝分裂即将结束，即染色体开始去凝集，核膜重建。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""},{"front":"说明癌症的发生与癌基因和抑癌基因的关系。为什么抑癌基因突变在细胞水平上是隐性 的，却表现为典型的显性孟德尔遗传？","back":"（1）癌症的发生与癌基因和抑癌基因的关系 癌症主要是由携带遗传信息的 DNA 的病理变化而引起的疾病，涉及多个基因位点的突变。 最常发生异常变化的两类基因是： ①癌基因：编码的产物与细胞的肿瘤性转化有关。它以显性的方式作用，对细胞生长起阳性 作用，并促进细胞转化。 ②抑癌基因：抑癌基因，又称肿瘤抑制基因或抗癌基因，正常时起抑制细胞增殖和肿瘤发生 的作用。 细胞的生长是推动细胞周期进行的基因产物与抑制其进行的基因产物之间微妙平衡的结果。 任何一种产物的异常，如一种癌基因的过度表达，或一种抑癌基因的失活，都可能导致细胞 生长的失控。细胞的癌变归根结底由癌基因和抑癌基因的突变或异常表达引起，破坏了正常 的细胞增殖的调控机制，形成具有无限分裂潜能的肿瘤细胞。 （2）抑癌基因突变在细胞水平上是隐性的，却表现为典型的显性孟德尔遗传的原因 ①抑癌基因有两个拷贝，其中一个拷贝正常，可保证正常的调控作用，一对等位基因的两个 拷贝都丢失或失活，才能引起细胞增殖的失控。 ②在细胞分裂过程中，如果出现纺锤体结构的缺陷，导致染色体的错误分离，或带有野生型 和突变型的染色体之间发生重组，就可能形成抑癌基因的两个拷贝都发生突变的细胞。等位 基因都发生突变很少发生在单个细胞中，在大量的有丝分裂进行过程中却必然会发生。一旦 产生两个拷贝的抑癌基因均失活的细胞，该细胞的分裂就会加速，基因突变也随之增加，从 而产生大量携带突变的后代。突变的累积，最终导致细胞癌变。例如家族性成视网膜细胞瘤 儿童患者从亲代获得一个有缺陷的 Rb 基因（一个拷贝是正常，另一个是异常的），只有当 正常的 Rb 基因拷贝通过自发突变才会形成成视网膜细胞瘤。","mod":5,"modName":"2.3.2 原癌基因(proto-oncogene)","points":""}],"jyq":[{"id":"jyq_ch13_1","kind":"fill","q":"德国科学家哈拉尔德·楚尔·豪森因发现导致宫颈癌的、法国科学家弗朗索瓦丝·巴尔-西诺西和吕克·蒙塔尼因发现而分享了2008年度的诺贝尔生理学或医学奖。","a":"乳突淋瘤病毒、人类免疫缺陷病毒。","src":"中山大学，2009年","kp":null,"e":"2008年诺贝尔奖：楚尔·豪森发现人乳头瘤病毒（乳突淋瘤病毒）与宫颈癌相关，巴尔-西诺西和蒙塔尼发现人类免疫缺陷病毒（HIV）。","oe":["楚尔·豪森发现人乳头瘤病毒（HPV，即乳突淋瘤病毒）是宫颈癌的致病因子。","巴尔-西诺西和蒙塔尼发现人类免疫缺陷病毒（HIV），即艾滋病的病原体。"]},{"id":"jyq_ch13_2","kind":"short","q":"病毒（virus）","a":"是一类非细胞形态的微生物。主要有以下基本特征：①个体微小，可通除滤菌器，大多数病毒必须用电镜才能看见；②仅具有一种类型的核酸，DNA或RNA，没有一种含两种核酸的病毒；③专营细胞内寄生生活；4具有受体连接蛋白，与敏感细胞表面的病毒受体连接，进而感染细胞。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch13_3","kind":"short","q":"在动物细胞培养过程中，贴壁生长的正常二倍体细胞表面相互接触时分裂随之停止，这种现象称为细胞的。","a":"接触抑制。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch13_4","kind":"short","q":"体外培养动物细胞生长特点是","a":"单层贴壁生长；接触抑制。","src":"山东大学，2006年","kp":null},{"id":"jyq_ch13_5","kind":"mcq","q":"体外培养细胞加血清的主要原因是（）。","o":["A. 血清含有多种营养物质","B. 血清含有多种生长因子","C. 血清含有补体、抗体等免疫活性物质，可以抗污染","D. 作用不明"],"a":"B","src":"南京师范大学，2008年","kp":null,"e":"体外培养加血清主要是因为血清含有多种生长因子，可促进细胞生长增殖。","oe":["A. 血清含有多种营养物质：错误，营养物质主要由培养基提供，非加血清主因。","B. 血清含有多种生长因子：正确，生长因子是血清促进细胞生长的关键成分。","C. 血清含有补体、抗体等免疫活性物质，可以抗污染：错误，这不是加血清的主要目的。","D. 作用不明：错误，血清作用明确，即提供生长因子等成分。"]},{"id":"jyq_ch13_6","kind":"mcq","q":"限制性内切酶是指（）。","o":["A. 切割DNA或RNA的酶","B. 专门切割RNA的酶","C. 专门切割核酸的酶","D. 专门切割DNA特定碱基顺序的酶"],"a":"D","src":"南京师范大学，2008年","kp":null,"e":"限制性内切酶能识别DNA分子中特定的碱基序列并在该位点切割DNA，故选D。它不切割RNA，也不能泛指切割一切核酸的酶。","oe":["限制酶作用于DNA，一般不切割RNA，该说法过于宽泛。","其底物是DNA而非RNA，不能专门切割RNA分子。","限制酶只识别并切割特定DNA序列，并非所有核酸。","正确，它识别DNA特定碱基序列并在该处切割DNA。"]},{"id":"jyq_ch13_7","kind":"short","q":"实验设计：为了研究某种特异蛋白在细胞中的定位，可以借助免疫荧光技术或免疫电镜技术。请比较免疫荧光技术和免疫电镜技术各自的优点与不足？并说明免疫电镜技术详细实验步骤（以辣根过氧化物为标记物）。","a":"①优点与不足：免疫荧光技术：制样简单快捷，灵敏，有特异性，但分辨率不足。免疫电镜技术：分辨率高，可同时观察细胞超微结构和蛋白质定位。但制样步骤复杂，抗原易失活。②免疫电镜技术详细实验步骤：取样一固定一脱水一环氧树脂包埋→超薄切片。特异蛋白的抗体准备一辣根过氧化物标记抗体一超薄切片在孵育液中孵育（孵育液含DAB，酶标记抗体等）→四氧化饿后固定→电子染色一电镜观察。","src":"华中农业大学，2008年","kp":null},{"id":"jyq_ch13_8","kind":"short","q":"为何绿色荧光蛋白的发现者会获得2008年诺贝尔奖？","a":"目前人们对绿色荧光蛋白的认识主要是基于它能够示踪蛋白质，人们基于它与成像技术的结合，能够以高的时间、空间分辨率，记录、分析一些活的生物系统、生命过程中非常微量蛋白质的行为、作用等，而且在无光的情况下也能进行，而过去即使在有光的情况下，也是很难实现的。过去，“生物”学研究常常研究的是“死物”，有了这个GFP示踪后，就可以研究实实在在的活的生命过程，这就好比研究熊猫、海豚等野生动物，为它们戴上不影响生存以及活动的发射信号装置，这将彻底改变医学研究，所以从方法学上来讲，是一个革命，而在过去这也是难以实现的。此外GFP不仅对于细胞生物学和神经生物学影响很大，它在生命科学的每个领域几乎都有很广泛的应用，如分子生物学、肿瘤生物学、免疫学、内分泌学、肝病学等。成果在细胞生物学有关领域研究中有何应用？简述应用的原理与主要步骤。【答案】日本科学家下村修、美国科学家马丁·沙尔菲和美籍华裔科学家钱永健获得2008年的诺贝尔化学奖。这三位科学家因在发现和研究绿色荧光蛋白方面作出贡献而获奖。下村修于1962年在水母中发现了绿色荧光蛋白。沙尔菲在利用绿色荧光蛋白做生物示踪分子方面作出了贡献。华裔科学家钱永健走出的可以说是绿色荧光蛋白开发历程的“最后一步”，在下村修与沙尔菲研究的基础上进一步搞清楚了绿色荧光蛋白特性。他改造绿色荧光蛋白，通过改变其氨基酸排序，造出能吸收、发出不同颜色光的荧光蛋白，其中包括蓝色、青色和黄色，并让它们发光更久、更强烈。绿色荧光蛋白（GFP）是从一种生活在北太平洋寒冷水域的水母体内发现的。这种水母体内含有一种生物发光蛋白质一一aequorin，它本身发蓝光。GFP能把这种光转变成绿色，也就是当水母容光焕发的时候我们实际看到的颜色。GFP的纯溶液在典型的室光下呈黄色，但是当被拿到户外的阳光下时，它会发出鲜绿的颜色。这种蛋白质从阳光中吸收紫外光，然后以能量较低的绿光形式发射出来。CFP在科学研究上有着惊人的用途，因为它能够使我们直接看到细胞内部的运动情况。在任何指定的时间我们都可以轻易地找出GFP在哪儿：只需要用紫外光去照射，这时所有的GFP都将发出鲜艳的绿色。如果把CFP连接到有兴趣观察的任何对象上，比如，可以把它连接到一种病毒上。然后，随着病毒在宿主体内不断扩散，就可以通过跟踪发出的绿光来观察病毒的扩散途径；或者把它接合到一种蛋白质上并通过显微镜观察它在细胞内部的移动。GFP是一种现成的荧光蛋白质，因此它特别容易使用。由于GFP可以形成自己的发色团，它非常适合于基因工程。根本不必担心操作任何奇怪的发色团，只需要利用遗传学的方法操纵细胞合成GFP蛋白质，GFP就会自动折叠并开始发光。GFP的用途已经扩展到艺术和商务领域，艺术家EduardoKac通过把GFP插人免子细胞内创造出了一只荧光的绿色兔子。育种工作者正在探索利用GFP来创造特殊的荧光植物和各种鱼类，CFP已经被移植到大鼠、老鼠、青蛙、有翅昆虫、蠕虫以及不计其数的其他生物体内。当然这些转基因植物和动物还存在一些争议，并且已经引发了关于基因工程安全性和伦理性的重要对话。在研究活细胞方面，CFP也有惊人的作用，并且科学家们正在努力使它变得更有用，科学家正在改进GFP分子以使其发出不同颜色的荧光。科学家们目前可以制造蓝色荧光蛋白、黄色荧光蛋白和大量其他颜色的荧光蛋白质。方法是使发色团产生能改变其稳定性的小的变异。科学家们还利用CFP来发明生理传感器：一种感应离子或酸碱度水平，然后通过发出特征性的荧光来报告结果的分子机器。","src":"中国科学院，2009年","kp":null},{"id":"jyq_ch13_9","kind":"mcq","q":"有关血红素、叶绿素的解释，不正确的是（（）。","o":["A. 都是叶啉化合物","B. 都与蛋白质共价结合","C. 不能被分子态氧所氧化","D. 它们基因有不同碱基序列"],"a":"D","src":"南京师范大学，2008年","kp":null,"e":"血红素和叶绿素都是卟啉类化合物，二者本身并非由基因编码的蛋白质，说“它们基因有不同碱基序列”不正确，故选D。","oe":["正确，血红素与叶绿素的核心都是卟啉环结构。","二者在体内均与相应蛋白质结合成复合物，一般视为正确。","作为辅基性质较稳定，不易被分子态氧所氧化。","错误，血红素、叶绿素均非基因产物，不存在碱基序列。"]},{"id":"jyq_ch13_10","kind":"short","q":"试述高尔基体的结构和功能。","a":"形、半球形或球形，膜周围有大小不等的囊泡。功能：①接受并转运来自内质网的大部分物质；②遣返一些蛋白质和脂质；③是蛋白质0-连接的糖基化的主要场所；④发生跨膜蛋白的酰基化；5是日冕蛋白病毒的装配场所。","src":"华中师范大学，2008年","kp":null},{"id":"jyq_ch13_11","kind":"short","q":"试述溶酶体在细胞中的主要功能。（中国科学院，2008、2009年）","a":"①清除功能：清除无用的生物大分子、衰老的细胞器及衰老损伤和死亡的细胞，保持正常的细胞代谢与调控；②防御功能：识别并吞噬人侵的病毒或细菌，在溶酶体作用下将其杀死并进一步降解；③消化体内物质供应营养，如降解内吞的血清脂蛋白，获得胆固醇等营养成分，在饥饿状态下，溶酶体可分解细胞内的生物大分子保证机体所需的能量；④在分泌腺细胞中，溶酶体常常摄入分泌颗粒，可能参与分泌过程的调节；5受精过程中，精子的顶体相当于特化的溶酶体，其中含多种水解酶类，能溶解卵细胞的外被及滤膜细胞，产生通道，使精子进人卵细胞；6在某些两栖类中参与细胞凋亡；7自噬死亡中的功能。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch13_12","kind":"mcq","q":"反转录酶存在于何种结构中（）。","o":["A. RNA病毒","B. 宿主细胞质","C. 宿主细胞核","D. 宿主细胞染色体"],"a":"A","src":"南京师范大学，2009年","kp":null,"e":"反转录酶由逆转录病毒（属RNA病毒）编码并随病毒颗粒存在，故反转录酶存在于RNA病毒中，选A。","oe":["正确，逆转录酶是RNA病毒（逆转录病毒）携带的酶。","宿主细胞质只是病毒复制的场所，非酶固有部位。","宿主细胞核中并不存在反转录酶。","宿主染色体不含编码反转录酶的基因及其产物。"]},{"id":"jyq_ch13_13","kind":"short","q":"肿瘤细胞（tumorcell）","a":"是动物体内细胞分裂调节失控而无限增殖的细胞。具有转移能力的肿瘤称为恶性肿瘤（malignancy）。上皮组织的恶性肿瘤称癌。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch13_14","kind":"judge","q":"永生细胞和癌细胞的主要共同点就是既没有细胞分裂次数的限制，也没有细胞间的接触抑制。","a":"错","src":"南京师范大学，2008年","kp":null,"e":"永生细胞虽无分裂次数限制，但未必失去接触抑制，失去接触抑制是癌细胞的典型特征，故该说法错误。","oe":["若选对，是把癌细胞的特性强加到永生细胞；永生细胞可仍保留接触抑制。","永生细胞未必丧失接触抑制，丧失接触抑制是癌细胞的特征，故该说法错误。"]},{"id":"jyq_ch13_15","kind":"judge","q":"抑癌基因突变而转变成癌基因。","a":"错","src":"上海交通大学，2007年","kp":null,"e":"抑癌基因突变后功能丧失，并不会转变为癌基因，故该说法错误。","oe":["若选“对”则错误。抑癌基因突变只是使其抑癌功能丧失或减弱，并不会因此变成癌基因。","选“错”正确。癌基因由原癌基因激活而来，抑癌基因突变属功能失活，二者性质不同。"]},{"id":"jyq_ch13_16","kind":"mcq","q":"下列叙述中正确的是（）。","o":["A. 癌基因是原癌基因的突变体","B. 原癌基因是原来存在于反转录病毒中的基因","C. 癌基因可以编码生长因子、生长因子受体，甚至是转录因子第十四章细胞增殖调控与癌细胞","D. 原癌基因是癌基因的抑癌基因"],"a":"A","src":"中国科学院，2003年","kp":null,"e":"原癌基因是正常细胞固有的基因，癌基因是原癌基因突变或异常活化后的形式，故选A。原癌基因并非来自逆转录病毒，也不是抑癌基因。","oe":["正确，癌基因是原癌基因突变或异常活化所形成的。","错误，原癌基因是正常细胞固有基因，非病毒来源基因。","该选项被章节标题文字截断而不完整，不能作为正确项。","错误，原癌基因与抑癌基因是两个完全不同的概念。"]},{"id":"jyq_ch13_17","kind":"mcq","q":"癌细胞的主要特点之一是（）。","o":["A. 细胞间黏附性增强","B. 缺少接触抑制作用","C. 对生长因子的需求量上升","D. 增殖力下降"],"a":"B","src":"军事医学科学院，2006年","kp":null,"e":"癌细胞失去接触抑制，可重叠生长并具有侵袭转移能力，故选B。","oe":["错误，癌细胞细胞间黏附性下降而非增强。","正确，癌细胞缺少接触抑制，可堆积重叠生长。","错误，癌细胞对生长因子需求降低，常自分泌生长因子。","错误，癌细胞增殖能力增强而非下降。"]},{"id":"jyq_ch13_18","kind":"mcq","q":"癌基因活化的机制为（）。","o":["A. 点突变","B. 获得启动子和增强子","C. 基因易位","D. 原癌基因扩散"],"a":"A","src":"中山大学，2005年","kp":null,"e":"原癌基因可由点突变、基因扩增、染色体易位及启动子/增强子插入等途径活化，其中点突变是经典机制，本题选A。","oe":["正确，点突变可使原癌基因产物结构改变而持续活化。","获得启动子和增强子（插入激活）也是活化途径之一。","染色体易位也可导致原癌基因异常激活，同为途径。","错误，原癌基因扩散不是公认的癌基因活化机制。"]},{"id":"jyq_ch13_19","kind":"mcq","q":"下列属于抑癌基因的是（）。","o":["A. ras","B. Rb基因","C. 突变型p53基因","D. 野生型p53基因"],"a":"B","src":"中山大学，2005年","kp":null,"e":"Rb基因是经典的抑癌基因，其失活与视网膜母细胞瘤发生密切相关，故选B。野生型p53同样属于抑癌基因，本题系单选。","oe":["错误，ras是原癌基因（癌基因），不属于抑癌基因。","正确，Rb是最经典的抑癌基因，失活可致肿瘤发生。","错误，突变型p53丧失抑癌功能，具癌基因样作用。","野生型p53也属抑癌基因，本题按单选取更经典的Rb。"]},{"id":"jyq_ch13_20","kind":"mcq","q":"原癌基因的显现突变导致细胞过度增值而形成肿瘤，最有可能的突变是（）。","o":["A. 无义突变","B. 错义突变","C. 移码突变","D. 同义突变"],"a":"B","src":"中国科学院，2006年","kp":null,"e":"错义突变改变蛋白质的氨基酸序列，可使原癌基因产物持续活化而致癌，如ras的点突变，故选B。","oe":["无义突变使肽链提前终止，产物通常失去功能。","正确，错义突变改变氨基酸，使蛋白持续活化致癌。","移码突变多导致蛋白失活或结构严重异常。","同义突变不改变氨基酸序列，通常无表型效应。"]},{"id":"jyq_ch13_21","kind":"mcq","q":"癌细胞的基本特征是（）。","o":["A. 细胞分裂速度增快","B. 失去了运动和分裂的接触抑制，所以不能在琼脂中形成克隆","C. 肿瘤抑制基因表达增高","D. 具有浸润性和扩散性"],"a":"","src":"中国科学院，2005年","kp":null,"e":"癌细胞具有接触抑制丧失、黏附性降低及侵袭转移等特征，浸润性和扩散性是其基本特征，故选D。","oe":["癌细胞的异常在于增殖失控，未必比正常细胞分裂更快。","失去接触抑制反而易在琼脂中形成克隆，该说法错误。","肿瘤抑制基因表达通常降低或失活，而非增高。","正确，浸润性和扩散（转移）是癌细胞的基本特征。"]},{"id":"jyq_ch13_22","kind":"mcq","q":"与正常细胞相比，肿瘤细胞的细胞核出现异常时，不正确的是（）。","o":["A. 核质比例升高","B. 核结构呈现异型","C. 核仁rRNA转录活性降低","D. 核孔数目显著增加"],"a":"B","src":"军事医学科学院，2006年","kp":null,"e":"肿瘤细胞核仁增大、rRNA转录活性升高，故“核仁rRNA转录活性降低”这一说法不正确，应选C。","oe":["正确，肿瘤细胞核增大，核质比例升高。","正确，肿瘤细胞核形态不规则，呈明显异型性。","错误，肿瘤细胞核仁rRNA转录活性升高而非降低。","正确，肿瘤细胞核膜上核孔数目可显著增加。"]},{"id":"jyq_ch13_23","kind":"mcq","q":"癌基因与对应的原癌基因的产物蛋白（）。","o":["A. 种类一样，结构相同","B. 种类一样，结构不同","C. 种类不一样，结构不相同","D. 种类一样，结构不一定相同"],"a":"D","src":"南京师范大学，2008年","kp":null,"e":"癌基因由对应的原癌基因突变而来，二者所编码蛋白的种类相同，但因突变其结构不一定相同，故选D。","oe":["错误，突变后蛋白结构可能改变，并非完全相同。","错误，二者产物种类相同，结构可相同也可不同。","错误，癌基因与原癌基因编码的蛋白种类相同。","正确，产物种类相同，但结构不一定相同。"]},{"id":"jyq_ch13_24","kind":"short","q":"无论原癌基因还是抑癌基因一旦发生突变，所在的细胞都能被转化为癌细胞。为什么？","a":"原癌基因是可促进细胞增殖的正常基因，但是其功能获得性突变形式为癌基因，具有促进细胞发生癌变的能力，而抑癌基因是正常细胞增殖过程中的负调控因子，它编码的蛋白往往在细胞周期的检验点上起阻正周期进程的作用，它的突变失活易导致肿瘤的发生。","src":"湖北大学，2008年","kp":null},{"id":"jyq_ch13_25","kind":"short","q":"1978年，科学家发现了p53是癌症基因（oncogene），10年后，科学家在研究结肠癌发生过程中证明p53是抑癌基因（tumorsuppressor），请简述p53在细胞生物学中的已知功能，并说明你的意见，p53究竟是癌基因还是抑癌基因？","a":"1978年，SV40病毒感染细胞后，p53发现与Tantigen结合，Tantigen的结合是使p53失活，所以认为p53具有转化细胞或肿瘤细胞的功能是一个误解。1988年，科学家在结肠癌研究时发现：两个p53等位基因总是一起缺失或突变，引发了p53丧失会导致癌变的新观念。p53抑癌基因。该基因编码一种相对分子质量为53kDa的蛋白质，命名为p53。p53基因的失活对肿瘤形成起重要作用。p53蛋白主要集中于核仁区，能与DNA特异结合，其活性受磷酸化调控。正常p53的生物功能好似“基因组卫士（guardianofthegenome）”，在G，期检查DNA损伤点，监视基因组的完整性。胞凋亡；如果p53基因的两个拷贝都发生了突变，对细胞的增殖失去控制，导致细胞癌变。p53具有抑制肿瘤血管生成，有效防止肿瘤的复发、转移，提高人体自身的免疫功能。","src":"中国科学院，2008年","kp":null},{"id":"jyq_ch13_26","kind":"short","q":"为何缺少功能性p53基因的肿瘤（如黑色素瘤，结肠癌等）患者，放疗和化疗的治疗效果不明显？","a":"p53是目前人类发现的一种最主要的抑癌基因，超过一半的肿瘤的发生都与p53的基因突变有关。p53就相当于一名分子警察，在不同的外界刺激下，启动不同的程序。即当DNA受到不可修复的损伤时，p53通过启动让细胞凋亡的程序，使细胞进行死亡；当DNA所受到损伤比较弱时，p53便启动细胞周期阻滞程序，阻止细胞分裂，再对受损DNA进行修复，从而防止有缺陷的遗传物质传递到子代细胞。所以缺少功能性p53基因的肿瘤（如黑色素瘤，结肠癌等）患者，放疗和化疗的治疗效果不明显。","src":"武汉大学，2009年","kp":null},{"id":"jyq_ch13_27","kind":"short","q":"癌细胞的增殖有何特征？为什么说癌症的发生是基因突变逐渐积累的结果。最近，德国科学家找到一种能够让癌细胞“自杀”的核酶，请问什么是核酶？你认为还有哪些新方案可以治疗癌症？","a":"癌细胞具有无限的增殖能力，分裂速度快。癌症的发生是基因突变逐渐积累的结果：根据DNA复制过程中的基因突变率及人的一生中细胞分裂次数推测，在人的一生中，其基因组中每个基因都可能发生10-次的突变。如果再考虑生活环境中的致癌因素（如辐射等物理因素，化学诱变剂等化学因素和肿瘤病毒感染臻物考研肿瘤的发生频率极低。第十四章细胞增殖调控与癌细胞根据大量的病例分析，癌症的发生一般并不是单一基因的突变，而至少在一个细胞中发生5～6个基因突变，才能赋予癌细胞所有特征，即癌细胞不仅增殖速度快，而且其子代细胞能够逃脱细胞衰老的命运，生长。因此细胞基因组中产生与肿瘤发生相关的某一原癌基因的突变，并非马上形成癌，而是继续生长直至细胞群系中新的偶发突变的产生。癌症治疗的新方法：研究人员用所谓的“碳化氢钉针”技术将一个起稳定作用的小分子化合物植入一个试验性癌症药物，提高了该药物促进白血病细胞自杀的效果。这项新的研究发现，用小分子稳定住的肽药物降低了移植到小鼠上的人类肿瘤的增长。一篇相关的研究评述指出，将非天然氨基酸准确地添加到用全天然氨基酸制造的具有生物活性的肽中，能帮助避免这类肽药物的一些常见端，包括药效低、不稳定以及将药物送到细胞的效率低等。人们认为，了解细胞凋亡调节的细节可能对发现更有效的癌症药物有用，这项研究为此提供了一些希望。随着人类对人类自身免疫系统如何防范和抵抗癌细胞侵入机制认识的不断加深，医疗科研人员对运用免疫疗法治疗癌症病魔的信心和动力也愈发加强，其中运用单克隆抗体来征服癌症是一种新兴的治疗方法。癌症免疫疗法也就是通过激活和加强人体自身免疫系统来抵御癌细胞的“人侵”。运用单克隆抗体来治疗癌症，就是运用人工培养的单克隆抗体来加强人体自身免疫系统的机能，因为人工培养与人体自身产生的单克隆抗体在抗击癌细胞的功能上是一致的。","src":"华中科大，2006年","kp":null},{"id":"jyq_ch13_28","kind":"short","q":"基因差次表达（genedifferentialexpression）","a":"也称基因的顺序表达，是决定细胞特殊性状的基因（奢侈基因）按一定顺序相继活化表达的现象。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch13_29","kind":"mcq","q":"人在不同发育阶段红细胞所含的血红蛋白不同，这是由于（）。","o":["A. 结合的血红素不同","B. 珠蛋白基因的转录本进行不同修饰","C. 珠蛋白的不同加工","D. 珠蛋白基因按程序开启和关闭"],"a":"D","src":"南京师范大学，2009年","kp":null,"e":"人在不同发育阶段红细胞中血红蛋白不同，是珠蛋白基因按发育程序依次开启与关闭的结果，故选D。","oe":["错误，各型血红蛋白的血红素相同，差别在珠蛋白。","错误，主要差异并非转录本的不同修饰所致。","错误，并非同一前体经不同加工所产生。","正确，珠蛋白基因按发育程序有序开启和关闭。"]},{"id":"jyq_ch13_30","kind":"short","q":"复制衰老的可能机制是什么？","a":"答在体细胞中，由于缺乏端粒酶，随着细胞分裂次数增多，端粒逐渐缩短。端粒的缩短使细胞中的p53含量明显增加并且活化，继而诱导p21的表达，抑制CDK活化，使得Rb不能被磷酸化，E2F处于持续失活状态，最终引发细胞的衰老。","src":"姜益泉《辅导与习题集》","kp":null}],"outline":["癌细胞基本特征","癌基因与原癌基因","抑癌基因(p53/Rb)","增殖调控失控","浸润与转移"],"outlineMap":[0,0,3,0,7]};